  // ============================================
  // DATA SCHEMA VERSION MANAGEMENT
  // ============================================
  const SCHEMA_VERSION = '2.0.0';
  
  const StorageManager = {
    /**
     * Get item with version check
     * @param {string} key - Storage key
     * @param {*} defaultValue - Default if not found or corrupted
     * @returns {*} Parsed data or default
     */
    get(key, defaultValue) {
      try {
        const raw = localStorage.getItem(key);
        if (!raw) return defaultValue;
        
        const parsed = JSON.parse(raw);
        
        // Check if data has version metadata
        if (parsed && parsed.__schema_version) {
          if (parsed.__schema_version !== SCHEMA_VERSION) {
            console.warn('⚠️ Data schema mismatch for', key, 
                        '- expected', SCHEMA_VERSION, 
                        'got', parsed.__schema_version,
                        '- using default');
            return defaultValue;
          }
          return parsed.__data !== undefined ? parsed.__data : defaultValue;
        }
        
        // Legacy data without version - attempt migration
        console.log('📦 Migrating legacy data for', key);
        return parsed;
      } catch(e) {
        console.error('❌ Failed to parse stored data for', key, ':', e.message);
        return defaultValue;
      }
    },
    
    /**
     * Set item with version wrapper
     * @param {string} key - Storage key
     * @param {*} data - Data to store
     */
    set(key, data) {
      try {
        const wrapped = {
          __schema_version: SCHEMA_VERSION,
          __timestamp: Date.now(),
          __data: data
        };
        localStorage.setItem(key, JSON.stringify(wrapped));
      } catch(e) {
        console.error('❌ Failed to save data for', key, ':', e.message);
        // If quota exceeded, try to clear old data
        if (e.name === 'QuotaExceededError') {
          console.warn('⚠️ Storage quota exceeded, clearing old data...');
          this.clearOldData();
          try {
            localStorage.setItem(key, JSON.stringify(wrapped));
          } catch(e2) {
            console.error('❌ Still cannot save after clearing');
          }
        }
      }
    },
    
    /**
     * Remove item
     */
    remove(key) {
      try {
        localStorage.removeItem(key);
      } catch(e) {
        console.error('Failed to remove', key, ':', e.message);
      }
    },
    
    /**
     * Clear old/unused data to free space
     */
    clearOldData() {
      const keysToKeep = [
        CONFIG.STORAGE_KEYS.WATCHLIST,
        CONFIG.STORAGE_KEYS.ALERTS,
        CONFIG.STORAGE_KEYS.SETTINGS,
        CONFIG.STORAGE_KEYS.DRAWINGS,
        CONFIG.STORAGE_KEYS.POSITIONS,
        'tvp_session',
        'tvp_pine_script',
        'tvp_indicator_settings',
        'tvp_indicator_templates',
        'tvp_theme',
        'tvp_tour_completed',
        'tvp_fcm_token',
        'tvp_fcm_enabled'
      ];
      
      const allKeys = [];
      for (let i = 0; i < localStorage.length; i++) {
        allKeys.push(localStorage.key(i));
      }
      
      let cleared = 0;
      for (let i = 0; i < allKeys.length; i++) {
        const key = allKeys[i];
        if (!keysToKeep.includes(key) && key.startsWith('tvp_')) {
          localStorage.removeItem(key);
          cleared++;
        }
      }
      
      console.log('🧹 Cleared', cleared, 'old storage items');
    }
  };
