// ============================================
// MOBILE LAYOUT FIX - Ensures proper chart distribution
// ============================================
const MobileLayoutFix = {
  init() {
    if (window.innerWidth > 768) return;
    this.ensureLayout();
    
    // Listen for indicator changes
    const container = document.getElementById('indicator-panes-container');
    if (container) {
      const observer = new MutationObserver(() => this.ensureLayout());
      observer.observe(container, { childList: true, subtree: false });
    }
    
    window.addEventListener('resize', () => setTimeout(() => this.ensureLayout(), 100));
  },
  
  ensureLayout() {
    const chartContainer = document.getElementById('chart-container');
    const mainPane = document.getElementById('main-chart-pane');
    const volumePane = document.getElementById('volume-chart-pane');
    const indContainer = document.getElementById('indicator-panes-container');
    
    if (!chartContainer || !mainPane) return;
    
    // Force volume pane to have fixed height
    if (volumePane) {
      volumePane.style.flex = '0 0 80px';
      volumePane.style.minHeight = '80px';
      volumePane.style.maxHeight = '80px';
      volumePane.style.height = '80px';
    }
    
    // Count visible indicator panes
    const indicatorPanes = indContainer ? indContainer.querySelectorAll('.chart-pane-indicator') : [];
    const hasIndicators = indicatorPanes.length > 0;
    
    if (hasIndicators) {
      // When indicators exist, distribute space
      indContainer.style.display = 'flex';
      indContainer.style.flex = '1 1 auto';
      indContainer.style.maxHeight = '40%';
      indContainer.style.overflowY = 'auto';
      
      // Give main chart remaining space
      mainPane.style.flex = '1 1 auto';
      mainPane.style.minHeight = '200px';
    } else {
      // When no indicators, main chart takes all except volume
      indContainer.style.display = 'none';
      mainPane.style.flex = '1 1 auto';
      mainPane.style.minHeight = '250px';
    }
    
    // Force resize after layout change
    if (typeof ChartEngine !== 'undefined' && ChartEngine.resizeAll) {
      setTimeout(() => ChartEngine.resizeAll(), 50);
    }
    
    // Force redraw of volume chart
    if (typeof ChartEngine !== 'undefined' && ChartEngine.charts && ChartEngine.charts.volume) {
      const volumeEl = document.getElementById('volume-chart');
      if (volumeEl && volumeEl.clientWidth > 0) {
        ChartEngine.charts.volume.resize(volumeEl.clientWidth, 80);
      }
    }
  }
};
	
// ============================================
// INTERVAL MANAGER - Prevents timer leaks
// All intervals must be registered here
// ============================================
const IntervalManager = {
  _intervals: [],
  _timeouts: [],
  
  /**
   * Register a setInterval - use this instead of raw setInterval
   * @param {Function} fn - Function to call
   * @param {number} ms - Interval in milliseconds
   * @param {string} label - Description for debugging
   * @returns {number} Interval ID
   */
  register(fn, ms, label) {
    const id = setInterval(fn, ms);
    this._intervals.push({ id, label, ms });
    console.log(`⏱️ Interval registered: ${label} (${ms}ms) - Total: ${this._intervals.length}`);
    return id;
  },
  
  /**
   * Register a setTimeout - use this instead of raw setTimeout for recurring timeouts
   * @param {Function} fn - Function to call
   * @param {number} ms - Delay in milliseconds
   * @param {string} label - Description for debugging
   * @returns {number} Timeout ID
   */
  registerTimeout(fn, ms, label) {
    const id = setTimeout(fn, ms);
    this._timeouts.push({ id, label, ms });
    return id;
  },
  
  /**
   * Clear a specific interval
   * @param {number} id - Interval ID to clear
   */
  clear(id) {
    clearInterval(id);
    this._intervals = this._intervals.filter(function(item) { return item.id !== id; });
    clearTimeout(id); // Also try as timeout
    this._timeouts = this._timeouts.filter(function(item) { return item.id !== id; });
  },
  
  /**
   * Clear ALL registered intervals and timeouts
   * Call this before re-initialization
   */
  clearAll() {
    console.log(`🧹 Clearing ${this._intervals.length} intervals and ${this._timeouts.length} timeouts`);
    
    this._intervals.forEach(function(item) {
      clearInterval(item.id);
      console.log(`  ⏹️ Cleared: ${item.label}`);
    });
    
    this._timeouts.forEach(function(item) {
      clearTimeout(item.id);
      console.log(`  ⏹️ Cleared timeout: ${item.label}`);
    });
    
    this._intervals = [];
    this._timeouts = [];
  },
  
  /**
   * Get current count of active intervals
   * @returns {object} Counts
   */
  getStats() {
    return {
      intervals: this._intervals.length,
      timeouts: this._timeouts.length,
      list: this._intervals.map(function(item) { return item.label + ' (' + item.ms + 'ms)'; })
    };
  }
};
