  const sellPriceEl = document.getElementById('chart-sell-price');
  if (buyPriceEl) buyPriceEl.textContent = U.formatPrice(p);
  if (sellPriceEl) sellPriceEl.textContent = U.formatPrice(p);
  
  // Update mobile price display
