// MARKET OVERVIEW MANAGER - DYNAMIC ASSETS
// ============================================
const MarketOverview = {
  async init() {
    await this.fetchMarketData();
    setInterval(() => this.fetchMarketData(), 60000);
    
    // Listen for symbol changes to refresh
    const originalSwitchSymbol = DataManager.switchSymbol.bind(DataManager);
    DataManager.switchSymbol = async (symbol) => {
      await originalSwitchSymbol(symbol);
      await this.fetchMarketData();
    };
  },
  
  async fetchMarketData() {
    const assetType = STATE.assetType || 'crypto';
    
    if (assetType === 'crypto') {
      await this.fetchCryptoMarketData();
    } else if (assetType === 'stocks') {
      await this.fetchStockMarketData();
    } else if (assetType === 'forex') {
      await this.fetchForexMarketData();
    }
  },
  
    async fetchCryptoMarketData() {
    try {
      var self = this;
      
      // Rate limited CoinGecko call (max every 60 seconds)
      U.rateLimiter.schedule('coingecko_global', async function() {
        try {
          var res = await fetch('https://api.coingecko.com/api/v3/global');
          if (res.ok) {
            var data = await res.json();
            var btcDominance = data.data.market_cap_percentage.btc;
            var totalMarketCap = data.data.total_market_cap.usd;
            var totalVolume = data.data.total_volume.usd;
            var ethDominance = data.data.market_cap_percentage.eth;
            
            self.updateElement('btc-dominance', btcDominance.toFixed(1) + '%');
            self.updateElement('total-marketcap', self.formatLargeNumber(totalMarketCap));
            self.updateElement('total-volume', self.formatLargeNumber(totalVolume));
            
            var ethDomEl = document.getElementById('eth-dominance');
            if (ethDomEl) ethDomEl.textContent = ethDominance.toFixed(1) + '%';
          }
        } catch(e) {
          ErrorHandler.handle(e, 'MarketOverview.CoinGecko', 'warning');
        }
      }, 60000, true);
      
      // Rate limited Fear & Greed call (max every 60 seconds)
      U.rateLimiter.schedule('fear_greed', async function() {
        try {
          var fgRes = await fetch('https://api.alternative.me/fng/?limit=1');
          if (fgRes.ok) {
            var fgData = await fgRes.json();
            var value = fgData.data[0].value;
            var classification = fgData.data[0].value_classification;
            
            var fearEl = document.getElementById('fear-greed');
            if (fearEl) {
              fearEl.innerHTML = value + ' <span style="font-size:10px;color:var(--text-muted);">(' + classification + ')</span>';
              var numValue = parseInt(value);
              if (numValue <= 25) fearEl.style.color = '#ef5350';
              else if (numValue >= 75) fearEl.style.color = '#26a69a';
              else fearEl.style.color = '#ff9800';
            }
          }
        } catch(e) {
          ErrorHandler.handle(e, 'MarketOverview.FearGreed', 'warning');
        }
      }, 60000, true);
      
    } catch (e) {
      ErrorHandler.handle(e, 'MarketOverview.fetchCryptoMarketData', 'warning');
      this.setFallbackValues('crypto');
    }
  },
  
  async fetchStockMarketData() {
    try {
      // Fetch US market data from Finnhub
      const res = await fetch(`https://finnhub.io/api/v1/quote?symbol=SPY&token=${CONFIG.FINNHUB_API_KEY}`);
      
      if (res.ok) {
        const spyData = await res.json();
        const spyPrice = spyData.c || 0;
        const spyChange = spyData.dp || 0;
        
        // Also get market news sentiment
        const newsRes = await fetch(`https://finnhub.io/api/v1/news?category=general&token=${CONFIG.FINNHUB_API_KEY}`);
        const newsData = newsRes.ok ? await newsRes.json() : [];
        const sentimentScore = newsData.length > 0 ? Math.min(80, 50 + newsData.length) : 50;
        
        this.updateElement('btc-dominance', 'S&P 500');
        this.updateElement('total-marketcap', '$' + U.formatPrice(spyPrice));
        this.updateElement('total-volume', spyChange >= 0 ? '+' + spyChange.toFixed(2) + '%' : spyChange.toFixed(2) + '%');
        this.updateElement('fear-greed', sentimentScore + ' (Sentiment)');
        
        // Color the fear greed element based on sentiment
        const fearEl = document.getElementById('fear-greed');
        if (fearEl) {
          if (sentimentScore <= 30) fearEl.style.color = '#ef5350';
          else if (sentimentScore >= 70) fearEl.style.color = '#26a69a';
          else fearEl.style.color = '#ff9800';
        }
      } else {
        this.setFallbackValues('stocks');
      }
    } catch (e) {
      console.error('Stock market data fetch error:', e);
      this.setFallbackValues('stocks');
    }
  },
  
  async fetchForexMarketData() {
    try {
      // Fetch major forex rates from Twelve Data
      const pairs = ['EUR/USD', 'GBP/USD', 'USD/JPY', 'USD/CHF'];
      const pair = pairs[0]; // Use EUR/USD as benchmark
      
      const res = await fetch(`${CONFIG.TWELVEDATA_BASE}/quote?symbol=${pair}&apikey=${CONFIG.TWELVEDATA_API_KEY}`);
      
      if (res.ok) {
        const data = await res.json();
        const price = parseFloat(data.close || 0);
        const change = parseFloat(data.percent_change || 0);
        
        this.updateElement('btc-dominance', 'EUR/USD');
        this.updateElement('total-marketcap', U.formatPrice(price));
        this.updateElement('total-volume', (change >= 0 ? '+' : '') + change.toFixed(2) + '%');
        
        // DXY (Dollar Index) as fear/greed proxy for forex
        const dxyRes = await fetch(`${CONFIG.TWELVEDATA_BASE}/quote?symbol=DXY&apikey=${CONFIG.TWELVEDATA_API_KEY}`);
        if (dxyRes.ok) {
          const dxyData = await dxyRes.json();
          const dxyPrice = parseFloat(dxyData.close || 100);
          const dxyStrength = Math.min(80, Math.max(20, Math.round((dxyPrice - 90) * 2 + 50)));
          
          this.updateElement('fear-greed', dxyStrength + ' (DXY)');
          
          const fearEl = document.getElementById('fear-greed');
          if (fearEl) {
            if (dxyStrength <= 30) fearEl.style.color = '#26a69a'; // Weak dollar = risk on
            else if (dxyStrength >= 70) fearEl.style.color = '#ef5350'; // Strong dollar = risk off
            else fearEl.style.color = '#ff9800';
          }
        } else {
          this.updateElement('fear-greed', '--');
        }
      } else {
        this.setFallbackValues('forex');
      }
    } catch (e) {
      console.error('Forex market data fetch error:', e);
      this.setFallbackValues('forex');
    }
  },
  
  async fetchFearGreed() {
    try {
      const res = await fetch('https://api.alternative.me/fng/?limit=1');
      
      if (res.ok) {
        const data = await res.json();
        const value = data.data[0].value;
        const classification = data.data[0].value_classification;
        
        const fearEl = document.getElementById('fear-greed');
        if (fearEl) {
          fearEl.innerHTML = `${value} <span style="font-size:10px;color:var(--text-muted);">(${classification})</span>`;
          
          const numValue = parseInt(value);
          if (numValue <= 25) fearEl.style.color = '#ef5350';
          else if (numValue >= 75) fearEl.style.color = '#26a69a';
          else fearEl.style.color = '#ff9800';
        }
      }
    } catch (e) {
      const fearEl = document.getElementById('fear-greed');
      if (fearEl) fearEl.textContent = '--';
    }
  },
  
  updateElement(id, value) {
    const el = document.getElementById(id);
    if (el) el.textContent = value;
  },

  formatLargeNumber(num) {
    if (!num) return '--';
    if (num >= 1e12) return '$' + (num / 1e12).toFixed(2) + 'T';
    if (num >= 1e9) return '$' + (num / 1e9).toFixed(2) + 'B';
    if (num >= 1e6) return '$' + (num / 1e6).toFixed(2) + 'M';
    return '$' + num.toFixed(2);
  },
  
  setFallbackValues(type) {
    this.updateElement('btc-dominance', '--%');
    this.updateElement('total-marketcap', '--');
    this.updateElement('total-volume', '--');
    this.updateElement('fear-greed', '--');
  }
};


