  /**
   * Place testnet order (simulated with real market data)
   */
  async placeTestnetOrder(side, quantity, price) {
    if (!this.testnetMode) return null;
    
    var order = {
      id: U.genId(),
      symbol: STATE.symbol,
      side: side.toUpperCase(),
      type: this.orderType === 'market' ? 'MARKET' : 'LIMIT',
      price: price,
      quantity: quantity,
      timestamp: Date.now(),
      status: 'FILLED',
      testnet: true
    };
    
    // Simulate small delay like real API
    await new Promise(function(resolve) { setTimeout(resolve, 300); });
    
    console.log('🧪 Testnet Order Executed:', order);
    
    if (typeof Toast !== 'undefined') {
      Toast.success('🧪 Testnet: ' + side.toUpperCase() + ' ' + quantity + ' @ $' + U.formatPrice(price));
    }
    
    return order;
  },
// OCO Order (One-Cancels-Other / Bracket Order)
async placeOCOOrder(side, quantity, price, stopPrice, limitPrice) {
  const position = {
    id: U.genId(),
    symbol: STATE.symbol,
    side: side,
    entryPrice: price,
    amount: quantity,
    stopLoss: stopPrice,
    takeProfit: limitPrice,
    type: 'OCO',
    status: 'open',
    entryTime: Date.now(),
    leverage: this.leverage,
    notional: price * quantity,
    margin: this.leverage > 1 ? (price * quantity) / this.leverage : price * quantity,
    pnl: 0,
    pnlPercent: 0
  };
  
  STATE.positions.push(position);
  this.savePositions();
  this.renderPositions();
  
  if (typeof Toast !== 'undefined') {
    Toast.success('OCO Order placed: SL @ $' + U.formatPrice(stopPrice) + ' | TP @ $' + U.formatPrice(limitPrice));
  }
  
  return position;
},

// Liquidation calculator
calculateLiquidation(entryPrice, leverage, side) {
  if (leverage <= 1) return null;
  
  const marginRatio = 1 / leverage;
  let liqPrice;
  
  if (side === 'long') {
    liqPrice = entryPrice * (1 - marginRatio * 0.9);
  } else {
    liqPrice = entryPrice * (1 + marginRatio * 0.9);
  }
  
  const distancePercent = Math.abs((liqPrice - entryPrice) / entryPrice) * 100;
  
  return {
    price: liqPrice,
    distancePercent: distancePercent.toFixed(2),
    warning: distancePercent < 5 ? '⚠️ High risk - liquidation close' : 
             distancePercent < 10 ? '⚡ Moderate risk' : '✅ Safe distance'
  };
},
  
  // ============================================
  // DATA PERSISTENCE
  // ============================================
  loadAccount() {
    const saved = localStorage.getItem('tvp_account');
    if (saved) {
      const data = JSON.parse(saved);
      this.account = { ...this.account, ...data };
    }
  },
  
  saveAccount() {
    localStorage.setItem('tvp_account', JSON.stringify(this.account));
  },
  
 loadPositions() {    
	const saved = localStorage.getItem(CONFIG.STORAGE_KEYS.POSITIONS);
    if (saved) {
      try {
        STATE.positions = JSON.parse(saved);
        // FIX: Ensure positions is always an array
        if (!Array.isArray(STATE.positions)) {
          console.warn('⚠️ Positions data corrupted, resetting');
          STATE.positions = [];
        }
        STATE.positions = STATE.positions.filter(p => p && p.id && p.symbol);
        STATE.positions.forEach(p => {
          if (!p.side) p.side = (p.type === 'buy') ? 'long' : 'short';
          if (!p.leverage) p.leverage = 1;
          if (!p.margin) p.margin = (p.entryPrice || 0) * (p.amount || 0) / (p.leverage || 1);
          if (!p.status) p.status = 'open';
        });
      } catch(e) {
        console.error('Error loading positions, resetting:', e);
        STATE.positions = [];
      }
    } else {
      STATE.positions = [];
    }
  },
  
  savePositions() {
    StorageManager.set(CONFIG.STORAGE_KEYS.POSITIONS, STATE.positions);
  },
  
  loadOrderHistory() {
    const saved = localStorage.getItem('tvp_order_history');
    if (saved) this.orderHistory = JSON.parse(saved);
    else this.orderHistory = [];
  },
  
  saveOrderHistory() {
    // Keep last 500 orders
    if (this.orderHistory.length > 500) {
      this.orderHistory = this.orderHistory.slice(-500);
    }
    localStorage.setItem('tvp_order_history', JSON.stringify(this.orderHistory));
  },
  
