    var dashWinrate = document.getElementById('dashboard-winrate');
    var dashTotal = document.getElementById('dashboard-total');
    
    // Balance
    if (dashBalance) {
      dashBalance.textContent = '$' + U.formatPrice(this.account.balance);
    }
    
    // Total P&L
    if (dashPnl) {
      var pnl = this.account.totalPnl;
      var sign = pnl >= 0 ? '+' : '';
      dashPnl.textContent = sign + '$' + U.formatNum(Math.abs(pnl), 2);
      dashPnl.style.color = pnl >= 0 ? 'var(--up-color)' : 'var(--down-color)';
    }
    
    // Open positions count
    if (dashOpen) {
      var openCount = STATE.positions ? STATE.positions.length : 0;
      dashOpen.textContent = openCount;
    }
    
    // Win rate
    if (dashWinrate && this.account.totalTrades > 0) {
      var winRate = ((this.account.winningTrades / this.account.totalTrades) * 100).toFixed(1);
      dashWinrate.textContent = winRate + '%';
      if (winRate >= 60) dashWinrate.style.color = 'var(--up-color)';
      else if (winRate >= 40) dashWinrate.style.color = 'var(--warning)';
      else dashWinrate.style.color = 'var(--down-color)';
    }
    
    // Total trades
    if (dashTotal) {
      dashTotal.textContent = this.account.totalTrades;
    }
    
    // Position count
