  // ============================================
  // EXPORT TRADE HISTORY
  // ============================================
  exportHistory() {
    if (!this.orderHistory || this.orderHistory.length === 0) {
      Toast.info('No trade history to export');
      return;
    }
    
    // Build CSV
    var headers = ['Date', 'Symbol', 'Action', 'Side', 'Price', 'Amount', 'Leverage', 'PnL', 'PnL%', 'Order Type'];
    var rows = this.orderHistory.map(function(o) {
      return [
        new Date(o.timestamp).toISOString(),
        o.symbol,
        o.action || 'trade',
        o.side || '',
        o.entryPrice || o.price || '',
        o.amount || '',
        o.leverage || '1',
        o.pnl ? o.pnl.toFixed(2) : '',
        o.pnlPercent ? o.pnlPercent.toFixed(2) + '%' : '',
        o.orderType || ''
      ].join(',');
    });
    
    var csv = headers.join(',') + '\n' + rows.join('\n');
    
    // Download
    var blob = new Blob([csv], { type: 'text/csv' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'tradevision_trades_' + new Date().toISOString().slice(0, 10) + '.csv';
    a.click();
    URL.revokeObjectURL(url);
    
    Toast.success('Trade history exported to CSV');
  },
  
