    if (amountInput) amountInput.value = '';
    if (totalInput) document.getElementById('trade-total-input').value = '';
    
    const symbol = STATE.symbol.replace('USDT', '');
    const sideText = this.tradeType === 'buy' ? 'BUY' : 'SELL';
    const leverageText = this.leverage > 1 ? ` ${this.leverage}x` : '';
    
    Toast.success(`${sideText}${leverageText}: ${amount} ${symbol} @ $${U.formatPrice(execPrice)}`);
    
