  // ============================================
  // RISK MANAGER - Professional Risk Analytics
  // Institutional-grade position sizing and risk metrics
  // ============================================
  const RiskManager = {
    /**
     * Calculate optimal position size using Kelly Criterion
     * @param {number} accountBalance - Available capital
     * @param {number} winRate - Historical win rate (0-1)
     * @param {number} avgWin - Average winning trade amount
     * @param {number} avgLoss - Average losing trade amount
     * @param {number} riskPercent - Max risk per trade (default 2%)
     * @returns {Object} Position sizing recommendation
     */
    calculateKellyPosition(accountBalance, winRate, avgWin, avgLoss, riskPercent) {
      const riskPct = riskPercent || 0.02; // 2% default
      
      if (avgLoss <= 0) {
        return {
          kellyPercent: 0,
          optimalSize: 0,
          recommendation: 'Cannot calculate - no loss data',
          riskAmount: accountBalance * riskPct
        };
      }
      
      // Kelly formula: f* = (bp - q) / b
      // b = win/loss ratio, p = win rate, q = loss rate
      const b = avgWin / avgLoss;
      const p = winRate;
      const q = 1 - p;
      const kellyPercent = (b * p - q) / b;
      
      // Conservative: use half-Kelly
      const halfKelly = Math.max(0, kellyPercent * 0.5);
      
      // Risk-based position sizing (more conservative)
      const riskAmount = accountBalance * riskPct;
      const kellySize = accountBalance * halfKelly;
      const optimalSize = Math.min(riskAmount, kellySize);
      
      let recommendation;
      if (kellyPercent <= 0) {
        recommendation = '⚠️ Negative edge - Do not trade';
      } else if (kellyPercent < 0.05) {
        recommendation = '🔸 Small edge - Reduce size by 50%';
      } else if (kellyPercent < 0.15) {
        recommendation = '✅ Decent edge - Standard sizing';
      } else if (kellyPercent < 0.25) {
        recommendation = '🟢 Strong edge - Consider full size';
      } else {
        recommendation = '⭐ Exceptional edge - Maximum allocation';
      }
      
      return {
        kellyPercent: (kellyPercent * 100).toFixed(2) + '%',
        halfKellyPercent: (halfKelly * 100).toFixed(2) + '%',
        optimalSize: optimalSize,
        riskAmount: riskAmount,
        recommendation: recommendation,
        riskPerTrade: riskPct
      };
    },
    
    /**
     * Calculate Value at Risk (VaR) for current portfolio
     * @param {Array} positions - Open positions
     * @param {number} confidence - Confidence level (default 0.95 = 95%)
     * @returns {Object} VaR metrics
     */
    calculateVaR(positions, confidence) {
      const confLevel = confidence || 0.95;
      const zScores = { 0.90: 1.28, 0.95: 1.645, 0.99: 2.33 };
      const zScore = zScores[confLevel] || 1.645;
      
      if (!positions || positions.length === 0) {
        return {
          var: 0,
          varPercent: 0,
          cvar: 0,
          maxDrawdown: 0,
          message: 'No open positions'
        };
      }
      
      // Calculate portfolio volatility weighted by position size
      let totalValue = 0;
      let weightedVol = 0;
      let maxPotentialLoss = 0;
      
      for (let i = 0; i < positions.length; i++) {
        const pos = positions[i];
        const positionValue = (pos.entryPrice || 0) * (pos.amount || 0);
        totalValue += positionValue;
        
        // Estimate volatility from recent candles
        if (STATE.candles && STATE.candles.length > 20) {
          const recentCandles = STATE.candles.slice(-20);
          const returns = [];
          for (let j = 1; j < recentCandles.length; j++) {
            returns.push(
              (recentCandles[j].close - recentCandles[j-1].close) / 
              recentCandles[j-1].close
            );
          }
          
          const avgReturn = returns.reduce(function(a, b) { return a + b; }, 0) / returns.length;
          const variance = returns.reduce(function(a, b) { 
            return a + Math.pow(b - avgReturn, 2); 
          }, 0) / returns.length;
          const volatility = Math.sqrt(variance);
          
          weightedVol += positionValue * volatility;
        }
        
        // Maximum potential loss (price going to zero)
        if (pos.side === 'long') {
          maxPotentialLoss += positionValue;
        }
      }
      
      const portfolioVol = totalValue > 0 ? weightedVol / totalValue : 0;
      
      // Daily VaR
      const dailyVaR = totalValue * portfolioVol * zScore;
      const dailyVaRPercent = totalValue > 0 ? (dailyVaR / totalValue) * 100 : 0;
      
      // Conditional VaR (expected loss beyond VaR - simplified)
      const cvar = dailyVaR * 1.4; // Approximate CVaR as 1.4x VaR
      
      return {
        totalPortfolioValue: totalValue,
        dailyVolatility: (portfolioVol * 100).toFixed(2) + '%',
        var: dailyVaR,
        varPercent: dailyVaRPercent.toFixed(2) + '%',
        varLabel: '1-Day VaR (' + (confLevel * 100) + '%)',
        cvar: cvar,
        cvarPercent: (cvar / totalValue * 100).toFixed(2) + '%',
        cvarLabel: 'Expected Shortfall',
        maxPotentialLoss: maxPotentialLoss,
        stressTest: maxPotentialLoss > 0 ? 
          'Worst case: -$' + U.formatLargeNum(maxPotentialLoss) : 'No stress detected',
        positionCount: positions.length
      };
    },
    
    /**
     * Calculate Sharpe Ratio for account performance
     * @param {Array} tradeHistory - Array of closed trades with PnL
     * @param {number} riskFreeRate - Risk-free rate (default 0.04 = 4%)
     * @returns {Object} Sharpe ratio and interpretation
     */
    calculateSharpeRatio(tradeHistory, riskFreeRate) {
      const rfRate = riskFreeRate || 0.04;
      
      if (!tradeHistory || tradeHistory.length < 5) {
        return {
          sharpe: 0,
          annualizedSharpe: 0,
          interpretation: 'Insufficient trade history (need 5+ trades)',
          tradeCount: tradeHistory ? tradeHistory.length : 0
        };
      }
      
      // Calculate periodic returns
      const returns = [];
      for (let i = 0; i < tradeHistory.length; i++) {
        if (tradeHistory[i].pnlPercent !== undefined) {
          returns.push(tradeHistory[i].pnlPercent / 100); // Convert to decimal
        }
      }
      
      if (returns.length === 0) {
        return { sharpe: 0, interpretation: 'No return data', tradeCount: 0 };
      }
      
      // Average return
      const avgReturn = returns.reduce(function(a, b) { return a + b; }, 0) / returns.length;
      
      // Standard deviation
      const variance = returns.reduce(function(a, b) { 
        return a + Math.pow(b - avgReturn, 2); 
      }, 0) / returns.length;
      const stdDev = Math.sqrt(variance);
      
      // Sharpe ratio
      const sharpe = stdDev > 0 ? (avgReturn - rfRate / 252) / stdDev : 0;
      
      // Annualized (assuming daily trades, multiply by sqrt(252))
      const annualizedSharpe = sharpe * Math.sqrt(252);
      
      let interpretation;
      if (annualizedSharpe < 0) interpretation = '❌ Negative - Losing strategy';
      else if (annualizedSharpe < 0.5) interpretation = '⚠️ Poor - Below market average';
      else if (annualizedSharpe < 1.0) interpretation = '🔸 Average - Market-like returns';
      else if (annualizedSharpe < 2.0) interpretation = '✅ Good - Above average';
      else if (annualizedSharpe < 3.0) interpretation = '🟢 Excellent - Strong strategy';
      else interpretation = '⭐ Outstanding - World-class performance';
      
      return {
        sharpe: sharpe.toFixed(4),
        annualizedSharpe: annualizedSharpe.toFixed(2),
        interpretation: interpretation,
        avgReturn: (avgReturn * 100).toFixed(2) + '%',
        volatility: (stdDev * 100).toFixed(2) + '%',
        tradeCount: returns.length
      };
    },
    
    /**
     * Generate comprehensive risk report
     */
    generateRiskReport() {
      const account = TradeManager.account;
      const positions = STATE.positions || [];
      const closedTrades = TradeManager.orderHistory ? 
        TradeManager.orderHistory.filter(function(t) { 
          return t.action === 'close' || t.action === 'partial_close'; 
        }) : [];
      
      // Win rate
      const totalTrades = closedTrades.length;
      const winningTrades = closedTrades.filter(function(t) { 
        return (t.pnl || 0) > 0; 
      }).length;
      const winRate = totalTrades > 0 ? winningTrades / totalTrades : 0;
      
      // Average win/loss
      const wins = closedTrades.filter(function(t) { return (t.pnl || 0) > 0; });
      const losses = closedTrades.filter(function(t) { return (t.pnl || 0) < 0; });
      const avgWin = wins.length > 0 ? 
        wins.reduce(function(s, t) { return s + (t.pnl || 0); }, 0) / wins.length : 0;
      const avgLoss = losses.length > 0 ? 
        Math.abs(losses.reduce(function(s, t) { return s + (t.pnl || 0); }, 0)) / losses.length : 0;
      
      // Kelly position sizing
      const kelly = this.calculateKellyPosition(
        account.balance, winRate, avgWin, avgLoss, 0.02
      );
      
      // VaR calculation
      const var_ = this.calculateVaR(positions, 0.95);
      
      // Sharpe ratio
      const sharpe = this.calculateSharpeRatio(closedTrades);
      
      // Drawdown analysis
      let peak = account.initialBalance;
      let maxDrawdown = 0;
      let currentDrawdown = 0;
      
      for (let i = 0; i < closedTrades.length; i++) {
        const trade = closedTrades[i];
        const equityAfter = (i === 0 ? account.initialBalance : 0) + 
          (trade.pnl || 0);
        
        if (equityAfter > peak) {
          peak = equityAfter;
        }
        
        const drawdown = peak > 0 ? (peak - equityAfter) / peak : 0;
        if (drawdown > maxDrawdown) {
          maxDrawdown = drawdown;
        }
      }
      
      // Current drawdown
      if (account.balance < peak) {
        currentDrawdown = (peak - account.balance) / peak;
      }
      
      return {
        timestamp: new Date().toISOString(),
        account: {
          balance: account.balance,
          initialBalance: account.initialBalance,
          totalPnl: account.totalPnl,
          totalPnlPercent: account.totalPnlPercent
        },
        performance: {
          totalTrades: totalTrades,
          winRate: (winRate * 100).toFixed(1) + '%',
          avgWin: avgWin.toFixed(2),
          avgLoss: avgLoss.toFixed(2),
          profitFactor: avgLoss > 0 ? (avgWin / avgLoss).toFixed(2) : '∞'
        },
        risk: {
          kelly: kelly,
          var: var_,
          sharpe: sharpe,
          maxDrawdown: (maxDrawdown * 100).toFixed(2) + '%',
          currentDrawdown: (currentDrawdown * 100).toFixed(2) + '%'
        },
        positions: {
          open: positions.length,
          totalExposure: var_.totalPortfolioValue,
          worstCase: var_.stressTest
        }
      };
    }
  };

