  function initPortfolioAnalytics() {
    // Show portfolio section if user has trades
    const section = document.getElementById('portfolio-analytics-section');
    if (!section) return;
    
    // Show section if there are positions or trade history
    const hasActivity = (STATE.positions && STATE.positions.length > 0) ||
                        (TradeManager.orderHistory && TradeManager.orderHistory.length > 0);
    
    if (hasActivity) {
      section.style.display = 'block';
    }
    
    // Refresh button
    const refreshBtn = document.getElementById('refresh-portfolio-btn');
    if (refreshBtn) {
      refreshBtn.addEventListener('click', function() {
        updatePortfolioAnalytics();
        if (typeof Toast !== 'undefined') {
          Toast.info('Portfolio analytics refreshed');
        }
      });
    }
    
    // Risk report button
    const reportBtn = document.getElementById('generate-risk-report-btn');
    if (reportBtn) {
      reportBtn.addEventListener('click', function() {
        generateAndDisplayRiskReport();
      });
    }
    
    updatePortfolioAnalytics();
  }
  
  function updatePortfolioAnalytics() {
    if (typeof RiskManager === 'undefined') return;
    
    const report = RiskManager.generateRiskReport();
    const section = document.getElementById('portfolio-analytics-section');
    
    // Show section if there's activity
    if (section && (report.performance.totalTrades > 0 || report.positions.open > 0)) {
      section.style.display = 'block';
    }
    
    // Update UI elements
    setElText('pa-winrate', report.performance.winRate);
    setElText('pa-profit-factor', report.performance.profitFactor);
    setElText('pa-sharpe', report.risk.sharpe.annualizedSharpe);
    setElText('pa-max-dd', report.risk.maxDrawdown);
    setElText('pa-var', '-$' + U.formatLargeNum(report.risk.var.var));
    setElText('pa-var-label', report.risk.var.varLabel);
    setElText('pa-kelly', '$' + U.formatLargeNum(report.risk.kelly.optimalSize));
    setElText('pa-kelly-rec', report.risk.kelly.recommendation);
    setElText('pa-exposure', '$' + U.formatLargeNum(report.positions.totalExposure));
    setElText('pa-open-positions', report.positions.open);
    
    // Color code Sharpe ratio
    const sharpeEl = document.getElementById('pa-sharpe');
    if (sharpeEl) {
      const sharpe = parseFloat(report.risk.sharpe.annualizedSharpe);
      if (sharpe < 0) sharpeEl.style.color = 'var(--down-color)';
      else if (sharpe < 1) sharpeEl.style.color = 'var(--warning)';
      else if (sharpe < 2) sharpeEl.style.color = 'var(--up-color)';
      else sharpeEl.style.color = 'var(--accent-primary)';
    }
  }
  
  function generateAndDisplayRiskReport() {
    if (typeof RiskManager === 'undefined') return;
    
    const report = RiskManager.generateRiskReport();
    
    // Create a formatted report
    const reportText = [
      '═══════════════════════════════',
      '  TRADEVISION PRO - RISK REPORT',
      '═══════════════════════════════',
      'Date: ' + new Date(report.timestamp).toLocaleString(),
      '',
      '📊 ACCOUNT SUMMARY',
      '  Balance: $' + U.formatLargeNum(report.account.balance),
      '  Total P&L: $' + U.formatNum(report.account.totalPnl, 2),
      '  Return: ' + U.formatNum(report.account.totalPnlPercent, 2) + '%',
      '',
      '📈 PERFORMANCE METRICS',
      '  Total Trades: ' + report.performance.totalTrades,
      '  Win Rate: ' + report.performance.winRate,
      '  Avg Win: $' + U.formatNum(report.performance.avgWin, 2),
      '  Avg Loss: $' + U.formatNum(report.performance.avgLoss, 2),
      '  Profit Factor: ' + report.performance.profitFactor,
      '',
      '⚠️ RISK METRICS',
      '  ' + report.risk.var.varLabel + ': $' + U.formatLargeNum(report.risk.var.var),
      '  Max Drawdown: ' + report.risk.maxDrawdown,
      '  Sharpe Ratio: ' + report.risk.sharpe.annualizedSharpe,
      '  ' + report.risk.sharpe.interpretation,
      '',
      '💡 POSITION SIZING (Kelly)',
      '  Optimal Size: $' + U.formatLargeNum(report.risk.kelly.optimalSize),
      '  ' + report.risk.kelly.recommendation,
      '',
      '📋 OPEN POSITIONS: ' + report.positions.open,
      '  Total Exposure: $' + U.formatLargeNum(report.positions.totalExposure),
      '  ' + report.positions.worstCase,
      '',
      '═══════════════════════════════',
      '⚠️ DISCLAIMER: This is not financial advice.',
      '═══════════════════════════════'
    ].join('\n');
    
    // Copy to clipboard
    if (navigator.clipboard) {
      navigator.clipboard.writeText(reportText).then(function() {
        if (typeof Toast !== 'undefined') {
          Toast.success('📋 Risk report copied to clipboard!');
        }
      });
    }
    
    // Also log to console for power users
    console.log(reportText);
    
    // Show summary toast
    if (typeof Toast !== 'undefined') {
      Toast.info(
        'Sharpe: ' + report.risk.sharpe.annualizedSharpe + 
        ' | Win Rate: ' + report.performance.winRate +
        ' | Max DD: ' + report.risk.maxDrawdown,
        8000
      );
    }
  }
  
  function setElText(id, value) {
    const el = document.getElementById(id);
    if (el) el.textContent = value;
  }
