  open(side) {
    var modal = document.getElementById('broker-modal');
    if (!modal) return;

    // Gather trade details from the paper trade panel
    var priceInput = document.getElementById('trade-price-input');
    var amountInput = document.getElementById('trade-amount-input');
    var price = parseFloat(priceInput?.value) || STATE.currentPrice || 0;
    var amount = parseFloat(amountInput?.value) || 0;
    var symbol = STATE.symbol;
    var displaySymbol = symbol.replace('USDT', '/USDT');
    var isBuy = (side === 'buy');

    // Format price and amount for display
    var formattedPrice = typeof U !== 'undefined' ? U.formatPrice(price) : price.toFixed(2);
    var formattedAmount = amount || 0.01;
    
    // Update badge in modal
    var sideBadge = document.getElementById('broker-side-badge');
    var amountBadge = document.getElementById('broker-amount-badge');
    var priceBadge = document.getElementById('broker-price-badge');
    var tradeDesc = document.getElementById('broker-trade-desc');
    
    if (sideBadge) {
      sideBadge.textContent = isBuy ? 'BUY' : 'SELL';
      sideBadge.style.color = isBuy ? 'var(--up-color)' : 'var(--down-color)';
    }
    if (amountBadge) amountBadge.textContent = formattedAmount + ' ' + displaySymbol;
    if (priceBadge) priceBadge.textContent = '$' + formattedPrice;
    if (tradeDesc) {
      tradeDesc.textContent = (isBuy ? 'Buy' : 'Sell') + ' ' + formattedAmount + ' ' + displaySymbol + ' at $' + formattedPrice;
    }
    
    // Store trade details for use in links
    this.currentTrade = {
      symbol: symbol,
      side: side,
      price: price,
      amount: formattedAmount,
      isBuy: isBuy
    };

    // ============================================
    // GENERATE BROKER CARDS
    // ============================================
    var container = document.getElementById('broker-cards-container');
    var self = this;
    
    container.innerHTML = this.brokers.map(function(broker) {
      var tags = '';
      
      // API badge
      if (broker.apiAvailable) {
        tags += '<span style="background: rgba(38,166,154,0.15); color: var(--up-color); padding: 2px 7px; border-radius: 10px; font-size: 9px; font-weight: 600; margin-left: 4px;">API</span>';
      }
      
      // Country tags
      broker.countries.forEach(function(c) {
        var bgColor = 'rgba(88,166,255,0.1)';
        if (c === 'India') bgColor = 'rgba(255,152,0,0.15)';
        if (c === 'Nigeria' || c === 'Kenya') bgColor = 'rgba(38,166,154,0.15)';
        tags += '<span style="background: ' + bgColor + '; padding: 2px 6px; border-radius: 10px; font-size: 9px; margin-left: 3px;">' + c + '</span>';
      });
      
      return '<div class="broker-card" data-broker="' + broker.name + '" style="cursor:pointer;">' +
        '<div class="broker-icon" style="color:' + broker.color + ';">' + broker.icon + '</div>' +
        '<div class="broker-name" style="margin-bottom: 4px;">' + broker.name + '</div>' +
        '<div style="margin-bottom: 4px;">' + tags + '</div>' +
        '<div class="broker-desc" style="margin-bottom: 10px; font-size: 10px;">' + broker.desc + '</div>' +
        '<span class="broker-link-btn" style="font-size: 10px;">Open Exchange →</span>' +
      '</div>';
    }).join('');
    
    // ============================================
    // ADD CLICK HANDLERS TO BROKER CARDS
    // ============================================
    container.querySelectorAll('.broker-card').forEach(function(card) {
      card.addEventListener('click', function() {
        var brokerName = this.dataset.broker;
        var broker = self.brokers.find(function(b) { return b.name === brokerName; });
        
        if (broker) {
          var trade = self.currentTrade;
          
          // Build the exchange URL
          var url = broker.buildUrl(trade.symbol, trade.side, trade.price, trade.amount);
          
          // Create a trade summary to copy to clipboard
          var summary = [
            '═══════════════════════════',
            '  TradeVision Pro - Order',
            '═══════════════════════════',
            'Exchange: ' + broker.name,
            'Side: ' + (trade.isBuy ? 'BUY' : 'SELL'),
            'Pair: ' + trade.symbol.replace('USDT', '/USDT'),
            'Price: $' + formattedPrice,
            'Amount: ' + trade.amount + ' ' + trade.symbol.replace('USDT', ''),
            'Total: $' + (trade.price * trade.amount).toFixed(2),
            '═══════════════════════════',
            'Opening ' + broker.name + '...'
          ].join('\n');
          
          // Copy summary to clipboard
          try {
            navigator.clipboard.writeText(summary).then(function() {
              console.log('✅ Trade summary copied to clipboard');
            }).catch(function() {
              // Clipboard failed, that's okay
            });
          } catch(e) {}
          
          // Show toast with instructions
          if (typeof Toast !== 'undefined') {
            Toast.success('Opening ' + broker.name + ' - Trade details copied!', 4000);
          }
          
          // Open exchange in new tab
          window.open(url, '_blank');
          
          // Close the modal
          modal.classList.remove('visible');
        }
      });
    });

    // Show the modal
    modal.classList.add('visible');
  }
