// Sync dropdown active states with actual buttons
function syncDropdownStates() {
    var menu = document.getElementById('tools-dropdown-menu');
    if (!menu) return;
    
    menu.querySelectorAll('.ctrl-dropdown-item').forEach(function(item) {
        var id = item.id;
        var actualBtn = document.getElementById(id);
        if (actualBtn) {
            var isActive = actualBtn.classList.contains('active');
            item.classList.toggle('active', isActive);
        }
    });
}

// Sync every 2 seconds
