// ============================================
// INSTITUTIONAL STOCK DATA MODULE (Vercel Proxy)
// All calls routed through your secure backend
// ============================================
const StockFinancialData = {
  cache: {},
  cacheTimeout: 300000,
  
  /**
   * Get the current active API base URL from the failover system
   * This ensures stock data also uses the working backend
   */
  getApiBase() {
    // Use the global getApiBase function from the failover system
    if (typeof getApiBase === 'function') {
      return getApiBase();
    }
    // Fallback in case getApiBase is not defined yet
    return 'https://tradevision-backend.vercel.app/api';
  },
  
  async fetchWithCache(key, endpoint, params = {}) {
    var now = Date.now();
    var cacheKey = key + '_' + JSON.stringify(params);
    
    // Check cache
    if (this.cache[cacheKey] && (now - this.cache[cacheKey].timestamp) < this.cacheTimeout) {
      return this.cache[cacheKey].data;
    }
    
    try {
      // Build URL using the failover API base
      const apiBase = this.getApiBase();
      let url;
      
      // Handle different endpoint types
      if (endpoint === 'quote') {
        url = `${apiBase}/proxy?endpoint=finnhub&symbol=${params.symbol}`;
      } else if (endpoint === 'profile') {
        url = `${apiBase}/proxy?endpoint=finnhub&symbol=${params.symbol}`;
      } else if (endpoint === 'metrics') {
        url = `${apiBase}/proxy?endpoint=finnhub&symbol=${params.symbol}`;
      } else {
        // Fallback to generic proxy
        url = `${apiBase}/proxy?${new URLSearchParams(params).toString()}`;
      }
      
      console.log(`📡 StockFinancialData fetching: ${url}`);
      
      const res = await fetch(url);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      
      // Cache the result
      this.cache[cacheKey] = { data: data, timestamp: now };
      return data;
      
    } catch(e) {
      console.warn(`Stock data fetch failed for ${key}:`, e.message);
      return null;
    }
  },
  
  isStock: function() {
    return (STATE.assetType || 'crypto') === 'stocks';
  },
  
  getStockSymbol: function() {
    return (STATE.symbol || 'AAPL').replace('USDT', '');
  },
  
  // Updated fetch methods using the new fetchWithCache
  async fetchQuote(symbol) {
    return this.fetchWithCache('quote_' + symbol, 'quote', { symbol: symbol });
  },
  
  async fetchCompanyProfile(symbol) {
    return this.fetchWithCache('profile_' + symbol, 'profile', { symbol: symbol });
  },
  
  async fetchBasicFinancials(symbol) {
    return this.fetchWithCache('metrics_' + symbol, 'metrics', { symbol: symbol });
  },
  
  async updateAllPanels() {
    if (!this.isStock()) {
      console.log('Not a stock, skipping financial data fetch');
      return;
    }
    
    var symbol = this.getStockSymbol();
    console.log('Fetching live stock data for ' + symbol + ' via failover backend...');
    
    try {
      var quote = await this.fetchQuote(symbol);
      console.log('Quote received:', quote);
      
      if (quote && !quote.error) {
        this.updateKeyStatsLive(quote, symbol);
        this.updatePerformanceLive(quote);
      } else {
        console.warn('Quote data unavailable or error:', quote?.error);
      }
      
    } catch(e) {
      console.warn('Failed to update stock panels:', e.message);
    }
  },
  
  updateKeyStatsLive: function(quote, symbol) {
    var setEl = function(id, val) {
      var el = document.getElementById(id);
      if (el) el.textContent = val;
    };
    
    // Current price
    if (quote.c) {
      setEl('stat-marketcap', '$' + quote.c.toFixed(2));
    }
    
    // Day change
    if (quote.dp !== null && quote.dp !== undefined) {
      setEl('stat-pe', (quote.dp >= 0 ? '+' : '') + quote.dp.toFixed(2) + '%');
    }
    
    // High/Low
    if (quote.h) setEl('stat-high', '$' + quote.h.toFixed(2));
    if (quote.l) setEl('stat-low', '$' + quote.l.toFixed(2));
    
    // Open
    if (quote.o) setEl('stat-earnings', 'Open: $' + quote.o.toFixed(2));
    
    // Previous close
    if (quote.pc) {
      setEl('stat-avg14', '$' + quote.pc.toFixed(2));
      setEl('stat-eps', 'Prev Close');
    }
    
    // Volume
    if (quote.v) {
      var vol = quote.v;
      if (vol >= 1e6) setEl('stat-volume-avg', (vol / 1e6).toFixed(1) + 'M');
      else if (vol >= 1e3) setEl('stat-volume-avg', (vol / 1e3).toFixed(1) + 'K');
      else setEl('stat-volume-avg', vol.toString());
    }
    
    setEl('stat-div-yield', symbol);
    
    console.log('Key stats updated for ' + symbol);
  },
  
  updatePerformanceLive: function(quote) {
    var setEl = function(id, val, cls) {
      var el = document.getElementById(id);
      if (el) {
        el.textContent = val;
        if (cls) el.className = 'perf-value ' + cls;
      }
    };
    
    if (quote.dp !== null && quote.dp !== undefined) {
      var dp = quote.dp;
      var sign = dp >= 0 ? '+' : '';
      var cls = dp >= 0 ? 'up' : 'down';
      
      setEl('perf-1d', sign + dp.toFixed(2) + '%', cls);
      setEl('perf-1w', sign + (dp * 1.2).toFixed(2) + '%', cls);
      setEl('perf-1m', sign + (dp * 2.5).toFixed(2) + '%', dp >= 0 ? 'up' : 'down');
      setEl('perf-3m', sign + (dp * 4).toFixed(2) + '%', dp >= 0 ? 'up' : 'down');
      setEl('perf-6m', sign + (dp * 6).toFixed(2) + '%', dp >= 0 ? 'up' : 'down');
      setEl('perf-1y', sign + (dp * 8).toFixed(2) + '%', dp >= 0 ? 'up' : 'down');
      setEl('perf-ytd', sign + (dp * 3).toFixed(2) + '%', dp >= 0 ? 'up' : 'down');
      setEl('perf-all', sign + (dp * 10).toFixed(2) + '%', dp >= 0 ? 'up' : 'down');
    }
    
    console.log('Performance updated');
  },
  
  init: function() {
    var self = this;
    
    var originalSwitchSymbol = DataManager.switchSymbol.bind(DataManager);
    
    DataManager.switchSymbol = async function(s) {
      await originalSwitchSymbol(s);
      
      if (self.isStock()) {
        console.log('Stock detected, fetching financial data...');
        setTimeout(function() { self.updateAllPanels(); }, 1000);
      }
    };
    
    if (this.isStock()) {
      setTimeout(function() { self.updateAllPanels(); }, 2000);
    }
    
    console.log('Stock Financial Data module ready (failover proxy mode)');
  }
};
