function initEarningsChart() {
  const container = document.getElementById('earnings-chart');
  if (!container) return;
  
  const quarters = ['Q1\'24', 'Q2\'24', 'Q3\'24', 'Q4\'24', 'Q1\'25'];
  const actual = [85, 92, 78, 95, 88];
  const estimate = [82, 88, 75, 90, 85];
  const maxVal = Math.max(...actual, ...estimate);
  
  container.innerHTML = quarters.map((q, i) => `
    <div class="earnings-bar-group" title="${q}: Actual $${actual[i]}B vs Est $${estimate[i]}B">
      <div class="earnings-bar actual" style="height:${(actual[i]/maxVal)*100}%"></div>
      <div class="earnings-bar estimate" style="height:${(estimate[i]/maxVal)*100}%"></div>
    </div>
  `).join('');
}

function initDividendDoughnut() {
  const canvas = document.getElementById('dividend-canvas');
  if (!canvas) return;
  
  const ctx = canvas.getContext('2d');
  const payoutRatio = 0.45; // 45% payout
  
  const draw = () => {
    const size = 80;
    canvas.width = size * 2;
    canvas.height = size * 2;
    const cx = size, cy = size, r = size - 10;
    
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    
    // Retained (Green)
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.arc(cx, cy, r, -Math.PI/2, -Math.PI/2 + (1-payoutRatio) * Math.PI * 2);
    ctx.closePath();
    ctx.fillStyle = '#26a69a';
    ctx.fill();
    
    // Payout (Red)
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.arc(cx, cy, r, -Math.PI/2 + (1-payoutRatio) * Math.PI * 2, -Math.PI/2 + Math.PI * 2);
    ctx.closePath();
    ctx.fillStyle = '#ef5350';
    ctx.fill();
    
    // Center hole
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.55, 0, Math.PI * 2);
    ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--bg-secondary').trim() || '#161b22';
    ctx.fill();
  };
  
  draw();
  
  document.getElementById('retained-val').textContent = Math.round((1-payoutRatio)*100) + '%';
  document.getElementById('payout-val').textContent = Math.round(payoutRatio*100) + '%';
  document.getElementById('payout-ratio').textContent = Math.round(payoutRatio*100) + '%';
}

