async function initIVStructure() {
  const container = document.getElementById('iv-chart');
  if (!container) {
    console.log('IV chart container not found, retrying...');
    setTimeout(initIVStructure, 500);
    return;
  }
  
  // Show loading state
  container.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:center;height:100px;color:var(--text-muted);">
      <i class="fas fa-spinner fa-spin"></i>
      <span style="margin-left:8px;">Loading IV data...</span>
    </div>
  `;
  
  // Get API base for proxy
  const getApiBase = () => {
    if (window.TRADEVISION_CONFIG && window.TRADEVISION_CONFIG.API_URL) {
      return window.TRADEVISION_CONFIG.API_URL;
    }
    return 'https://tradevision-backend.vercel.app/api';
  };
  
  const apiBase = getApiBase();
  const currency = STATE.symbol?.includes('BTC') ? 'BTC' : 
                   STATE.symbol?.includes('ETH') ? 'ETH' : 'BTC';
  
  try {
    let ivData = null;
    let dataSource = 'fallback';
    
    // Try to fetch from backend
    try {
      const response = await fetch(`${apiBase}/proxy?endpoint=deribit-iv-term&currency=${currency}`, {
        headers: { 'Content-Type': 'application/json' },
        signal: AbortSignal.timeout(5000)
      });
      
      if (response.ok) {
        ivData = await response.json();
        if (ivData && ivData.length > 0) {
          dataSource = 'deribit';
          console.log('✅ IV data from Deribit');
        }
      }
    } catch (error) {
      console.warn('Deribit failed, using fallback:', error.message);
    }
    
    // If Deribit failed, use calculated fallback
    if (!ivData || ivData.length === 0) {
      ivData = getFallbackIVData(currency);
      dataSource = 'fallback (calculated)';
      console.log('📊 Using fallback IV data');
    }
    
    // Render the IV Term Structure
    renderIVTermStructure(container, ivData, dataSource);
    
  } catch (error) {
    console.error('IV data error:', error.message);
    renderIVFallback(container);
  }
}

// Fallback IV data generator
function getFallbackIVData(currency) {
  // Calculate based on current market conditions
  const currentPrice = STATE.currentPrice || (currency === 'BTC' ? 60000 : 3000);
  const volatility = Math.abs(STATE.change24h || 5) * 1.5;
  
  const baseIV = Math.min(85, Math.max(25, volatility + 35));
  
  const expiries = [
    { label: '7D', days: 7, multiplier: 1.3 },
    { label: '14D', days: 14, multiplier: 1.2 },
    { label: '30D', days: 30, multiplier: 1.0 },
    { label: '60D', days: 60, multiplier: 0.9 },
    { label: '90D', days: 90, multiplier: 0.85 },
    { label: '180D', days: 180, multiplier: 0.8 },
    { label: '365D', days: 365, multiplier: 0.75 }
  ];
  
  return expiries.map(exp => ({
    expiry: exp.label,
    daysToExpiry: exp.days,
    iv: Math.round(baseIV * exp.multiplier),
    source: 'fallback'
  }));
}

