// ============================================
// STRATEGY BACKTESTER
// ============================================
const Backtester = {
  // ============================================
  // CONFIGURATION
  // ============================================
  config: {
    initialCapital: 10000,
    commission: 0.001,        // 0.1% per trade
    slippage: 0.0005,         // 0.05% slippage
    maxPositionSize: 0.95,    // Use max 95% of capital
    riskPerTrade: 0.02,       // Risk 2% per trade
    riskFreeRate: 0.04,       // 4% annual for Sharpe calculation
    minBarsForStats: 30       // Need at least 30 bars for valid stats
  },

  // ============================================
  // INDICATOR CALCULATORS (NO FUTURE LEAK)
  // Each calculates using ONLY data up to current bar
  // ============================================

  /**
   * Calculate RSI at a specific bar using only historical data
   * @param {Array} data - Array of candles
   * @param {number} barIndex - Current bar index (exclusive)
   * @param {number} period - RSI period
   * @returns {number|null} RSI value or null if not enough data
   */
  calcRSIAtBar: function(data, barIndex, period) {
    period = period || 14;
    if (barIndex < period + 1) return null;
    
    var gains = 0, losses = 0;
    
    for (var i = barIndex - period + 1; i <= barIndex; i++) {
      var change = data[i].close - data[i - 1].close;
      if (change >= 0) gains += change;
      else losses -= change;
    }
    
    var avgGain = gains / period;
    var avgLoss = losses / period;
    
    if (avgLoss === 0) return 100;
    var rs = avgGain / avgLoss;
    return 100 - (100 / (1 + rs));
  },

  /**
   * Calculate SMA at a specific bar
   */
  calcSMAAtBar: function(data, barIndex, period) {
    period = period || 20;
    if (barIndex < period - 1) return null;
    
    var sum = 0;
    for (var i = barIndex - period + 1; i <= barIndex; i++) {
      sum += data[i].close;
    }
    return sum / period;
  },

  /**
   * Calculate EMA at a specific bar (recursive, no future leak)
   */
  calcEMAAtBar: function(data, barIndex, period) {
    period = period || 20;
    if (barIndex < period - 1) return null;
    
    // Calculate initial SMA for the first EMA value
    if (barIndex === period - 1) {
      return this.calcSMAAtBar(data, barIndex, period);
    }
    
    var prevEMA = this.calcEMAAtBar(data, barIndex - 1, period);
    if (prevEMA === null) return null;
    
    var k = 2 / (period + 1);
    return (data[barIndex].close - prevEMA) * k + prevEMA;
  },

  /**
   * Calculate MACD at a specific bar
   * Returns { macdLine, signalLine, histogram }
   */
  calcMACDAtBar: function(data, barIndex, fastPeriod, slowPeriod, signalPeriod) {
    fastPeriod = fastPeriod || 12;
    slowPeriod = slowPeriod || 26;
    signalPeriod = signalPeriod || 9;
    
    if (barIndex < slowPeriod - 1) return null;
    
    var fastEMA = this.calcEMAAtBar(data, barIndex, fastPeriod);
    var slowEMA = this.calcEMAAtBar(data, barIndex, slowPeriod);
    
    if (fastEMA === null || slowEMA === null) return null;
    
    var macdLine = fastEMA - slowEMA;
    
    // Calculate signal line (need to track previous MACD values)
    if (!this._macdCache) this._macdCache = {};
    var key = barIndex + '_' + fastPeriod + '_' + slowPeriod;
    
    if (!this._macdCache[key]) {
      // Build array of MACD values up to this bar
      var macdValues = [];
      for (var i = slowPeriod - 1; i <= barIndex; i++) {
        var fEma = this.calcEMAAtBar(data, i, fastPeriod);
        var sEma = this.calcEMAAtBar(data, i, slowPeriod);
        if (fEma !== null && sEma !== null) {
          macdValues.push(fEma - sEma);
        }
      }
      this._macdCache[key] = macdValues;
    }
    
    var macdValues = this._macdCache[key];
    
    // Calculate signal line from MACD values
    var signalLine = null;
    if (macdValues.length >= signalPeriod) {
      var signalSum = 0;
      for (var i = macdValues.length - signalPeriod; i < macdValues.length; i++) {
        signalSum += macdValues[i];
      }
      signalLine = signalSum / signalPeriod;
    }
    
    if (macdLine === null || signalLine === null) return null;
    
    return {
      macdLine: macdLine,
      signalLine: signalLine,
      histogram: macdLine - signalLine
    };
  },

  /**
   * Calculate ATR at a specific bar
   */
  calcATRAtBar: function(data, barIndex, period) {
    period = period || 14;
    if (barIndex < period) return null;
    
    var trueRanges = [];
    for (var i = Math.max(1, barIndex - period + 1); i <= barIndex; i++) {
      var high = data[i].high;
      var low = data[i].low;
      var prevClose = data[i - 1].close;
      var tr = Math.max(high - low, Math.abs(high - prevClose), Math.abs(low - prevClose));
      trueRanges.push(tr);
    }
    
    var sum = trueRanges.reduce(function(a, b) { return a + b; }, 0);
    return sum / trueRanges.length;
  },

  /**
   * Calculate Bollinger Bands at a specific bar
   */
  calcBBAtBar: function(data, barIndex, period, stdDevMult) {
    period = period || 20;
    stdDevMult = stdDevMult || 2;
    
    if (barIndex < period - 1) return null;
    
    var sma = this.calcSMAAtBar(data, barIndex, period);
    if (sma === null) return null;
    
    // Calculate standard deviation
    var varianceSum = 0;
    for (var i = barIndex - period + 1; i <= barIndex; i++) {
      varianceSum += Math.pow(data[i].close - sma, 2);
    }
    var stdDev = Math.sqrt(varianceSum / period);
    
    return {
      upper: sma + stdDevMult * stdDev,
      middle: sma,
      lower: sma - stdDevMult * stdDev,
      width: (2 * stdDevMult * stdDev) / sma // Bandwidth
    };
  },

  // ============================================
  // ENTRY/EXIT SIGNAL CALCULATORS
  // ============================================

  /**
   * Get entry signal for a specific bar
   * @returns {boolean} True if entry conditions are met
   */
  getEntrySignal: function(data, barIndex, entryConfig) {
    var ind = entryConfig.indicator;
    var cond = entryConfig.condition;
    var val = entryConfig.value;
    
    switch(ind) {
      case 'RSI':
        var rsi = this.calcRSIAtBar(data, barIndex, 14);
        if (rsi === null) return false;
        if (cond === 'below') return rsi < val;
        if (cond === 'above') return rsi > val;
        return false;
        
      case 'SMA_CROSS':
        var sma20 = this.calcSMAAtBar(data, barIndex, 20);
        var sma50 = this.calcSMAAtBar(data, barIndex, 50);
        var prevSMA20 = this.calcSMAAtBar(data, barIndex - 1, 20);
        var prevSMA50 = this.calcSMAAtBar(data, barIndex - 1, 50);
        
        if (sma20 === null || sma50 === null || prevSMA20 === null || prevSMA50 === null) return false;
        
        if (cond === 'above') return sma20 > sma50;
        if (cond === 'below') return sma20 < sma50;
        if (cond === 'crosses_above') return prevSMA20 <= prevSMA50 && sma20 > sma50;
        if (cond === 'crosses_below') return prevSMA20 >= prevSMA50 && sma20 < sma50;
        return false;
        
      case 'MACD':
        var macd = this.calcMACDAtBar(data, barIndex, 12, 26, 9);
        var prevMACD = this.calcMACDAtBar(data, barIndex - 1, 12, 26, 9);
        
        if (macd === null || prevMACD === null) return false;
        
        if (cond === 'above') return macd.histogram > val;
        if (cond === 'below') return macd.histogram < val;
        if (cond === 'crosses_above') return prevMACD.histogram <= 0 && macd.histogram > 0;
        if (cond === 'crosses_below') return prevMACD.histogram >= 0 && macd.histogram < 0;
        return false;
        
      case 'BB':
        var bb = this.calcBBAtBar(data, barIndex, 20, 2);
        if (bb === null) return false;
        
        var price = data[barIndex].close;
        if (cond === 'below_lower') return price <= bb.lower;
        if (cond === 'above_upper') return price >= bb.upper;
        if (cond === 'above_middle') return price > bb.middle;
        if (cond === 'below_middle') return price < bb.middle;
        return false;
        
      case 'PRICE_CHANGE':
        if (barIndex < 1) return false;
        var change = ((data[barIndex].close - data[barIndex - 1].close) / data[barIndex - 1].close) * 100;
        if (cond === 'above') return change > val;
        if (cond === 'below') return change < val;
        return false;
        
      default:
        return false;
    }
  },

  /**
   * Get exit signal for a specific bar
   */
  getExitSignal: function(data, barIndex, exitConfig, position) {
    var ind = exitConfig.indicator;
    var cond = exitConfig.condition;
    var val = exitConfig.value;
    
    if (!position || !position.entryPrice) return false;
    
    // Check stop loss
    if (position.stopLossPercent) {
      var stopPrice = position.entryPrice * (1 - position.stopLossPercent / 100);
      if (data[barIndex].low <= stopPrice) return true;
    }
    
    // Check take profit
    if (position.takeProfitPercent) {
      var tpPrice = position.entryPrice * (1 + position.takeProfitPercent / 100);
      if (data[barIndex].high >= tpPrice) return true;
    }
    
    // Check trailing stop
    if (position.trailingStopPercent && position.highestPrice) {
      var trailStop = position.highestPrice * (1 - position.trailingStopPercent / 100);
      if (data[barIndex].low <= trailStop) return true;
    }
    
    // Time-based exit (max bars in trade)
    if (position.maxBars && (barIndex - position.entryBarIndex) >= position.maxBars) {
      return true;
    }
    
    // Indicator-based exit
    switch(ind) {
      case 'RSI':
        var rsi = this.calcRSIAtBar(data, barIndex, 14);
        if (rsi === null) return false;
        if (cond === 'above') return rsi > val;
        if (cond === 'below') return rsi < val;
        return false;
        
      case 'MACD':
        var macd = this.calcMACDAtBar(data, barIndex, 12, 26, 9);
        var prevMACD = this.calcMACDAtBar(data, barIndex - 1, 12, 26, 9);
        
        if (macd === null || prevMACD === null) return false;
        if (cond === 'crosses_below') return prevMACD.histogram >= 0 && macd.histogram < 0;
        if (cond === 'crosses_above') return prevMACD.histogram <= 0 && macd.histogram > 0;
        return false;
        
      default:
        return false;
    }
  },

  // ============================================
  // POSITION SIZING
  // ============================================

  /**
   * Calculate position size based on risk management
   * @param {number} capital - Available capital
   * @param {number} entryPrice - Entry price
   * @param {number} stopLossPrice - Stop loss price (or null)
   * @returns {number} Position size in units
   */
  calculatePositionSize: function(capital, entryPrice, stopLossPrice) {
    var riskAmount = capital * this.config.riskPerTrade;
    var maxCapital = capital * this.config.maxPositionSize;
    
    if (stopLossPrice && stopLossPrice > 0) {
      var riskPerUnit = Math.abs(entryPrice - stopLossPrice);
      if (riskPerUnit > 0) {
        var sizeFromRisk = riskAmount / riskPerUnit;
        var sizeFromCapital = maxCapital / entryPrice;
        return Math.min(sizeFromRisk, sizeFromCapital);
      }
    }
    
    return maxCapital / entryPrice;
  },

  // ============================================
  // EXECUTION SIMULATOR
  // ============================================

  /**
   * Simulate order execution with slippage and commission
   */
  executeOrder: function(price, size, isEntry) {
    var slippageCost = price * size * this.config.slippage;
    var commission = price * size * this.config.commission;
    var totalCost = slippageCost + commission;
    
    // Slippage direction: pay more on entry, receive less on exit
    var executionPrice = isEntry ? price * (1 + this.config.slippage) : price * (1 - this.config.slippage);
    
    return {
      executionPrice: executionPrice,
      slippageCost: slippageCost,
      commission: commission,
      totalCost: totalCost,
      totalValue: executionPrice * size
    };
  },
    // ============================================
  // MAIN BACKTEST RUNNER
  // ============================================

  /**
   * Run a complete backtest simulation
   * @param {Array} data - Candlestick data array
   * @param {Object} entryConfig - { indicator, condition, value }
   * @param {Object} exitConfig - { indicator, condition, value }
   * @param {Object} riskConfig - { stopLossPercent, takeProfitPercent, trailingStopPercent, maxBars }
   * @returns {Object} Complete backtest results
   */
  runBacktest: function(data, entryConfig, exitConfig, riskConfig) {
    riskConfig = riskConfig || {};
    
    // Validate data
    if (!data || data.length < this.config.minBarsForStats) {
      return {
        error: true,
        message: 'Need at least ' + this.config.minBarsForStats + ' candles for valid backtest',
        totalTrades: 0
      };
    }
    
    // Initialize tracking variables
    var capital = this.config.initialCapital;
    var initialCapital = this.config.initialCapital;
    var position = null;
    var trades = [];
    var equityCurve = [{ trade: 0, equity: capital, barIndex: 0, time: data[0].time }];
    
    var peakCapital = capital;
    var maxDrawdown = 0;
    var maxDrawdownPercent = 0;
    var dailyReturns = [];
    var winStreak = 0;
    var loseStreak = 0;
    var maxWinStreak = 0;
    var maxLoseStreak = 0;
    
    // ============================================
    // WALK-FORWARD SIMULATION LOOP
    // Each bar, we calculate indicators using ONLY
    // data up to that bar (no future leak)
    // ============================================
    
    var startBar = Math.max(50, this.config.minBarsForStats); // Skip early bars for indicator warmup
    
    for (var barIndex = startBar; barIndex < data.length; barIndex++) {
      
      // ============================================
      // CHECK FOR EXIT (if in position)
      // ============================================
      if (position) {
        // Update highest price for trailing stop
        if (data[barIndex].high > position.highestPrice) {
          position.highestPrice = data[barIndex].high;
        }
        
        var shouldExit = this.getExitSignal(data, barIndex, exitConfig, position);
        
        if (shouldExit) {
          // Determine exit price
          var exitPrice;
          var exitReason;
          
          // Check if stop loss hit
          if (position.stopLossPercent) {
            var stopPrice = position.entryPrice * (1 - position.stopLossPercent / 100);
            if (data[barIndex].low <= stopPrice) {
              exitPrice = Math.min(position.entryPrice, stopPrice); // Assume fill at stop
              exitReason = 'Stop Loss';
            }
          }
          
          // Check if take profit hit
          if (!exitPrice && position.takeProfitPercent) {
            var tpPrice = position.entryPrice * (1 + position.takeProfitPercent / 100);
            if (data[barIndex].high >= tpPrice) {
              exitPrice = tpPrice;
              exitReason = 'Take Profit';
            }
          }
          
          // Check trailing stop
          if (!exitPrice && position.trailingStopPercent && position.highestPrice) {
            var trailStop = position.highestPrice * (1 - position.trailingStopPercent / 100);
            if (data[barIndex].low <= trailStop) {
              exitPrice = trailStop;
              exitReason = 'Trailing Stop';
            }
          }
          
          // Default: exit at close
          if (!exitPrice) {
            exitPrice = data[barIndex].close;
            exitReason = 'Signal';
          }
          
          // Execute exit with slippage and commission
          var exitExecution = this.executeOrder(exitPrice, position.size, false);
          var grossPnl = (exitExecution.executionPrice - position.entryPrice) * position.size;
          var netPnl = grossPnl - exitExecution.totalCost - position.entryCost.totalCost;
          var pnlPercent = (netPnl / position.capitalAtRisk) * 100;
          
          capital += netPnl;
          if (capital < 0) capital = 0; // Prevent negative capital
          
          // Track streaks
          if (netPnl > 0) {
            winStreak++;
            loseStreak = 0;
            if (winStreak > maxWinStreak) maxWinStreak = winStreak;
          } else {
            loseStreak++;
            winStreak = 0;
            if (loseStreak > maxLoseStreak) maxLoseStreak = loseStreak;
          }
          
          // Record trade
          trades.push({
            entryTime: position.entryTime,
            exitTime: data[barIndex].time,
            entryPrice: position.entryPrice,
            exitPrice: exitExecution.executionPrice,
            size: position.size,
            grossPnl: grossPnl,
            netPnl: netPnl,
            pnlPercent: pnlPercent,
            exitReason: exitReason,
            barsHeld: barIndex - position.entryBarIndex,
            entryCosts: position.entryCost.totalCost,
            exitCosts: exitExecution.totalCost
          });
          
          // Track equity curve
          equityCurve.push({
            trade: trades.length,
            equity: capital,
            barIndex: barIndex,
            time: data[barIndex].time
          });
          
          // Track drawdown
          if (capital > peakCapital) peakCapital = capital;
          var currentDrawdown = peakCapital - capital;
          var currentDrawdownPercent = peakCapital > 0 ? (currentDrawdown / peakCapital) * 100 : 0;
          if (currentDrawdownPercent > maxDrawdownPercent) {
            maxDrawdown = currentDrawdown;
            maxDrawdownPercent = currentDrawdownPercent;
          }
          
          position = null;
        }
      }
      
      // ============================================
      // CHECK FOR ENTRY (if not in position)
      // ============================================
      if (!position) {
        var shouldEnter = this.getEntrySignal(data, barIndex, entryConfig);
        
        if (shouldEnter) {
          var entryPrice = data[barIndex].close;
          
          // Calculate stop loss price
          var stopLossPrice = null;
          if (riskConfig.stopLossPercent) {
            stopLossPrice = entryPrice * (1 - riskConfig.stopLossPercent / 100);
          }
          
          // Calculate position size
          var positionSize = this.calculatePositionSize(capital, entryPrice, stopLossPrice);
          
          if (positionSize > 0 && capital > 100) {
            // Execute entry with slippage and commission
            var entryExecution = this.executeOrder(entryPrice, positionSize, true);
            
            position = {
              entryPrice: entryExecution.executionPrice,
              size: positionSize,
              entryTime: data[barIndex].time,
              entryBarIndex: barIndex,
              capitalAtRisk: capital,
              entryCost: entryExecution,
              stopLossPercent: riskConfig.stopLossPercent || null,
              takeProfitPercent: riskConfig.takeProfitPercent || null,
              trailingStopPercent: riskConfig.trailingStopPercent || null,
              maxBars: riskConfig.maxBars || null,
              highestPrice: entryExecution.executionPrice
            };
          }
        }
      }
    }
    
    // Close any open position at last bar
    if (position) {
      var lastBar = data[data.length - 1];
      var exitExecution = this.executeOrder(lastBar.close, position.size, false);
      var grossPnl = (exitExecution.executionPrice - position.entryPrice) * position.size;
      var netPnl = grossPnl - exitExecution.totalCost - position.entryCost.totalCost;
      var pnlPercent = (netPnl / position.capitalAtRisk) * 100;
      
      capital += netPnl;
      if (capital < 0) capital = 0;
      
      trades.push({
        entryTime: position.entryTime,
        exitTime: lastBar.time,
        entryPrice: position.entryPrice,
        exitPrice: exitExecution.executionPrice,
        size: position.size,
        grossPnl: grossPnl,
        netPnl: netPnl,
        pnlPercent: pnlPercent,
        exitReason: 'End of Data',
        barsHeld: data.length - 1 - position.entryBarIndex,
        entryCosts: position.entryCost.totalCost,
        exitCosts: exitExecution.totalCost
      });
      
      equityCurve.push({
        trade: trades.length,
        equity: capital,
        barIndex: data.length - 1,
        time: lastBar.time
      });
    }
    
    // ============================================
    // CALCULATE PERFORMANCE METRICS
    // ============================================
    var results = this.calculateMetrics(trades, equityCurve, capital, initialCapital);
    results.equityCurve = equityCurve;
    results.trades = trades;
    results.config = {
      entry: entryConfig,
      exit: exitConfig,
      risk: riskConfig
    };
    
    // Clean up cache
    this._macdCache = null;
    
    return results;
  },

  // ============================================
  // PERFORMANCE METRICS CALCULATOR
  // ============================================

  /**
   * Calculate comprehensive performance metrics
   */
  calculateMetrics: function(trades, equityCurve, finalCapital, initialCapital) {
    var totalTrades = trades.length;
    
    if (totalTrades === 0) {
      return {
        error: true,
        message: 'No trades generated',
        totalTrades: 0,
        totalReturn: 0,
        totalReturnPercent: 0
      };
    }
    
    // Separate winning and losing trades
    var winningTrades = trades.filter(function(t) { return t.netPnl > 0; });
    var losingTrades = trades.filter(function(t) { return t.netPnl < 0; });
    
    var totalWins = winningTrades.length;
    var totalLosses = losingTrades.length;
    var winRate = (totalWins / totalTrades) * 100;
    
    // PnL metrics
    var totalGrossPnl = trades.reduce(function(sum, t) { return sum + t.grossPnl; }, 0);
    var totalNetPnl = trades.reduce(function(sum, t) { return sum + t.netPnl; }, 0);
    var totalReturn = finalCapital - initialCapital;
    var totalReturnPercent = ((finalCapital - initialCapital) / initialCapital) * 100;
    
    // Average trade metrics
    var avgTradeNet = totalNetPnl / totalTrades;
    var avgWin = totalWins > 0 ? winningTrades.reduce(function(sum, t) { return sum + t.netPnl; }, 0) / totalWins : 0;
    var avgLoss = totalLosses > 0 ? Math.abs(losingTrades.reduce(function(sum, t) { return sum + t.netPnl; }, 0)) / totalLosses : 0;
    
    // Best/Worst
    var bestTrade = trades.reduce(function(max, t) { return Math.max(max, t.netPnl); }, -Infinity);
    var worstTrade = trades.reduce(function(min, t) { return Math.min(min, t.netPnl); }, Infinity);
    
    // Profit factor
    var grossProfit = winningTrades.reduce(function(sum, t) { return sum + t.netPnl; }, 0);
    var grossLoss = Math.abs(losingTrades.reduce(function(sum, t) { return sum + t.netPnl; }, 0));
    var profitFactor = grossLoss > 0 ? grossProfit / grossLoss : grossProfit > 0 ? Infinity : 0;
    
    // Average holding period
    var avgBarsHeld = trades.reduce(function(sum, t) { return sum + (t.barsHeld || 0); }, 0) / totalTrades;
    
    // Max drawdown from equity curve
    var peak = initialCapital;
    var maxDD = 0;
    var maxDDPercent = 0;
    
    for (var i = 0; i < equityCurve.length; i++) {
      var equity = equityCurve[i].equity;
      if (equity > peak) peak = equity;
      var dd = peak - equity;
      var ddPercent = peak > 0 ? (dd / peak) * 100 : 0;
      if (ddPercent > maxDDPercent) {
        maxDD = dd;
        maxDDPercent = ddPercent;
      }
    }
    
    // Sharpe Ratio
    var returns = [];
    for (var i = 1; i < equityCurve.length; i++) {
      var r = (equityCurve[i].equity - equityCurve[i-1].equity) / equityCurve[i-1].equity;
      returns.push(r);
    }
    
    var avgReturn = returns.length > 0 ? returns.reduce(function(a, b) { return a + b; }, 0) / returns.length : 0;
    var variance = returns.length > 0 ? returns.reduce(function(a, b) { return a + Math.pow(b - avgReturn, 2); }, 0) / returns.length : 0;
    var stdDev = Math.sqrt(variance);
    var sharpeRatio = stdDev > 0 ? ((avgReturn - this.config.riskFreeRate / 252) / stdDev) * Math.sqrt(252) : 0;
    
    // Sortino Ratio (only considers downside deviation)
    var downsideReturns = returns.filter(function(r) { return r < 0; });
    var downsideVariance = downsideReturns.length > 0 ? downsideReturns.reduce(function(a, b) { return a + Math.pow(b, 2); }, 0) / returns.length : 0;
    var downsideDev = Math.sqrt(downsideVariance);
    var sortinoRatio = downsideDev > 0 ? ((avgReturn - this.config.riskFreeRate / 252) / downsideDev) * Math.sqrt(252) : 0;
    
    // Calmar Ratio
    var calmarRatio = maxDDPercent > 0 ? (totalReturnPercent / maxDDPercent) : 0;
    
    // Win/Loss streaks
    var maxWinStreak = 0, maxLoseStreak = 0;
    var currentWinStreak = 0, currentLoseStreak = 0;
    
    for (var i = 0; i < trades.length; i++) {
      if (trades[i].netPnl > 0) {
        currentWinStreak++;
        currentLoseStreak = 0;
        if (currentWinStreak > maxWinStreak) maxWinStreak = currentWinStreak;
      } else {
        currentLoseStreak++;
        currentWinStreak = 0;
        if (currentLoseStreak > maxLoseStreak) maxLoseStreak = currentLoseStreak;
      }
    }
    
    // Expectancy
    var expectancy = (winRate / 100 * avgWin) - ((1 - winRate / 100) * avgLoss);
    
    // Total costs
    var totalCommissions = trades.reduce(function(sum, t) { return sum + t.entryCosts + t.exitCosts; }, 0);
    
    return {
      // Basic stats
      totalTrades: totalTrades,
      totalWins: totalWins,
      totalLosses: totalLosses,
      winRate: parseFloat(winRate.toFixed(2)),
      
      // Return metrics
      totalGrossPnl: parseFloat(totalGrossPnl.toFixed(2)),
      totalNetPnl: parseFloat(totalNetPnl.toFixed(2)),
      totalReturn: parseFloat(totalReturn.toFixed(2)),
      totalReturnPercent: parseFloat(totalReturnPercent.toFixed(2)),
      
      // Trade averages
      avgTradeNet: parseFloat(avgTradeNet.toFixed(2)),
      avgWin: parseFloat(avgWin.toFixed(2)),
      avgLoss: parseFloat(avgLoss.toFixed(2)),
      bestTrade: parseFloat(bestTrade.toFixed(2)),
      worstTrade: parseFloat(worstTrade.toFixed(2)),
      
      // Ratios
      profitFactor: profitFactor === Infinity ? '∞' : parseFloat(profitFactor.toFixed(2)),
      sharpeRatio: parseFloat(sharpeRatio.toFixed(2)),
      sortinoRatio: parseFloat(sortinoRatio.toFixed(2)),
      calmarRatio: parseFloat(calmarRatio.toFixed(2)),
      
      // Risk metrics
      maxDrawdown: parseFloat(maxDD.toFixed(2)),
      maxDrawdownPercent: parseFloat(maxDDPercent.toFixed(2)),
      maxWinStreak: maxWinStreak,
      maxLoseStreak: maxLoseStreak,
      
      // Other
      expectancy: parseFloat(expectancy.toFixed(2)),
      avgBarsHeld: parseFloat(avgBarsHeld.toFixed(1)),
      totalCommissions: parseFloat(totalCommissions.toFixed(2)),
      
      // Final state
      initialCapital: initialCapital,
      finalCapital: parseFloat(finalCapital.toFixed(2))
    };
  },

  // ============================================
  // INITIALIZATION
  // ============================================
  
  init: function() {
    var backtestBtn = document.getElementById('backtest-btn');
    var runBtn = document.getElementById('run-backtest-btn');
    var modal = document.getElementById('backtest-modal');
    
    if (backtestBtn && modal) {
      backtestBtn.addEventListener('click', function() {
        modal.classList.add('visible');
      });
    }
    
    if (modal) {
      modal.querySelectorAll('.modal-close').forEach(function(btn) {
        btn.addEventListener('click', function() { modal.classList.remove('visible'); });
      });
      modal.addEventListener('click', function(e) {
        if (e.target === modal) modal.classList.remove('visible');
      });
    }
    
    if (runBtn) {
      var self = this;
      runBtn.addEventListener('click', function() { self.run(); });
    }
	
// ADD THIS TEST HANDLER
var testBtn = document.getElementById('test-backtest-btn');
if (testBtn) {
    var self = this;
    testBtn.addEventListener('click', function() {
        console.log('Running backtest quick test...');
        
        var state = window.TV.getState();
        
        if (!state || !state.candles || state.candles.length < 50) {
            alert('Not enough data. Need at least 50 candles. Currently: ' + (state && state.candles ? state.candles.length : 0));
            return;
        }
        
        var results = self.runBacktest(
            state.candles,
            { indicator: 'RSI', condition: 'below', value: 30 },
            { indicator: 'RSI', condition: 'above', value: 70 },
            { stopLossPercent: 5, takeProfitPercent: 10 }
        );
        
        if (results.error) {
            alert(results.message);
        } else {
            console.log('DEBUG - sortinoRatio:', results.sortinoRatio);
            console.log('DEBUG - calmarRatio:', results.calmarRatio);
            console.log('DEBUG - bestTrade:', results.bestTrade);
            console.log('DEBUG - worstTrade:', results.worstTrade);
            console.log('DEBUG - expectancy:', results.expectancy);
            console.log('DEBUG - maxWinStreak:', results.maxWinStreak);
            console.log('DEBUG - maxLoseStreak:', results.maxLoseStreak);
            console.log('DEBUG - totalCommissions:', results.totalCommissions);
            console.log('DEBUG - avgBarsHeld:', results.avgBarsHeld);
            
            var resultsDiv = document.getElementById('backtest-results');
            if (resultsDiv) {
                resultsDiv.style.display = 'block';
            }
            
            self.displayResults(results);
            
            alert(
                'Test Complete!\n\n' +
                'Trades: ' + results.totalTrades + '\n' +
                'Win Rate: ' + results.winRate + '%\n' +
                'Return: ' + results.totalReturnPercent.toFixed(2) + '%\n' +
                'Sharpe: ' + results.sharpeRatio + '\n' +
                'Max DD: ' + results.maxDrawdownPercent.toFixed(2) + '%'
            );
            
            console.log('Full results:', results);
        }
    });
}
    
    // Keyboard shortcut
    document.addEventListener('keydown', function(e) {
      if ((e.ctrlKey || e.metaKey) && e.key === 'b') {
        e.preventDefault();
        if (modal) modal.classList.add('visible');
      }
    });
    
    console.log('✅ Institutional Backtester Ready');
  },
  
  /**
   * Run backtest from UI inputs and display results
   */
  run: function() {
    var data = STATE.candles;
    if (!data || data.length < this.config.minBarsForStats) {
      if (typeof Toast !== 'undefined') {
        Toast.error('Need at least ' + this.config.minBarsForStats + ' candles for backtest');
      }
      return;
    }
    
    // Read entry config from UI
    var entryConfig = {
      indicator: document.getElementById('bt-entry-ind1')?.value || 'RSI',
      condition: document.getElementById('bt-entry-cond1')?.value || 'below',
      value: parseFloat(document.getElementById('bt-entry-val1')?.value) || 30
    };
    
    // Read exit config from UI
    var exitConfig = {
      indicator: document.getElementById('bt-exit-ind')?.value || 'RSI',
      condition: document.getElementById('bt-exit-cond')?.value || 'above',
      value: parseFloat(document.getElementById('bt-exit-val')?.value) || 70
    };
    
    // Risk config (using default values, can be extended with UI inputs)
    var riskConfig = {
      stopLossPercent: parseFloat(document.getElementById('bt-sl-percent')?.value) || 5,
      takeProfitPercent: parseFloat(document.getElementById('bt-tp-percent')?.value) || 10,
      trailingStopPercent: parseFloat(document.getElementById('bt-trail-percent')?.value) || 0,
      maxBars: parseInt(document.getElementById('bt-max-bars')?.value) || 0
    };
    
    console.log('🔬 Running institutional backtest...');
    console.log('Entry:', entryConfig);
    console.log('Exit:', exitConfig);
    console.log('Risk:', riskConfig);
    
    var results = this.runBacktest(data, entryConfig, exitConfig, riskConfig);
    
    if (results.error) {
      if (typeof Toast !== 'undefined') {
        Toast.error(results.message);
      }
      return;
    }
    
    this.displayResults(results);
  },
  
  /**
 * Populate individual result fields in the UI
 * This works regardless of which display function is called
 */
populateResultFields: function(results) {
    var setEl = function(id, val, color) {
        var el = document.getElementById(id);
        if (el) {
            el.textContent = val;
            if (color) el.style.color = color;
        } else {
            console.warn('Element not found:', id);
        }
    };
    
    // Main metrics
    setEl('bt-total-return', 
        (results.totalReturnPercent >= 0 ? '+' : '') + results.totalReturnPercent.toFixed(2) + '%',
        results.totalReturnPercent >= 0 ? 'var(--up-color)' : 'var(--down-color)');
    
    setEl('bt-win-rate', results.winRate.toFixed(1) + '%');
    setEl('bt-max-dd', results.maxDrawdownPercent.toFixed(2) + '%', 'var(--down-color)');
    setEl('bt-sharpe', results.sharpeRatio.toFixed(2));
    setEl('bt-trades', results.totalTrades);
    setEl('bt-profit-factor', 
        typeof results.profitFactor === 'string' ? results.profitFactor : results.profitFactor.toFixed(2));
    
    var avgEl = document.getElementById('bt-avg-trade');
    if (avgEl) {
        avgEl.textContent = (results.avgTradeNet >= 0 ? '+' : '') + '$' + results.avgTradeNet.toFixed(2);
        avgEl.style.color = results.avgTradeNet >= 0 ? 'var(--up-color)' : 'var(--down-color)';
    }
    
    // Additional metrics
    setEl('bt-agg-sharpe', results.sharpeRatio.toFixed(2));
    setEl('bt-agg-returns', 
        (results.totalReturnPercent >= 0 ? '+' : '') + results.totalReturnPercent.toFixed(2) + '%',
        results.totalReturnPercent >= 0 ? 'var(--up-color)' : 'var(--down-color)');
    setEl('bt-agg-dd', results.maxDrawdownPercent.toFixed(2) + '%');
    setEl('bt-agg-long', results.totalWins);
    setEl('bt-agg-short', results.totalLosses);
    
    console.log('✅ All result fields populated');
},

  
  /**
   * Display backtest results in the UI
   */
displayResults: function(results) {
    var resultsDiv = document.getElementById('backtest-results');
    if (!resultsDiv) return;
    
    resultsDiv.style.display = 'block';
    
    var setEl = function(id, val, color) {
        var el = document.getElementById(id);
        if (el) {
            el.textContent = val;
            if (color) el.style.color = color;
        }
    };
    
    // Row 1: Primary Metrics
    setEl('bt-total-return', (results.totalReturnPercent >= 0 ? '+' : '') + results.totalReturnPercent.toFixed(2) + '%',
        results.totalReturnPercent >= 0 ? 'var(--up-color)' : 'var(--down-color)');
    setEl('bt-win-rate', results.winRate.toFixed(1) + '%');
    setEl('bt-max-dd', results.maxDrawdownPercent.toFixed(2) + '%', 'var(--down-color)');
    setEl('bt-sharpe', results.sharpeRatio.toFixed(2));
    
    // Row 2: Secondary Metrics
    setEl('bt-sortino', results.sortinoRatio.toFixed(2));
    setEl('bt-calmar', results.calmarRatio.toFixed(2));
    setEl('bt-best-trade', '$' + results.bestTrade.toFixed(2), 'var(--up-color)');
    setEl('bt-worst-trade', '$' + results.worstTrade.toFixed(2), 'var(--down-color)');
    
    // Row 3: Advanced Metrics
    setEl('bt-expectancy', '$' + results.expectancy.toFixed(2));
    setEl('bt-max-win-streak', results.maxWinStreak);
    setEl('bt-max-lose-streak', results.maxLoseStreak);
    setEl('bt-total-costs', '$' + results.totalCommissions.toFixed(2));
    
    // Summary Bar
    setEl('bt-trades', results.totalTrades);
    setEl('bt-profit-factor', typeof results.profitFactor === 'string' ? results.profitFactor : results.profitFactor.toFixed(2));
    setEl('bt-avg-bars', results.avgBarsHeld.toFixed(1));
    
    var avgEl = document.getElementById('bt-avg-trade');
    if (avgEl) {
        avgEl.textContent = (results.avgTradeNet >= 0 ? '+' : '') + '$' + results.avgTradeNet.toFixed(2);
        avgEl.style.color = results.avgTradeNet >= 0 ? 'var(--up-color)' : 'var(--down-color)';
    }
    
    // Performance Table Row
    setEl('bt-agg-sharpe', results.sharpeRatio.toFixed(2));
    setEl('bt-agg-turnover', results.avgBarsHeld.toFixed(1));
    setEl('bt-agg-fitness', results.calmarRatio.toFixed(2));
    setEl('bt-agg-returns', (results.totalReturnPercent >= 0 ? '+' : '') + results.totalReturnPercent.toFixed(2) + '%',
        results.totalReturnPercent >= 0 ? 'var(--up-color)' : 'var(--down-color)');
    setEl('bt-agg-dd', results.maxDrawdownPercent.toFixed(2) + '%');
    setEl('bt-agg-margin', '$' + results.totalCommissions.toFixed(2));
    setEl('bt-agg-long', results.totalWins);
    setEl('bt-agg-short', results.totalLosses);
    
    // Fitness/Turnover cards (in right sidebar)
    setEl('bt-fitness', results.calmarRatio.toFixed(2));
    setEl('bt-turnover', results.avgBarsHeld.toFixed(1));
    setEl('bt-margin', '$' + results.totalCommissions.toFixed(2));
    
    if (typeof Toast !== 'undefined') {
        Toast.success('Backtest complete: ' + results.totalTrades + ' trades');
    }
    
    console.log('📊 Institutional Backtest Results:', results);
}
};

// ============================================
// ALERT SYSTEM 2.0
// ============================================
// ============================================
// PROFESSIONAL ALERT SYSTEM 3.0
// Multi-condition, persistent, notification-ready
// ============================================
const AlertSystem2 = {
  alerts: [],
  alertHistory: [],
  triggeredCache: {},
  maxHistory: 200,
  
  // ============================================
  // INITIALIZATION
  // ============================================
  init() {
    this.loadAlerts();
    this.loadHistory();
    this.setupModal();
    this.renderActiveAlerts();
    this.updateAlertBadge();
    
    console.log('✅ Professional Alert System 3.0 ready with ' + this.alerts.length + ' alerts');
  },
  
  // ============================================
  // DATA PERSISTENCE
  // ============================================
  loadAlerts() {
    var saved = localStorage.getItem('tvp_alerts_v3');
    if (saved) {
      try {
        this.alerts = JSON.parse(saved);
      } catch(e) {
        this.alerts = [];
      }
    }
  },
  
  saveAlerts() {
    localStorage.setItem('tvp_alerts_v3', JSON.stringify(this.alerts));
    this.updateAlertBadge();
  },
  
  loadHistory() {
    var saved = localStorage.getItem('tvp_alert_history');
    if (saved) {
      try {
        this.alertHistory = JSON.parse(saved);
      } catch(e) {
        this.alertHistory = [];
      }
    }
  },
  
  saveHistory() {
    if (this.alertHistory.length > this.maxHistory) {
      this.alertHistory = this.alertHistory.slice(-this.maxHistory);
    }
    localStorage.setItem('tvp_alert_history', JSON.stringify(this.alertHistory));
  },
  
  // ============================================
  // BADGE UPDATE
  // ============================================
  updateAlertBadge() {
    var activeCount = this.alerts.filter(function(a) { return a.active; }).length;
    var badge = document.getElementById('alert-count');
    if (badge) {
      badge.textContent = activeCount;
      badge.style.display = activeCount > 0 ? 'flex' : 'none';
    }
  },
  
  // ============================================
  // MODAL SETUP
  // ============================================
  setupModal() {
    var self = this;
    
    // Alert type tab switching
    document.querySelectorAll('.alert2-type-tab').forEach(function(tab) {
      var newTab = tab.cloneNode(true);
      tab.parentNode.replaceChild(newTab, tab);
      
      newTab.addEventListener('click', function() {
        document.querySelectorAll('.alert2-type-tab').forEach(function(t) {
          t.style.background = 'transparent';
          t.style.color = 'var(--text-muted)';
          t.classList.remove('active');
        });
        this.style.background = 'var(--accent-primary)';
        this.style.color = 'white';
        this.classList.add('active');
        
        var type = this.getAttribute('data-alert-type');
        document.querySelectorAll('.alert2-form-panel').forEach(function(p) {
          p.style.display = 'none';
        });
        var panel = document.getElementById('alert2-form-' + type);
        if (panel) panel.style.display = 'block';
      });
    });
    
    // Create alert button
    var createBtn = document.getElementById('create-alert2-btn');
    if (createBtn) {
      var newCreateBtn = createBtn.cloneNode(true);
      createBtn.parentNode.replaceChild(newCreateBtn, createBtn);
      newCreateBtn.addEventListener('click', function() { self.createAlert(); });
    }
    
    // Request notification permission button
    var notifBtn = document.getElementById('request-notif-perm');
    if (notifBtn) {
      notifBtn.addEventListener('click', function() {
        if ('Notification' in window) {
          Notification.requestPermission().then(function(perm) {
            if (perm === 'granted') {
              if (typeof Toast !== 'undefined') Toast.success('Notifications enabled!');
            }
          });
        }
      });
    }
  },
  
  // ============================================
  // CREATE ALERT
  // ============================================
  createAlert() {
    var activeTab = document.querySelector('.alert2-type-tab.active');
    var type = activeTab ? activeTab.getAttribute('data-alert-type') : 'price';
    var symbol = STATE.symbol;
    var currentPrice = STATE.currentPrice || 0;
    
    var alert = {
      id: U.genId(),
      symbol: symbol,
      type: type,
      active: true,
      triggered: false,
      repeatable: false,
      notify: 'toast',
      createdAt: new Date().toISOString(),
      createdPrice: currentPrice,
      createdInterval: STATE.interval
    };
    
    switch(type) {
      case 'price':
        alert.condition = document.getElementById('alert2-condition')?.value || 'above';
        alert.price = parseFloat(document.getElementById('alert2-price')?.value);
        alert.notify = document.getElementById('alert2-notify')?.value || 'toast';
        if (!alert.price || isNaN(alert.price) || alert.price <= 0) {
          if (typeof Toast !== 'undefined') Toast.error('Please enter a valid price');
          return;
        }
        break;
        
      case 'indicator':
        alert.indicator = document.getElementById('alert2-indicator')?.value || 'RSI';
        alert.condition = document.getElementById('alert2-ind-condition')?.value || 'above';
        alert.value = parseFloat(document.getElementById('alert2-ind-value')?.value);
        if (!alert.value || isNaN(alert.value)) {
          if (typeof Toast !== 'undefined') Toast.error('Please enter a valid value');
          return;
        }
        break;
        
      case 'volume':
        alert.multiplier = parseFloat(document.getElementById('alert2-vol-multiplier')?.value) || 2;
        break;
        
      case 'combo':
        alert.combo1 = document.getElementById('alert2-combo1')?.value || 'RSI_BELOW_30';
        alert.combo2 = document.getElementById('alert2-combo2')?.value || 'NONE';
        alert.notify = document.getElementById('alert2-notify')?.value || 'toast';
        break;
    }
    
    this.alerts.push(alert);
    this.saveAlerts();
    this.renderActiveAlerts();
    this.updateAlertBadge();
    
    // Clear input fields
    var priceInput = document.getElementById('alert2-price');
    var indValueInput = document.getElementById('alert2-ind-value');
    if (priceInput) priceInput.value = '';
    if (indValueInput) indValueInput.value = '70';
    
    if (typeof Toast !== 'undefined') {
      var desc = this.getAlertDescription(alert);
      Toast.success('Alert created: ' + desc);
    }
  },
  
  // ============================================
  // DELETE ALERT
  // ============================================
  deleteAlert(id) {
    this.alerts = this.alerts.filter(function(a) { return a.id !== id; });
    this.saveAlerts();
    this.renderActiveAlerts();
    this.updateAlertBadge();
    if (typeof Toast !== 'undefined') Toast.info('Alert deleted');
  },
  
  // ============================================
  // TOGGLE ALERT ACTIVE/INACTIVE
  // ============================================
  toggleAlert(id) {
    var alert = this.alerts.find(function(a) { return a.id === id; });
    if (alert) {
      alert.active = !alert.active;
      alert.triggered = false;
      this.saveAlerts();
      this.renderActiveAlerts();
      this.updateAlertBadge();
    }
  },
  
  // ============================================
  // GET ALERT DESCRIPTION
  // ============================================
  getAlertDescription(alert) {
    switch(alert.type) {
      case 'price':
        return alert.symbol.replace('USDT', '/USDT') + ' ' + alert.condition.replace('_', ' ') + ' $' + U.formatPrice(alert.price);
      case 'indicator':
        return alert.symbol.replace('USDT', '/USDT') + ' ' + alert.indicator + ' ' + alert.condition.replace('_', ' ') + ' ' + alert.value;
      case 'volume':
        return alert.symbol.replace('USDT', '/USDT') + ' Volume ' + alert.multiplier + 'x Spike';
      case 'combo':
        return alert.symbol.replace('USDT', '/USDT') + ' Combo: ' + alert.combo1.replace(/_/g, ' ') + (alert.combo2 !== 'NONE' ? ' + ' + alert.combo2.replace(/_/g, ' ') : '');
      default:
        return alert.symbol;
    }
  },
  
  // ============================================
  // RENDER ACTIVE ALERTS LIST
  // ============================================
  renderActiveAlerts() {
    var container = document.getElementById('active-alerts-2');
    if (!container) return;
    
    var active = this.alerts.filter(function(a) { return a.active; });
    var triggered = this.alerts.filter(function(a) { return !a.active; });
    
    // Update count
    var countEl = document.getElementById('alert2-count');
    if (countEl) {
      var totalActive = active.filter(function(a) { return !a.triggered; }).length;
      countEl.textContent = totalActive;
    }
    
    if (active.length === 0) {
      container.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-muted);font-size:11px;"><i class="fas fa-bell-slash"></i> No active alerts</div>';
      return;
    }
    
    var html = '<div style="font-size:10px;font-weight:600;color:var(--text-muted);margin-bottom:6px;">ACTIVE (' + active.filter(function(a) { return !a.triggered; }).length + ')</div>';
    
    active.forEach(function(a) {
      var desc = AlertSystem2.getAlertDescription(a);
      var typeIcon = a.type === 'price' ? '💵' : a.type === 'indicator' ? '📊' : a.type === 'volume' ? '📈' : '🔗';
      var typeBadge = a.type === 'price' ? 'Price' : a.type === 'indicator' ? 'Indicator' : a.type === 'volume' ? 'Volume' : 'Combo';
      var isTriggered = a.triggered;
      
      html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 12px;border:1px solid ' + (isTriggered ? 'var(--warning)' : 'var(--border-primary)') + ';border-radius:8px;margin-bottom:6px;background:' + (isTriggered ? 'var(--warning-muted)' : 'var(--bg-tertiary)') + ';transition:all 0.2s;">' +
        '<div style="flex:1;min-width:0;">' +
          '<div style="display:flex;align-items:center;gap:6px;margin-bottom:3px;">' +
            '<span style="font-size:14px;">' + typeIcon + '</span>' +
            '<span style="font-weight:600;font-size:11px;color:' + (isTriggered ? 'var(--warning)' : 'var(--text-primary)') + ';">' + desc + '</span>' +
            '<span style="font-size:8px;padding:1px 6px;border-radius:8px;background:' + (a.type === 'combo' ? 'var(--accent-muted)' : 'var(--bg-hover)') + ';color:var(--text-muted);">' + typeBadge + '</span>' +
          '</div>' +
          '<div style="font-size:9px;color:var(--text-muted);">' +
            (a.createdInterval || '') + ' · ' + new Date(a.createdAt).toLocaleDateString() +
            (isTriggered ? ' · <span style="color:var(--warning);">Triggered!</span>' : '') +
          '</div>' +
        '</div>' +
        '<div style="display:flex;gap:4px;flex-shrink:0;">' +
          '<button onclick="AlertSystem2.toggleAlert(\'' + a.id + '\')" style="background:none;border:none;color:' + (isTriggered ? 'var(--up-color)' : 'var(--text-muted)') + ';cursor:pointer;padding:6px 8px;font-size:12px;border-radius:4px;" title="' + (isTriggered ? 'Reset' : 'Deactivate') + '">' + (isTriggered ? '↻' : '⏸') + '</button>' +
          '<button onclick="AlertSystem2.deleteAlert(\'' + a.id + '\')" style="background:none;border:none;color:var(--danger);cursor:pointer;padding:6px 8px;font-size:14px;border-radius:4px;" title="Delete">✕</button>' +
        '</div>' +
      '</div>';
    });
    
    // Show alert history
    if (this.alertHistory.length > 0) {
      html += '<div style="margin-top:16px;border-top:1px solid var(--border-primary);padding-top:10px;">';
      html += '<div style="font-size:10px;font-weight:600;color:var(--text-muted);margin-bottom:6px;">RECENT TRIGGERS (' + Math.min(this.alertHistory.length, 5) + ')</div>';
      
      this.alertHistory.slice(-5).reverse().forEach(function(h) {
        html += '<div style="padding:6px 8px;font-size:10px;color:var(--text-muted);border-bottom:1px solid rgba(48,54,61,0.2);display:flex;justify-content:space-between;">' +
          '<span style="color:var(--warning);">🔔</span>' +
          '<span style="flex:1;margin-left:6px;">' + h.description + '</span>' +
          '<span style="font-size:9px;">' + U.timeAgo(h.timestamp) + '</span>' +
        '</div>';
      });
      
      html += '<button onclick="AlertSystem2.clearHistory()" style="width:100%;padding:6px;margin-top:4px;background:transparent;border:1px solid var(--border-primary);border-radius:4px;color:var(--text-muted);cursor:pointer;font-size:9px;">Clear History</button>';
      html += '</div>';
    }
    
    container.innerHTML = html;
  },
  
  // ============================================
  // CLEAR HISTORY
  // ============================================
  clearHistory() {
    this.alertHistory = [];
    this.saveHistory();
    this.renderActiveAlerts();
    if (typeof Toast !== 'undefined') Toast.info('Alert history cleared');
  },
  
  // ============================================
  // CHECK ALERTS - Called every second
  // ============================================
  checkAlerts() {
    if (!STATE.currentPrice || !STATE.candles || STATE.candles.length < 50) return;
    
    var self = this;
    var triggeredAny = false;
    
    this.alerts.forEach(function(alert) {
      if (!alert.active) return;
      if (alert.symbol !== STATE.symbol) return;
      if (alert.triggered) return;
      
      var shouldTrigger = false;
      var message = '';
      
      switch(alert.type) {
        case 'price':
          var price = STATE.currentPrice;
          if (alert.condition === 'above' && price >= alert.price) {
            shouldTrigger = true;
            message = alert.symbol.replace('USDT', '/USDT') + ' ABOVE $' + U.formatPrice(alert.price);
          } else if (alert.condition === 'below' && price <= alert.price) {
            shouldTrigger = true;
            message = alert.symbol.replace('USDT', '/USDT') + ' BELOW $' + U.formatPrice(alert.price);
          }
          break;
          
        case 'indicator':
          var indicatorValue = null;
          
          if (alert.indicator === 'RSI') {
            var rsiData = IndicatorEngine.calculateRSI(STATE.candles, 14);
            if (rsiData && rsiData.length > 0) indicatorValue = rsiData[rsiData.length - 1].value;
          } else if (alert.indicator === 'ATR') {
            var atrData = IndicatorEngine.calculateATR(STATE.candles, 14);
            if (atrData && atrData.length > 0) indicatorValue = atrData[atrData.length - 1].value;
          } else if (alert.indicator === 'STOCH') {
            var stochData = IndicatorEngine.calculateStochastic(STATE.candles, 14, 3);
            if (stochData && stochData.k && stochData.k.length > 0) indicatorValue = stochData.k[stochData.k.length - 1].value;
          }
          
          if (indicatorValue !== null) {
            if (alert.condition === 'above' && indicatorValue >= alert.value) {
              shouldTrigger = true;
              message = alert.symbol.replace('USDT', '/USDT') + ' ' + alert.indicator + ' ABOVE ' + alert.value + ' (' + indicatorValue.toFixed(1) + ')';
            } else if (alert.condition === 'below' && indicatorValue <= alert.value) {
              shouldTrigger = true;
              message = alert.symbol.replace('USDT', '/USDT') + ' ' + alert.indicator + ' BELOW ' + alert.value + ' (' + indicatorValue.toFixed(1) + ')';
            }
          }
          break;
          
        case 'volume':
          var recentVol = STATE.candles.slice(-5).reduce(function(s, c) { return s + c.volume; }, 0) / 5;
          var prevVol = STATE.candles.slice(-20, -5).reduce(function(s, c) { return s + c.volume; }, 0) / 15;
          if (prevVol > 0 && recentVol > prevVol * alert.multiplier) {
            shouldTrigger = true;
            message = alert.symbol.replace('USDT', '/USDT') + ' Volume Spike ' + alert.multiplier + 'x';
          }
          break;
          
        case 'combo':
          var cond1 = false, cond2 = false;
          var rsiCheck = IndicatorEngine.calculateRSI(STATE.candles, 14);
          var lastRsiVal = rsiCheck && rsiCheck.length > 0 ? rsiCheck[rsiCheck.length - 1].value : 50;
          var lastClose = STATE.candles[STATE.candles.length - 1].close;
          
          if (alert.combo1 === 'RSI_BELOW_30') cond1 = lastRsiVal < 30;
          if (alert.combo1 === 'RSI_ABOVE_70') cond1 = lastRsiVal > 70;
          if (alert.combo1 === 'PRICE_ABOVE_MA50') {
            var sma50 = IndicatorEngine.calculateSMA(STATE.candles, 50);
            cond1 = sma50 && sma50.length > 0 ? lastClose > sma50[sma50.length - 1].value : false;
          }
          if (alert.combo1 === 'VOL_SPIKE_2X') {
            var rv = STATE.candles.slice(-5).reduce(function(s, c) { return s + c.volume; }, 0) / 5;
            var pv = STATE.candles.slice(-20, -5).reduce(function(s, c) { return s + c.volume; }, 0) / 15;
            cond1 = pv > 0 && rv > pv * 2;
          }
          
          if (alert.combo2 === 'NONE') cond2 = true;
          else if (alert.combo2 === 'RSI_BELOW_30') cond2 = lastRsiVal < 30;
          else if (alert.combo2 === 'RSI_ABOVE_70') cond2 = lastRsiVal > 70;
          else if (alert.combo2 === 'PRICE_ABOVE_MA50') {
            var sma50b = IndicatorEngine.calculateSMA(STATE.candles, 50);
            cond2 = sma50b && sma50b.length > 0 ? lastClose > sma50b[sma50b.length - 1].value : false;
          }
          
          if (cond1 && cond2) {
            shouldTrigger = true;
            message = alert.symbol.replace('USDT', '/USDT') + ' Combo Alert!';
          }
          break;
      }
      
      if (shouldTrigger) {
        alert.triggered = true;
        triggeredAny = true;
        
        // Add to history
        self.alertHistory.push({
          alertId: alert.id,
          symbol: alert.symbol,
          description: message,
          price: STATE.currentPrice,
          timestamp: Date.now()
        });
        self.saveHistory();
        
        // Send notification
        if (alert.notify === 'browser' || alert.notify === 'all') {
          self.sendBrowserNotification(message);
        }
        if (alert.notify === 'sound' || alert.notify === 'all') {
          self.playAlertSound();
        }
        
        // Toast always shows
        if (typeof Toast !== 'undefined') {
          Toast.warning('🔔 ' + message, 8000);
        }
      }
    });
    
    if (triggeredAny) {
      this.saveAlerts();
      this.renderActiveAlerts();
      this.updateAlertBadge();
    }
  },
  
  // ============================================
  // BROWSER NOTIFICATION
  // ============================================
  sendBrowserNotification(message) {
    if ('Notification' in window && Notification.permission === 'granted') {
      try {
        new Notification('TradeVision Alert', {
          body: message,
          icon: 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text y=".9em" font-size="90">🔔</text></svg>',
          tag: 'tradevision-alert'
        });
      } catch(e) {}
    }
  },
  
  // ============================================
  // ALERT SOUND
  // ============================================
  playAlertSound() {
    try {
      var ctx = new (window.AudioContext || window.webkitAudioContext)();
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.frequency.value = 880;
      gain.gain.value = 0.3;
      osc.start();
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);
      osc.stop(ctx.currentTime + 0.4);
    } catch(e) {}
  }
};

// ============================================
// INITIALIZE PHASE 5 MODULES
// ============================================
(function initPhase5() {
  function initAll() {
    if (typeof MultiChart !== 'undefined') MultiChart.init();
    if (typeof Backtester !== 'undefined') Backtester.init();
    if (typeof AlertSystem2 !== 'undefined') AlertSystem2.init();
    
    // Update secondary chart prices every 2 seconds
    IntervalManager.register(function() {
  if (typeof MultiChart !== 'undefined' && MultiChart.layout !== 'single') {
    MultiChart.updateSecondaryPrices();
  }
}, 2000, 'MultiChart-priceUpdates');
    
    // Reload secondary charts when interval changes
    if (typeof window.TV !== 'undefined') {
      var originalSwitchInterval = window.TV.switchInterval;
      window.TV.switchInterval = function(interval) {
        originalSwitchInterval(interval);
        // Reload all visible secondary charts
        if (typeof MultiChart !== 'undefined') {
          for (var i = 2; i <= 4; i++) {
            var pane = document.getElementById('chart-pane-' + i);
            if (pane && pane.style.display !== 'none') {
              MultiChart.loadSecondaryChart(i);
            }
          }
        }
      };
    }
    
    // Indicator sync - when indicator is added to main, notify user
    if (typeof IndicatorEngine !== 'undefined') {
      var originalApply = IndicatorEngine.applyIndicator;
      IndicatorEngine.applyIndicator = function(name) {
        originalApply.call(this, name);
        // If in multi-chart mode, ask if user wants to apply to all
        if (typeof MultiChart !== 'undefined' && MultiChart.layout !== 'single') {
          setTimeout(function() {
            Toast.info('Indicator added to main chart. Use same settings on other charts for consistency.', 4000);
          }, 500);
        }
      };
    }
    
    console.log('✅ Phase 5 modules initialized');
  }
  
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
      setTimeout(initAll, 800);
    });
  } else {
    setTimeout(initAll, 800);
  }
})();


