// BUILD MOBILE WATCHLIST
// ============================================
// ============================================
// P0 FIX #4: BUILD MOBILE WATCHLIST - COMPLETE REWRITE
// Ensures proper data binding and event handling
// ============================================
function buildMobileWatchlist() {
  const container = document.getElementById('mobile-watchlist-list');
  if (!container) return;
  
  // Get current watchlist from STATE (always use the canonical source)
  const watchlist = STATE.watchlist || [];
  
  if (watchlist.length === 0) {
    container.innerHTML = `
      <div style="padding: 30px 20px; text-align: center; color: var(--text-muted);">
        <i class="fas fa-star" style="font-size: 28px; margin-bottom: 10px; display: block; opacity: 0.4;"></i>
        <div style="font-size: 13px; font-weight: 500; margin-bottom: 4px;">No symbols in watchlist</div>
        <div style="font-size: 10px; opacity: 0.7;">Use the search bar above to add symbols</div>
      </div>`;
    return;
  }
  
  // Build watchlist HTML
  const html = watchlist.map(item => {
    const sym = U.sanitizeAttr(item.symbol);
    const display = U.sanitize(item.symbol.replace('USDT', '/USDT'));
    
    return `
      <div class="mobile-wl-item" data-symbol="${sym}" style="
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 12px 10px;
        border-bottom: 1px solid rgba(48, 54, 61, 0.3);
        cursor: pointer;
        min-height: 48px;
        transition: background 0.15s ease;
      " onmousedown="this.style.background='var(--bg-hover)'" onmouseup="this.style.background='transparent'">
        
        <div style="flex: 1; min-width: 0;">
          <div style="font-weight: 700; font-size: 13px; color: var(--text-primary);">${display}</div>
          <div style="font-size: 9px; color: var(--text-muted); margin-top: 1px;">Binance</div>
        </div>
        
        <div style="text-align: right; margin-right: 8px; flex-shrink: 0;">
          <div style="font-weight: 600; font-size: 13px; font-family: 'SF Mono', 'Monaco', monospace;" 
               id="mwl-price-${sym}">--</div>
          <div style="font-size: 10px; padding: 2px 6px; border-radius: 4px; display: inline-block; margin-top: 2px;" 
               id="mwl-change-${sym}">--</div>
        </div>
        
        <button class="mwl-remove-btn" data-symbol="${sym}" style="
          background: none;
          border: none;
          color: var(--text-muted);
          cursor: pointer;
          padding: 8px;
          font-size: 14px;
          flex-shrink: 0;
          opacity: 0.4;
          border-radius: 6px;
          transition: all 0.15s ease;
        " onmouseenter="this.style.opacity='1';this.style.background='var(--danger-muted)';this.style.color='var(--danger)'" 
           onmouseleave="this.style.opacity='0.4';this.style.background='transparent';this.style.color='var(--text-muted)'"
           title="Remove from watchlist">✕</button>
      </div>
    `;
  }).join('');
  
  container.innerHTML = html;
  
  // ============================================
  // BIND CLICK HANDLERS
  // ============================================
  
  // Watchlist item click → switch symbol
  container.querySelectorAll('.mobile-wl-item').forEach(item => {
    item.addEventListener('click', function(e) {
      // Ignore clicks on remove button
      if (e.target.closest('.mwl-remove-btn')) return;
      
      const sym = this.getAttribute('data-symbol');
      if (!sym) return;
      
      // Switch the chart symbol
      if (typeof window.TV !== 'undefined' && window.TV.switchSymbol) {
        window.TV.switchSymbol(sym);
      } else if (typeof DataManager !== 'undefined' && DataManager.switchSymbol) {
        DataManager.switchSymbol(sym);
      }
      
      // Show toast notification
      if (typeof Toast !== 'undefined') {
        Toast.info('Switched to ' + sym.replace('USDT', '/USDT'), 1500);
      }
      
      // Add haptic feedback if available
      if (navigator.vibrate) {
        navigator.vibrate(10);
      }
    });
  });
  
  // Remove button click → remove from watchlist
  container.querySelectorAll('.mwl-remove-btn').forEach(btn => {
    btn.addEventListener('click', function(e) {
      e.stopPropagation();
      e.preventDefault();
      
      const sym = this.getAttribute('data-symbol');
      if (!sym) return;
      
      // Add haptic feedback for removal
      if (navigator.vibrate) {
        navigator.vibrate([10, 30, 10]);
      }
      
      // Remove from watchlist
      if (typeof window.TV !== 'undefined' && window.TV.removeFromWatchlist) {
        window.TV.removeFromWatchlist(sym);
      } else {
        // Direct removal fallback
        STATE.watchlist = STATE.watchlist.filter(item => item.symbol !== sym);
        StorageManager.set(CONFIG.STORAGE_KEYS.WATCHLIST, STATE.watchlist);
        
        // Refresh display
        if (typeof WatchlistManager !== 'undefined' && WatchlistManager.render) {
          WatchlistManager.render();
        }
      }
      
      // Rebuild mobile watchlist immediately
      buildMobileWatchlist();
      
      if (typeof Toast !== 'undefined') {
        Toast.info(sym.replace('USDT', '/USDT') + ' removed from watchlist');
      }
    });
  });
  
  console.log('✅ P0-4: Mobile watchlist built with', watchlist.length, 'items');
}

// ============================================
// BUILD MOBILE INDICATORS GRID
// ============================================
function buildMobileIndicators() {
  const container = document.getElementById('mobile-indicators-grid');
  if (!container) return;
  
  const indicators = [
    'RSI', 'MACD', 'SMA', 'EMA', 'Bollinger', 'VWAP',
    'Stochastic', 'ATR', 'Ichimoku', 'SuperTrend', 'PSAR',
    'CCI', 'WilliamsR', 'Keltner', 'OBV', 'MFI'
  ];
  
  container.innerHTML = indicators.map(function(ind) {
    const isActive = STATE.activeIndicators && STATE.activeIndicators.has(ind);
    return `
      <button class="sheet-indicator-btn ${isActive ? 'active' : ''}" 
              data-indicator="${ind}"
              style="background: ${isActive ? 'var(--accent-muted)' : 'var(--bg-tertiary)'};
                     border-color: ${isActive ? 'var(--accent-primary)' : 'var(--border-primary)'};
                     color: ${isActive ? 'var(--accent-primary)' : 'var(--text-secondary)'};">
        ${ind}
      </button>
    `;
  }).join('');
  
  // Add click handlers
  container.querySelectorAll('.sheet-indicator-btn').forEach(function(btn) {
    btn.addEventListener('click', function(e) {
      e.stopPropagation();
      
      const ind = this.getAttribute('data-indicator');
      
      if (ind && typeof IndicatorEngine !== 'undefined') {
        IndicatorEngine.toggleIndicator(ind);
        
        // Refresh the grid to update active states
        setTimeout(function() {
          buildMobileIndicators();
        }, 300);
      }
    });
  });
}

// ============================================
// UPDATE MOBILE STATS
// ============================================
function updateMobileStats() {
  const lastCandle = STATE.candles && STATE.candles.length > 0 
    ? STATE.candles[STATE.candles.length - 1] 
    : null;
  
  if (lastCandle) {
    const setVal = function(id, val) {
      const el = document.getElementById(id);
      if (el) el.textContent = val;
    };
    
    setVal('ms-open', typeof U !== 'undefined' ? U.formatPrice(lastCandle.open) : lastCandle.open.toFixed(2));
    setVal('ms-high', typeof U !== 'undefined' ? U.formatPrice(lastCandle.high) : lastCandle.high.toFixed(2));
    setVal('ms-low', typeof U !== 'undefined' ? U.formatPrice(lastCandle.low) : lastCandle.low.toFixed(2));
    setVal('ms-volume', typeof U !== 'undefined' ? U.formatVolume(lastCandle.volume) : lastCandle.volume.toFixed(2));
    
    const changeEl = document.getElementById('ms-change');
    if (changeEl && STATE.change24h !== null) {
      const change = STATE.change24h;
      changeEl.textContent = (change >= 0 ? '+' : '') + change.toFixed(2) + '%';
      changeEl.style.color = change >= 0 ? 'var(--up-color)' : 'var(--down-color)';
    }
  } else {
    // No data yet
    ['ms-open', 'ms-high', 'ms-low', 'ms-volume', 'ms-change'].forEach(function(id) {
      const el = document.getElementById(id);
      if (el) el.textContent = '--';
    });
  }
}

// ============================================
// UPDATE MOBILE PRICES (LIVE)
// ============================================
function updateMobilePrices() {
  // Update every 2 seconds
  setInterval(function() {
    if (!STATE.currentPrice) return;
    
    // Update header price
    const priceEl = document.getElementById('mobile-price');
    const symbolEl = document.getElementById('mobile-symbol-name');
    const changeBadge = document.getElementById('mobile-change-badge');
    
    if (priceEl) {
      priceEl.textContent = typeof U !== 'undefined' 
        ? U.formatPrice(STATE.currentPrice) 
        : STATE.currentPrice.toFixed(2);
      priceEl.style.color = (STATE.change24h || 0) >= 0 
        ? 'var(--up-color)' 
        : 'var(--down-color)';
    }
    
    if (symbolEl) {
      symbolEl.textContent = STATE.symbol.replace('USDT', '/USDT');
    }
    
    if (changeBadge && STATE.change24h !== null) {
      const change = STATE.change24h;
      changeBadge.textContent = (change >= 0 ? '+' : '') + change.toFixed(2) + '%';
      changeBadge.className = 'mobile-change-badge ' + (change >= 0 ? 'up' : 'down');
    }
    
    // Update watchlist prices in sheet
    document.querySelectorAll('#mobile-watchlist-list .mobile-wl-item').forEach(function(item) {
      const sym = item.getAttribute('data-symbol');
      const data = STATE.marketData?.get(sym);
      
      const priceDisplay = document.getElementById('mwl-price-' + sym);
      const changeDisplay = document.getElementById('mwl-change-' + sym);
      
      if (priceDisplay && data?.price) {
        priceDisplay.textContent = '$' + (typeof U !== 'undefined' 
          ? U.formatPrice(data.price) 
          : data.price.toFixed(2));
      }
      
      if (changeDisplay && data?.change !== undefined) {
        changeDisplay.textContent = (data.change >= 0 ? '+' : '') + data.change.toFixed(2) + '%';
        changeDisplay.style.color = data.change >= 0 ? 'var(--up-color)' : 'var(--down-color)';
        changeDisplay.style.background = data.change >= 0 ? 'var(--up-muted)' : 'var(--down-muted)';
      }
    });
  }, 2000);
}

// ============================================
// ECONOMIC CALENDAR MODULE - FIXED
// ============================================
const EconomicCalendar = {
  async init() {
    await this.fetchEvents();
    IntervalManager.register(() => this.fetchEvents(), 3600000, 'EconomicCalendar-refresh'); // refresh hourly
  },

  async fetchEvents() {
    const container = document.getElementById('economic-calendar-list');
    if (!container) return;
    
    container.innerHTML = '<div style="padding:10px;text-align:center;color:var(--text-muted);"><i class="fas fa-spinner fa-spin"></i> Loading...</div>';
    
    try {
      // Try Finnhub first
      const today = new Date();
      const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
      const from = today.toISOString().slice(0,10);
      const to = nextWeek.toISOString().slice(0,10);
      
      let events = [];
      
      try {
        const res = await fetch(`https://finnhub.io/api/v1/calendar/economic?from=${from}&to=${to}&token=${CONFIG.FINNHUB_API_KEY}`);
        if (res.ok) {
          const data = await res.json();
          if (data.economicCalendar && data.economicCalendar.length > 0) {
            events = data.economicCalendar.filter(e => e.impact && parseFloat(e.impact) >= 2);
          }
        }
      } catch(e) {
        console.warn('Finnhub economic calendar failed:', e.message);
      }
      
      // Fallback: Use hardcoded major economic events for this week
      if (!events || events.length === 0) {
        events = this.getFallbackEvents();
      }
      
      STATE.economicEvents = events.slice(0, 20);
      this.render();
      
    } catch(e) {
      console.error('Economic calendar error:', e);
      const events = this.getFallbackEvents();
      STATE.economicEvents = events;
      this.render();
    }
  },
  
  getFallbackEvents() {
    const today = new Date();
    const dayOfWeek = today.getDay();
    const monday = new Date(today);
    monday.setDate(today.getDate() - dayOfWeek + 1);
    
    // Generate dates for this week
    const days = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      days.push(d);
    }
    
    // Common high-impact economic events
    const weeklyEvents = [
      // Monday
      { date: days[0], event: 'ISM Manufacturing PMI', country: 'US', impact: '3', previous: '47.2', forecast: '47.5', actual: null },
      { date: days[0], event: 'Construction Spending MoM', country: 'US', impact: '2', previous: '0.1%', forecast: '0.2%', actual: null },
      
      // Tuesday
      { date: days[1], event: 'JOLTS Job Openings', country: 'US', impact: '3', previous: '8.73M', forecast: '8.65M', actual: null },
      { date: days[1], event: 'Factory Orders MoM', country: 'US', impact: '2', previous: '-3.6%', forecast: '0.3%', actual: null },
      
      // Wednesday
      { date: days[2], event: 'ADP Employment Change', country: 'US', impact: '3', previous: '107K', forecast: '130K', actual: null },
      { date: days[2], event: 'ISM Services PMI', country: 'US', impact: '3', previous: '53.4', forecast: '52.8', actual: null },
      { date: days[2], event: 'Crude Oil Inventories', country: 'US', impact: '2', previous: '-2.2M', forecast: '-1.5M', actual: null },
      
      // Thursday
      { date: days[3], event: 'Initial Jobless Claims', country: 'US', impact: '3', previous: '215K', forecast: '218K', actual: null },
      { date: days[3], event: 'Trade Balance', country: 'US', impact: '2', previous: '-$62.2B', forecast: '-$63.0B', actual: null },
      { date: days[3], event: 'ECB Interest Rate Decision', country: 'EU', impact: '3', previous: '4.50%', forecast: '4.50%', actual: null },
      
      // Friday
      { date: days[4], event: 'Nonfarm Payrolls', country: 'US', impact: '3', previous: '216K', forecast: '175K', actual: null },
      { date: days[4], event: 'Unemployment Rate', country: 'US', impact: '3', previous: '3.7%', forecast: '3.8%', actual: null },
      { date: days[4], event: 'Average Hourly Earnings YoY', country: 'US', impact: '2', previous: '4.5%', forecast: '4.4%', actual: null },
      
      // Weekend events
      { date: days[5], event: 'Consumer Credit Change', country: 'US', impact: '1', previous: '$1.56B', forecast: '$3.5B', actual: null },
      
      // Crypto-specific events
      { date: days[2], event: 'Bitcoin ETF Flow Data', country: 'US', impact: '2', previous: '+$125M', forecast: '--', actual: null },
      { date: days[4], event: 'CME Bitcoin Futures Expiry', country: 'US', impact: '2', previous: '--', forecast: '--', actual: null },
    ];
    
    return weeklyEvents;
  },

  render() {
    const container = document.getElementById('economic-calendar-list');
    if (!container) return;
    
    if (!STATE.economicEvents || STATE.economicEvents.length === 0) {
      container.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-muted);">No high‑impact events this week.</div>';
      return;
    }

    container.innerHTML = STATE.economicEvents.map(e => {
      const eventDate = new Date(e.date);
      const today = new Date();
      const isToday = eventDate.toDateString() === today.toDateString();
      
      const dateStr = eventDate.toLocaleDateString('en-US', { 
        weekday: 'short', 
        month: 'short', 
        day: 'numeric' 
      });
      
      const actual = e.actual !== null && e.actual !== undefined ? e.actual : '--';
      const previous = e.previous || '--';
      const forecast = e.forecast || '--';
      const impactStars = '★'.repeat(Math.min(parseInt(e.impact) || 1, 3)) + '☆'.repeat(Math.max(3 - (parseInt(e.impact) || 1), 0));
      
      const impactColors = {
        '1': 'var(--text-muted)',
        '2': '#ff9800',
        '3': '#ef5350'
      };
      const impactColor = impactColors[e.impact] || 'var(--text-muted)';
      
      return `
        <div style="
          margin-bottom: 6px; 
          padding: 8px 10px; 
          background: ${isToday ? 'var(--accent-muted)' : 'var(--bg-primary)'}; 
          border-radius: 6px;
          border-left: 3px solid ${impactColor};
          ${isToday ? 'border: 1px solid var(--accent-primary);' : ''}
        ">
          <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom: 4px;">
            <span style="font-size: 10px; color: var(--text-muted);">
              ${isToday ? '🔴 TODAY · ' : ''}${dateStr}
            </span>
            <span style="display:flex; align-items:center; gap: 4px;">
              <span style="font-size: 9px; color: var(--text-muted);">${e.country}</span>
              <span style="color: ${impactColor}; font-size: 10px; letter-spacing: 1px;">${impactStars}</span>
            </span>
          </div>
          <div style="font-weight: 600; font-size: 12px; margin-bottom: 4px; color: var(--text-primary);">${e.event}</div>
          <div style="display:flex; justify-content:space-between; font-size: 10px;">
            <span style="color: var(--text-muted);">Prev: <b style="color: var(--text-secondary);">${previous}</b></span>
            <span style="color: var(--text-muted);">Forecast: <b style="color: var(--accent-primary);">${forecast}</b></span>
            <span style="color: var(--text-muted);">Actual: <b style="color: var(--success);">${actual}</b></span>
          </div>
        </div>`;
    }).join('');
    
    // Add last updated timestamp
    const now = new Date();
    container.innerHTML += `
      <div style="text-align:center;font-size:9px;color:var(--text-muted);padding:8px;border-top:1px solid var(--border-primary);margin-top:4px;">
        <i class="fas fa-sync-alt"></i> Updated ${now.toLocaleTimeString()} · Data may be delayed
      </div>
    `;
  }
};

