// ============================================
// 1. MOBILE SYMBOL SEARCH DROPDOWN
// ============================================
function setupMobileSymbolSearch() {
    if (window.innerWidth > 768) return;
    
    var symbolArea = document.getElementById('mobile-symbol-area');
    var searchDropdown = document.getElementById('mobile-search-overlay');
    var searchInput = document.getElementById('mobile-search-input');
    var searchClose = document.getElementById('mobile-search-close-btn');
    var searchResults = document.getElementById('mobile-search-results');
    var searchTabs = document.querySelectorAll('.mobile-search-tab');
    
    if (!symbolArea || !searchDropdown) {
        console.warn('Mobile search elements not found');
        return;
    }
    
    // Default symbols to show when opening
    var defaultSymbols = [
        { symbol: 'BTCUSDT', name: 'Bitcoin', type: 'crypto' },
        { symbol: 'ETHUSDT', name: 'Ethereum', type: 'crypto' },
        { symbol: 'BNBUSDT', name: 'BNB', type: 'crypto' },
        { symbol: 'SOLUSDT', name: 'Solana', type: 'crypto' },
        { symbol: 'XRPUSDT', name: 'Ripple', type: 'crypto' },
        { symbol: 'ADAUSDT', name: 'Cardano', type: 'crypto' },
        { symbol: 'DOGEUSDT', name: 'Dogecoin', type: 'crypto' },
        { symbol: 'AAPL', name: 'Apple Inc.', type: 'stocks' },
        { symbol: 'TSLA', name: 'Tesla Inc.', type: 'stocks' },
        { symbol: 'MSFT', name: 'Microsoft Corp.', type: 'stocks' },
        { symbol: 'EURUSD', name: 'Euro/US Dollar', type: 'forex' },
        { symbol: 'GBPUSD', name: 'Pound/US Dollar', type: 'forex' }
    ];
    
    var currentTab = 'all';
    
    // Render search results
    function renderResults(symbols) {
        if (!searchResults) return;
        
        if (!symbols || symbols.length === 0) {
            searchResults.innerHTML = '<div style="padding:30px;text-align:center;color:var(--text-muted);font-size:14px;">No results found</div>';
            return;
        }
        
        var html = '';
        for (var i = 0; i < symbols.length; i++) {
            var s = symbols[i];
            var displaySym = s.symbol.indexOf('USDT') > -1 ? s.symbol.replace('USDT', '/USDT') : s.symbol;
            var typeLabel = s.type === 'crypto' ? 'Crypto' : s.type === 'stocks' ? 'Stock' : 'Forex';
            var bgColor = s.type === 'crypto' ? 'rgba(88,166,255,0.1)' : s.type === 'stocks' ? 'rgba(38,166,154,0.1)' : 'rgba(255,152,0,0.1)';
            var txtColor = s.type === 'crypto' ? '#58a6ff' : s.type === 'stocks' ? '#26a69a' : '#ff9800';
            
                        html += '<div class="mobile-search-result-item" data-symbol="' + U.sanitizeAttr(s.symbol) + '" data-type="' + U.sanitizeAttr(s.type) + '">' +
                '<div>' +
                    '<div class="mobile-search-result-symbol">' + U.sanitize(displaySym) + '</div>' +
                    '<div class="mobile-search-result-name">' + U.sanitize(s.name || s.symbol) + '</div>' +
                '</div>' +
                '<span style="font-size:10px;padding:3px 8px;border-radius:10px;font-weight:600;background:' + bgColor + ';color:' + txtColor + ';">' + U.sanitize(typeLabel) + '</span>' +
            '</div>';
        }
        
        searchResults.innerHTML = html;
        
        // Add click handlers to each result
        var items = searchResults.querySelectorAll('.mobile-search-result-item');
        for (var j = 0; j < items.length; j++) {
            (function(item) {
                item.addEventListener('click', function() {
                    var symbol = this.getAttribute('data-symbol');
                    var type = this.getAttribute('data-type');
                    
                    // Set asset type
                    if (type) {
                        STATE.assetType = type;
                    }
                    
                    // Switch symbol
                    if (typeof window.TV !== 'undefined' && window.TV.switchSymbol) {
                        window.TV.switchSymbol(symbol);
                    }
                    
                    // Update mobile header display
                    var nameEl = document.getElementById('mobile-symbol-name');
                    if (nameEl) {
                        nameEl.textContent = symbol.indexOf('USDT') > -1 ? symbol.replace('USDT', '/USDT') : symbol;
                    }
                    
                    // Close search
                    closeSearch();
                });
            })(items[j]);
        }
    }
    
    function closeSearch() {
        if (searchDropdown) {
            searchDropdown.classList.remove('visible');
        }
        if (searchInput) {
            searchInput.value = '';
        }
        if (searchResults) {
            searchResults.innerHTML = '';
        }
    }
    
    // ============================================
    // OPEN SEARCH - Click on symbol area
    // ============================================
    symbolArea.addEventListener('click', function() {
        if (searchDropdown) {
            searchDropdown.classList.add('visible');
        }
        if (searchInput) {
            searchInput.value = '';
            setTimeout(function() {
                searchInput.focus();
            }, 100);
        }
        renderResults(defaultSymbols);
    });
    
    // ============================================
    // OPEN SEARCH - Click on search button
    // ============================================
    var searchBtn = document.getElementById('mobile-search-btn');
    if (searchBtn) {
        searchBtn.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            
            if (searchDropdown) {
                searchDropdown.classList.add('visible');
            }
            if (searchInput) {
                searchInput.value = '';
                setTimeout(function() {
                    searchInput.focus();
                }, 100);
            }
            renderResults(defaultSymbols);
        });
    }
    
    // ============================================
    // CLOSE SEARCH
    // ============================================
    if (searchClose) {
        searchClose.addEventListener('click', function() {
            closeSearch();
        });
    }
    
    // Close on overlay click (click outside the search dropdown)
    if (searchDropdown) {
        searchDropdown.addEventListener('click', function(e) {
            if (e.target === searchDropdown) {
                closeSearch();
            }
        });
    }
    
    // ============================================
    // SEARCH INPUT HANDLER
    // ============================================
    if (searchInput) {
        searchInput.addEventListener('input', function() {
            var query = this.value.trim().toUpperCase();
            
            if (query.length < 1) {
                renderResults(defaultSymbols);
                return;
            }
            
            var results = [];
            
            // Search crypto symbols from available symbols
            if (typeof STATE !== 'undefined' && STATE.availableSymbols && STATE.availableSymbols.length) {
                for (var k = 0; k < STATE.availableSymbols.length; k++) {
                    var s = STATE.availableSymbols[k];
                    if (s.symbol.indexOf(query) > -1 || (s.baseAsset && s.baseAsset.indexOf(query) > -1)) {
                        results.push({ symbol: s.symbol, name: s.baseAsset, type: 'crypto' });
                        if (results.length >= 10) break;
                    }
                }
            }
            
            // Search stock symbols
            if (typeof STATE !== 'undefined' && STATE.stockSymbols && STATE.stockSymbols.length) {
                for (var m = 0; m < STATE.stockSymbols.length; m++) {
                    var st = STATE.stockSymbols[m];
                    if (st.symbol.indexOf(query) > -1 || (st.description && st.description.toUpperCase().indexOf(query) > -1)) {
                        results.push({ symbol: st.symbol, name: st.description || st.symbol, type: 'stocks' });
                        if (results.length >= 15) break;
                    }
                }
            }
            
            // Fallback to default symbols
            if (results.length === 0) {
                for (var n = 0; n < defaultSymbols.length; n++) {
                    var ds = defaultSymbols[n];
                    if (ds.symbol.indexOf(query) > -1 || ds.name.toUpperCase().indexOf(query) > -1) {
                        results.push(ds);
                    }
                }
            }
            
            renderResults(results.slice(0, 15));
        });
        
        // Handle Enter key
        searchInput.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') {
                closeSearch();
            }
        });
    }
    
    // ============================================
    // SEARCH TABS
    // ============================================
    if (searchTabs && searchTabs.length) {
        for (var t = 0; t < searchTabs.length; t++) {
            (function(tab) {
                tab.addEventListener('click', function() {
                    // Remove active from all tabs
                    for (var u = 0; u < searchTabs.length; u++) {
                        searchTabs[u].classList.remove('active');
                    }
                    // Set active on clicked tab
                    this.classList.add('active');
                    
                    currentTab = this.getAttribute('data-tab') || 'all';
                    
                    // Refilter results if there's a query
                    if (searchInput && searchInput.value.trim().length > 0) {
                        searchInput.dispatchEvent(new Event('input'));
                    } else if (currentTab !== 'all') {
                        // Filter default symbols by type
                        var filtered = defaultSymbols.filter(function(s) {
                            return s.type === currentTab;
                        });
                        renderResults(filtered);
                    } else {
                        renderResults(defaultSymbols);
                    }
                });
            })(searchTabs[t]);
        }
    }
    
    console.log('✅ Mobile symbol search ready');
}

// ============================================
// 2. MOBILE TIMEFRAME OVERLAY & MODAL
// ============================================
function setupMobileTimeframe() {
  if (window.innerWidth > 768) return;
  
  var tfBtn = document.getElementById('mobile-tf-fixed-btn');
  var tfModal = document.getElementById('mobile-tf-modal');
  var tfLabel = document.getElementById('mobile-tf-label-fixed');
  
  if (!tfBtn || !tfModal) {
    console.warn('⚠️ P0-2: Timeframe button or modal not found in DOM');
    return;
  }
  
  // Set initial label from current state
  if (tfLabel) {
    tfLabel.textContent = (typeof STATE !== 'undefined' && STATE.interval) ? STATE.interval : '15m';
  }
  
  // ============================================
  // OPEN MODAL ON CLICK
  // ============================================
  tfBtn.addEventListener('click', function(e) {
    e.preventDefault();
    e.stopPropagation();
    
    // Get current interval
    var currentInterval = (typeof STATE !== 'undefined' && STATE.interval) ? STATE.interval : '15m';
    
    // Update active state on all modal option buttons
    var options = tfModal.querySelectorAll('.mobile-tf-option');
    for (var i = 0; i < options.length; i++) {
      var opt = options[i];
      var optInterval = opt.getAttribute('data-interval');
      var isActive = (optInterval === currentInterval);
      
      opt.classList.toggle('active', isActive);
      opt.style.background = isActive ? 'var(--accent-muted)' : 'var(--bg-tertiary)';
      opt.style.borderColor = isActive ? 'var(--accent-primary)' : 'var(--border-primary)';
      opt.style.color = isActive ? 'var(--accent-primary)' : 'var(--text-primary)';
      opt.style.fontWeight = isActive ? '700' : '600';
    }
    
    // Show modal with animation
    tfModal.classList.add('open');
  });
  
  // ============================================
  // CLOSE MODAL HANDLERS
  // ============================================
  var closeBtn = document.querySelector('.mobile-tf-modal-close');
  if (closeBtn) {
    closeBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      tfModal.classList.remove('open');
    });
  }
  
  // Close on overlay click
  tfModal.addEventListener('click', function(e) {
    if (e.target === tfModal) {
      tfModal.classList.remove('open');
    }
  });
  
  // Close on Escape key
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && tfModal.classList.contains('open')) {
      tfModal.classList.remove('open');
    }
  });
  
  // ============================================
  // TIMEFRAME OPTION CLICKS
  // ============================================
  document.querySelectorAll('.mobile-tf-option').forEach(function(btn) {
    // Remove old listeners by cloning
    var newBtn = btn.cloneNode(true);
    btn.parentNode.replaceChild(newBtn, btn);
    
    newBtn.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      
      var interval = this.getAttribute('data-interval');
      if (!interval) return;
      
      // Switch chart interval
      if (typeof window.TV !== 'undefined' && window.TV.switchInterval) {
        window.TV.switchInterval(interval);
      } else if (typeof DataManager !== 'undefined' && DataManager.switchInterval) {
        DataManager.switchInterval(interval);
      }
      
      // Update button label
      if (tfLabel) {
        tfLabel.textContent = interval;
      }
      
      // Update modal active state
      document.querySelectorAll('.mobile-tf-option').forEach(function(b) {
        b.classList.remove('active');
        b.style.background = 'var(--bg-tertiary)';
        b.style.borderColor = 'var(--border-primary)';
        b.style.color = 'var(--text-primary)';
        b.style.fontWeight = '600';
      });
      
      this.classList.add('active');
      this.style.background = 'var(--accent-muted)';
      this.style.borderColor = 'var(--accent-primary)';
      this.style.color = 'var(--accent-primary)';
      this.style.fontWeight = '700';
      
      // Update footer timeframe buttons
      document.querySelectorAll('.ftf-btn:not(.ftf-more)').forEach(function(b) {
        b.classList.toggle('active', b.getAttribute('data-interval') === interval);
      });
      
      // Close modal
      tfModal.classList.remove('open');
      
      // Show toast
      if (typeof Toast !== 'undefined') {
        Toast.info('Timeframe: ' + interval, 1500);
      }
      
      console.log('✅ P0-2: Timeframe switched to', interval);
    });
  });
  
  console.log('✅ P0-2: Mobile timeframe button + modal setup complete');
}

// ============================================
// 3. MOBILE RIGHT PANEL SLIDE-OUT
// ============================================
// ============================================
// MOBILE RIGHT PANEL SLIDE-OUT (FIXED v2.0)
// Uses event delegation instead of broken cloning
// ============================================
function setupMobileRightPanel() {
    if (window.innerWidth > 768) return;
    
    var panel = document.getElementById('mobile-right-panel');
    var overlay = document.getElementById('mobile-panel-overlay');
    var toggleBtn = document.getElementById('mobile-panel-toggle-btn');
    var closeBtn = document.getElementById('mobile-panel-close');
    var panelContent = document.getElementById('mobile-panel-content');
    var rightSidebar = document.getElementById('right-sidebar');
    
    if (!panel) {
        console.warn('Mobile right panel element not found');
        return;
    }
    
    // ============================================
    // FIX: Use a SHARED wrapper that mirrors desktop sidebar
    // Instead of cloning, we point the mobile panel content
    // to use the same interactive elements
    // ============================================
        function openPanel() {
        if (rightSidebar && panelContent) {
            // ============================================
            // FIX: Clone sidebar structure but use event 
            // delegation instead of re-binding handlers
            // ============================================
            panelContent.innerHTML = rightSidebar.innerHTML;
            
            // Remove duplicate IDs to avoid conflicts
            var allElements = panelContent.querySelectorAll('[id]');
            for (var i = 0; i < allElements.length; i++) {
                allElements[i].removeAttribute('id');
            }

			var watchlistContent = panelContent.querySelector('.watchlist-container, #watchlist');
      if (watchlistContent && rightSidebar) {
        var desktopWatchlist = rightSidebar.querySelector('.watchlist-container, #watchlist');
        if (desktopWatchlist) {
          watchlistContent.innerHTML = desktopWatchlist.innerHTML;
        }
      }
            // ============================================
            // USE EVENT DELEGATION ON THE PANEL CONTENT
            // This handles ALL clicks without re-binding
            // ============================================
            panelContent.onclick = function(e) {
				// P0 FIX: Guard against non-DOM targets
    if (!e || !e.target || typeof e.target.closest !== 'function') {
        return;
    }
                var target = e.target;

				if (!target || !target.closest) {
        console.warn('⚠️ Click target is not a DOM element, ignoring');
        return;
    }
                
                // === TRADE TYPE BUTTONS (Buy/Sell) ===
                var tradeTypeBtn = target.closest('.trade-type');
                if (tradeTypeBtn) {
                    e.preventDefault();
                    e.stopPropagation();
                    
                    // Toggle active state in mobile panel
                    panelContent.querySelectorAll('.trade-type').forEach(function(b) {
                        b.classList.remove('active');
                    });
                    tradeTypeBtn.classList.add('active');
                    
                    // Sync with desktop panel
                    var isBuy = tradeTypeBtn.classList.contains('buy') || 
                               (tradeTypeBtn.getAttribute('data-trade-type') === 'buy');
                    
                    var desktopBuyBtn = document.querySelector('#right-sidebar .trade-type.buy');
                    var desktopSellBtn = document.querySelector('#right-sidebar .trade-type.sell');
                    
                    if (isBuy && desktopBuyBtn) {
                        desktopBuyBtn.click();
                    } else if (!isBuy && desktopSellBtn) {
                        desktopSellBtn.click();
                    }
                    
                    // Update the place order button text immediately
                    var orderBtn = panelContent.querySelector('.place-order-btn');
                    if (orderBtn) {
                        orderBtn.textContent = isBuy ? 'Place Buy Order' : 'Place Sell Order';
                        orderBtn.className = 'place-order-btn ' + (isBuy ? 'buy' : 'sell');
                        orderBtn.style.background = isBuy ? 'var(--up-color)' : 'var(--down-color)';
                    }
                    
                    console.log('📱 Mobile trade type switched to:', isBuy ? 'BUY' : 'SELL');
                    return;
                }
                
                // === ORDER TYPE BUTTONS (Limit/Market/Stop) ===
                var orderTypeBtn = target.closest('.order-type-btn');
                if (orderTypeBtn) {
                    e.preventDefault();
                    e.stopPropagation();
                    
                    panelContent.querySelectorAll('.order-type-btn').forEach(function(b) {
                        b.classList.remove('active');
                    });
                    orderTypeBtn.classList.add('active');
                    
                    // Sync with desktop
                    var orderType = orderTypeBtn.getAttribute('data-order');
                    var desktopOrderBtn = document.querySelector('#right-sidebar .order-type-btn[data-order="' + orderType + '"]');
                    if (desktopOrderBtn) {
                        desktopOrderBtn.click();
                    }
                    
                    // Update price input state
                    var priceInput = panelContent.querySelector('#trade-price-input') || 
                                    panelContent.querySelector('input[placeholder="0.00"]');
                    if (priceInput) {
                        if (orderType === 'market') {
                            priceInput.readOnly = true;
                            priceInput.classList.add('readonly');
                            if (STATE.currentPrice) {
                                priceInput.value = U.formatPrice(STATE.currentPrice);
                            }
                        } else {
                            priceInput.readOnly = false;
                            priceInput.classList.remove('readonly');
                        }
                    }
                    
                    console.log('📱 Mobile order type switched to:', orderType);
                    return;
                }
                
                // === QUICK AMOUNT BUTTONS ===
                var quickAmountBtn = target.closest('.quick-amount-btn');
                if (quickAmountBtn) {
                    e.preventDefault();
                    e.stopPropagation();
                    
                    var pct = parseInt(quickAmountBtn.getAttribute('data-pct')) / 100;
                    var priceInput = panelContent.querySelector('input[placeholder="0.00"]') ||
                                    panelContent.querySelector('#trade-price-input');
                    var amountInput = panelContent.querySelector('#trade-amount-input') ||
                                     panelContent.querySelector('input[placeholder="0.00"]');
                    
                    // Sync with desktop by clicking the same button there
                    var desktopQuickBtn = document.querySelector('#right-sidebar .quick-amount-btn[data-pct="' + (pct * 100) + '"]');
                    if (desktopQuickBtn) {
                        desktopQuickBtn.click();
                    }
                    
                    // Copy values from desktop after click
                    setTimeout(function() {
                        var desktopPrice = document.getElementById('trade-price-input');
                        var desktopAmount = document.getElementById('trade-amount-input');
                        var desktopTotal = document.getElementById('trade-total-input');
                        
                        if (priceInput && desktopPrice) priceInput.value = desktopPrice.value;
                        if (amountInput && desktopAmount) amountInput.value = desktopAmount.value;
                        
                        var totalInput = panelContent.querySelector('#trade-total-input');
                        if (totalInput && desktopTotal) totalInput.value = desktopTotal.value;
                    }, 100);
                    
                    console.log('📱 Mobile quick amount:', (pct * 100) + '%');
                    return;
                }
                
                // === PLACE ORDER BUTTON ===
                var placeOrderBtn = target.closest('.place-order-btn');
                if (placeOrderBtn) {
                    e.preventDefault();
                    e.stopPropagation();
                    
                    // Trigger desktop place order button
                    var desktopPlaceBtn = document.getElementById('quick-trade-btn');
                    if (desktopPlaceBtn) {
                        desktopPlaceBtn.click();
                        console.log('📱 Mobile place order triggered');
                    }
                    return;
                }
                
                // === LEVERAGE SLIDER ===
                var leverageSlider = target.closest('#leverage-slider') || 
                                    target.closest('.leverage-slider');
                if (leverageSlider && target.type === 'range') {
                    // Let the slider work naturally but sync with desktop
                    var desktopSlider = document.getElementById('leverage-slider');
                    if (desktopSlider) {
                        desktopSlider.value = target.value;
                        desktopSlider.dispatchEvent(new Event('input'));
                    }
                    
                    var leverageValue = panelContent.querySelector('#leverage-value') ||
                                       panelContent.querySelector('.leverage-value');
                    if (leverageValue) {
                        leverageValue.textContent = target.value + 'x';
                    }
                    return;
                }
                
                // === STOP LOSS / TAKE PROFIT INPUTS ===
                var slInput = target.closest('#trade-sl-input');
                var tpInput = target.closest('#trade-tp-input');
                if (slInput || tpInput) {
                    // Sync values with desktop on blur
                    var fieldType = slInput ? 'sl' : 'tp';
                    target.addEventListener('blur', function() {
                        var desktopInput = document.getElementById('trade-' + fieldType + '-input');
                        if (desktopInput) {
                            desktopInput.value = target.value;
                            desktopInput.dispatchEvent(new Event('input'));
                        }
                    }, { once: true });
                    return;
                }
                
                // === WATCHLIST ITEMS ===
                var wlItem = target.closest('.watchlist-item');
                if (wlItem && !target.closest('.wl-remove')) {
                    e.preventDefault();
                    var symbol = wlItem.getAttribute('data-symbol');
                    if (symbol && window.TV && window.TV.switchSymbol) {
                        window.TV.switchSymbol(symbol);
                        closePanel();
                        if (typeof Toast !== 'undefined') {
                            Toast.success('Loaded: ' + symbol.replace('USDT', '/USDT'));
                        }
                    }
                    return;
                }
                
                // === WATCHLIST REMOVE BUTTONS ===
                var wlRemove = target.closest('.wl-remove');
                if (wlRemove) {
                    e.preventDefault();
                    e.stopPropagation();
                    var sym = wlRemove.getAttribute('data-symbol');
                    if (sym && window.TV && window.TV.removeFromWatchlist) {
                        window.TV.removeFromWatchlist(sym);
                        setTimeout(function() { openPanel(); }, 200);
                    }
                    return;
                }
                
                // === SCREENER ITEMS ===
                var screenerItem = target.closest('.screener-item');
                if (screenerItem) {
                    e.preventDefault();
                    var scrSymbol = screenerItem.getAttribute('data-symbol');
                    if (scrSymbol && window.TV && window.TV.switchSymbol) {
                        window.TV.switchSymbol(scrSymbol);
                        closePanel();
                        if (typeof Toast !== 'undefined') {
                            Toast.success('Loaded: ' + scrSymbol.replace('USDT', '/USDT'));
                        }
                    }
                    return;
                }
                
                // === SCREENER TABS ===
                var screenerTab = target.closest('.screener-tab');
                if (screenerTab) {
                    e.preventDefault();
                    var filter = screenerTab.getAttribute('data-filter');
                    panelContent.querySelectorAll('.screener-tab').forEach(function(t) {
                        t.style.background = 'transparent';
                        t.style.color = 'var(--text-secondary)';
                    });
                    screenerTab.style.background = 'var(--accent-primary)';
                    screenerTab.style.color = 'white';
                    
                    // Trigger desktop tab
                    var desktopTab = document.querySelector('#right-sidebar .screener-tab[data-filter="' + filter + '"]');
                    if (desktopTab) {
                        desktopTab.click();
                        setTimeout(function() {
                            refreshMobileScreener();
                        }, 800);
                    }
                    return;
                }
                
                // === POSITION CLOSE BUTTONS ===
                var closePosBtn = target.closest('.position-close-btn');
                if (closePosBtn) {
                    e.preventDefault();
                    e.stopPropagation();
                    var posId = closePosBtn.getAttribute('data-id');
                    if (posId && confirm('Close this position at market price?')) {
                        if (typeof TradeManager !== 'undefined') {
                            TradeManager.closePosition(posId);
                        }
                    }
                    return;
                }
                
                // === MARKET STAT CLICKS (switch symbol) ===
                var marketItem = target.closest('.market-item');
                if (marketItem) {
                    e.preventDefault();
                    var mktSymbol = marketItem.getAttribute('onclick')?.match(/'([^']+)'/)?.[1];
                    if (mktSymbol && window.TV && window.TV.switchSymbol) {
                        window.TV.switchSymbol(mktSymbol);
                        closePanel();
                    }
                    return;
                }
            };
            
            // ============================================
            // Also handle input events for trade inputs
            // ============================================
            panelContent.oninput = function(e) {
                var target = e.target;
                
                // Price input changes
                if (target.closest('#trade-price-input') || 
                    (target.type === 'text' && target.placeholder === '0.00' && !target.readOnly)) {
                    var desktopPrice = document.getElementById('trade-price-input');
                    if (desktopPrice) {
                        desktopPrice.value = target.value;
                        desktopPrice.dispatchEvent(new Event('input'));
                    }
                }
                
                // Amount input changes
                if (target.closest('#trade-amount-input')) {
                    var desktopAmount = document.getElementById('trade-amount-input');
                    if (desktopAmount) {
                        desktopAmount.value = target.value;
                        desktopAmount.dispatchEvent(new Event('input'));
                    }
                }
            };
        }
        
        panel.classList.add('open');
        if (overlay) overlay.classList.add('visible');
        document.body.style.overflow = 'hidden';
        
        // Sync current trade state from desktop to mobile
        setTimeout(function() {
            syncTradeStateToMobile();
        }, 100);
    }
    
    /**
     * Sync desktop trade panel state to mobile panel
     */
    function syncTradeStateToMobile() {
        // Sync trade type (Buy/Sell)
        var desktopBuyActive = document.querySelector('#right-sidebar .trade-type.buy.active');
        var desktopSellActive = document.querySelector('#right-sidebar .trade-type.sell.active');
        
        if (panelContent) {
            var mobileBuyBtn = panelContent.querySelector('.trade-type.buy');
            var mobileSellBtn = panelContent.querySelector('.trade-type.sell');
            var mobileOrderBtn = panelContent.querySelector('.place-order-btn');
            
            if (mobileBuyBtn && mobileSellBtn) {
                mobileBuyBtn.classList.remove('active');
                mobileSellBtn.classList.remove('active');
                
                if (desktopBuyActive && desktopBuyActive.classList.contains('active')) {
                    mobileBuyBtn.classList.add('active');
                    if (mobileOrderBtn) {
                        mobileOrderBtn.textContent = 'Place Buy Order';
                        mobileOrderBtn.className = 'place-order-btn buy';
                        mobileOrderBtn.style.background = 'var(--up-color)';
                    }
                } else if (desktopSellActive && desktopSellActive.classList.contains('active')) {
                    mobileSellBtn.classList.add('active');
                    if (mobileOrderBtn) {
                        mobileOrderBtn.textContent = 'Place Sell Order';
                        mobileOrderBtn.className = 'place-order-btn sell';
                        mobileOrderBtn.style.background = 'var(--down-color)';
                    }
                }
            }
            
            // Sync order type
            var desktopOrderType = document.querySelector('#right-sidebar .order-type-btn.active');
            if (desktopOrderType) {
                var orderType = desktopOrderType.getAttribute('data-order');
                panelContent.querySelectorAll('.order-type-btn').forEach(function(b) {
                    b.classList.toggle('active', b.getAttribute('data-order') === orderType);
                });
            }
            
            // Sync input values
            var desktopPrice = document.getElementById('trade-price-input');
            var desktopAmount = document.getElementById('trade-amount-input');
            var desktopTotal = document.getElementById('trade-total-input');
            var desktopSL = document.getElementById('trade-sl-input');
            var desktopTP = document.getElementById('trade-tp-input');
            var desktopLeverage = document.getElementById('leverage-slider');
            
            var mobilePrice = panelContent.querySelector('#trade-price-input') || panelContent.querySelector('input[placeholder="0.00"]');
            var mobileAmount = panelContent.querySelector('#trade-amount-input');
            var mobileTotal = panelContent.querySelector('#trade-total-input');
            var mobileLeverage = panelContent.querySelector('#leverage-slider');
            
            if (mobilePrice && desktopPrice) mobilePrice.value = desktopPrice.value;
            if (mobileAmount && desktopAmount) mobileAmount.value = desktopAmount.value;
            if (mobileTotal && desktopTotal) mobileTotal.value = desktopTotal.value;
            if (mobileLeverage && desktopLeverage) mobileLeverage.value = desktopLeverage.value;
            
            // Sync leverage display
            var mobileLevValue = panelContent.querySelector('#leverage-value') || panelContent.querySelector('.leverage-value');
            var desktopLevValue = document.getElementById('leverage-value');
            if (mobileLevValue && desktopLevValue) mobileLevValue.textContent = desktopLevValue.textContent;
        }
    }
    
    /**
     * Refresh screener content in mobile panel
     */
    function refreshMobileScreener() {
        var desktopScreener = document.getElementById('screener-container');
        if (!desktopScreener || !panelContent) return;
        
        var mobileScreenerEl = panelContent.querySelector('#screener-container') ||
                              panelContent.querySelector('[style*="max-height:250px"]');
        if (mobileScreenerEl) {
            mobileScreenerEl.innerHTML = desktopScreener.innerHTML;
        }
    }
    
    function refreshPanelContent() {
        // Refresh screener content only
        var desktopScreener = document.querySelector('#right-sidebar #screener-container');
        var mobileScreener = panelContent.querySelector('#screener-container');
        if (!mobileScreener && desktopScreener) {
            // Find the screener container in mobile panel
            var statsTables = panelContent.querySelectorAll('div[style*="max-height:250px"]');
            for (var i = 0; i < statsTables.length; i++) {
                if (statsTables[i].querySelector('.screener-item')) {
                    mobileScreener = statsTables[i];
                    break;
                }
            }
        }
        if (mobileScreener && desktopScreener) {
            mobileScreener.innerHTML = desktopScreener.innerHTML;
            // Re-attach click handlers to screener items
            mobileScreener.querySelectorAll('.screener-item').forEach(function(item) {
                item.addEventListener('click', function() {
                    var symbol = this.getAttribute('data-symbol');
                    if (symbol && window.TV && window.TV.switchSymbol) {
                        window.TV.switchSymbol(symbol);
                        closePanel();
                    }
                });
            });
        }
    }
    
    function closePanel() {
        panel.classList.remove('open');
        if (overlay) overlay.classList.remove('visible');
        document.body.style.overflow = '';
    }
    
    // Toggle button
    if (toggleBtn) {
        toggleBtn.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            if (panel.classList.contains('open')) {
                closePanel();
            } else {
                openPanel();
            }
        });
    }
    
    // Close button
    if (closeBtn) {
        closeBtn.addEventListener('click', function(e) {
            e.preventDefault();
            closePanel();
        });
    }
    
    // Overlay click
    if (overlay) {
        overlay.addEventListener('click', function() {
            closePanel();
        });
    }
    
    // Swipe to close
    var touchStartX = 0;
    panel.addEventListener('touchstart', function(e) {
        touchStartX = e.touches[0].clientX;
    }, { passive: true });
    
    panel.addEventListener('touchmove', function(e) {
        var diff = e.touches[0].clientX - touchStartX;
        if (diff > 80) closePanel();
    }, { passive: true });
    
    // Escape key
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && panel.classList.contains('open')) {
            closePanel();
        }
    });
    
    console.log('✅ Mobile right panel ready (fixed - event delegation)');
}

