// ============================================
// P0 FIX #1: MOBILE VOLUME CHART AUTO-VISIBILITY
// Ensures volume chart renders automatically on mobile
// without requiring user interaction
// ============================================
function fixMobileVolumeChart() {
  if (window.innerWidth > 768) return;
  
  var volumePane = document.getElementById('volume-chart-pane');
  var volumeChart = document.getElementById('volume-chart');
  var chartContainer = document.getElementById('chart-container');
  
  if (!volumePane || !volumeChart) {
    console.warn('⚠️ Volume chart elements not found');
    return;
  }
  
  // FIXED: Use fixed dimensions, not dynamic
  var fixedHeight = 80;
  
  volumePane.style.cssText = [
    'display: flex !important',
    'flex-direction: column !important',
    'flex: 0 0 ' + fixedHeight + 'px !important',
    'min-height: ' + fixedHeight + 'px !important',
    'height: ' + fixedHeight + 'px !important',
    'max-height: ' + fixedHeight + 'px !important',
    'width: 100% !important',
    'overflow: hidden !important',
    'border-top: 1px solid var(--border-primary) !important',
    'border-bottom: 1px solid var(--border-primary) !important',
    'visibility: visible !important',
    'opacity: 1 !important'
  ].join(';');
  
  volumeChart.style.cssText = [
    'display: block !important',
    'width: 100% !important',
    'height: ' + fixedHeight + 'px !important',
    'min-height: ' + fixedHeight + 'px !important',
    'visibility: visible !important',
    'opacity: 1 !important'
  ].join(';');
  
  // Resize the chart
  if (typeof ChartEngine !== 'undefined' && ChartEngine.charts && ChartEngine.charts.volume) {
    try {
      ChartEngine.charts.volume.resize(volumeChart.clientWidth || window.innerWidth, fixedHeight);
    } catch(e) {}
  }
  
  console.log('✅ Volume chart fixed at ' + fixedHeight + 'px');
}

// In initAllMobileFeatures, add:
function fixMobileScroll() {
  if (window.innerWidth > 768) return;
  
  var chartContainer = document.getElementById('chart-container');
  
  if (chartContainer) {
    // Prevent page scroll when touching chart
    chartContainer.style.overflowY = 'hidden';
    chartContainer.style.overflowX = 'hidden';
    chartContainer.style.touchAction = 'pan-x pinch-zoom';
    chartContainer.style.webkitOverflowScrolling = 'touch';
    chartContainer.style.maxHeight = '100%';
    chartContainer.style.position = 'relative';
    chartContainer.style.userSelect = 'none';
    chartContainer.style.webkitUserSelect = 'none';
  }
  
  // Fix main chart pane touch behavior
  var mainPane = document.getElementById('main-chart-pane');
  if (mainPane) {
    mainPane.style.touchAction = 'pan-x pinch-zoom';
    mainPane.style.userSelect = 'none';
    mainPane.style.webkitUserSelect = 'none';
  }
  
  // Prevent double-tap zoom on chart elements
  var priceChart = document.getElementById('price-chart');
  if (priceChart) {
    priceChart.addEventListener('touchstart', function(e) {
      if (e.touches.length === 2) {
        e.preventDefault(); // Allow pinch zoom
      }
    }, { passive: false });
  }
  
  // Indicator panes scrollable
  var indContainer = document.getElementById('indicator-panes-container');
  if (indContainer) {
    indContainer.style.overflowY = 'auto';
    indContainer.style.webkitOverflowScrolling = 'touch';
    indContainer.style.touchAction = 'pan-y';
  }
}

// ============================================
// 4. MOBILE BOTTOM SHEET
// ============================================
function initMobileSheet() {
    if (window.innerWidth > 768) return;
    
    if (typeof STATE === 'undefined' || typeof DrawingEngine === 'undefined' || typeof ChartEngine === 'undefined') {
        console.warn('⏳ Dependencies not ready, retrying mobile sheet init in 500ms...');
        setTimeout(initMobileSheet, 500);
        return;
    }
    
    var sheet = document.getElementById('mobile-bottom-sheet');
    var overlay = document.getElementById('mobile-overlay');
    var chartContainer = document.querySelector('.chart-container');
    
    if (!sheet) {
        console.warn('Mobile bottom sheet not found');
        return;
    }
    
    var sheetState = 'collapsed';
    var touchStartY = 0;
    var touchCurrentY = 0;
    var isDragging = false;
    
    function setSheetState(state) {
        sheetState = state;
        
        switch(state) {
            case 'collapsed':
                sheet.style.transform = 'translateY(calc(100% - 56px))';
                sheet.style.transition = 'transform 0.35s cubic-bezier(0.4, 0, 0.2, 1)';
                sheet.classList.remove('expanded', 'full');
                if (overlay) {
                    overlay.classList.remove('visible');
                    overlay.style.display = 'none';
                }
                if (chartContainer) chartContainer.classList.remove('sheet-open');
                document.body.style.overflow = '';
                break;
                
            case 'expanded':
                sheet.style.transform = 'translateY(25%)';
                sheet.style.transition = 'transform 0.35s cubic-bezier(0.4, 0, 0.2, 1)';
                sheet.classList.add('expanded');
                sheet.classList.remove('full');
                if (overlay) {
                    overlay.classList.remove('visible');
                    overlay.style.display = 'none';
                }
                if (chartContainer) chartContainer.classList.remove('sheet-open');
                document.body.style.overflow = '';
                break;
                
            case 'full':
                sheet.style.transform = 'translateY(0)';
                sheet.style.transition = 'transform 0.35s cubic-bezier(0.4, 0, 0.2, 1)';
                sheet.classList.add('expanded', 'full');
                if (overlay) {
                    overlay.classList.add('visible');
                    overlay.style.display = 'block';
                }
                if (chartContainer) chartContainer.classList.add('sheet-open');
                document.body.style.overflow = 'hidden';
                break;
        }
    }
    
    // ============================================
    // HANDLE BAR - TOUCH/CLICK TO TOGGLE
    // ============================================
    var sheetHandle = document.getElementById('sheet-handle');
    
    if (sheetHandle) {
        // Touch events for drag
        sheetHandle.addEventListener('touchstart', function(e) {
            touchStartY = e.touches[0].clientY;
            touchCurrentY = touchStartY;
            isDragging = true;
            sheet.style.transition = 'none';
        }, { passive: true });
        
        sheetHandle.addEventListener('touchmove', function(e) {
            if (!isDragging) return;
            touchCurrentY = e.touches[0].clientY;
        }, { passive: true });
        
        sheetHandle.addEventListener('touchend', function(e) {
            if (!isDragging) return;
            isDragging = false;
            
            var diff = touchStartY - touchCurrentY;
            var absDiff = Math.abs(diff);
            
            if (absDiff < 10) {
                // It was a tap, not a drag - cycle states
                if (sheetState === 'collapsed') {
                    setSheetState('expanded');
                } else if (sheetState === 'expanded') {
                    setSheetState('full');
                } else {
                    setSheetState('collapsed');
                }
            } else if (diff > 30) {
                // Dragged UP - expand
                if (sheetState === 'collapsed') setSheetState('expanded');
                else if (sheetState === 'expanded') setSheetState('full');
            } else if (diff < -30) {
                // Dragged DOWN - collapse
                if (sheetState === 'full') setSheetState('expanded');
                else if (sheetState === 'expanded') setSheetState('collapsed');
                else setSheetState('collapsed');
            } else {
                // Snap back
                setSheetState(sheetState);
            }
        });
        
        // Mouse events for desktop testing
        sheetHandle.addEventListener('click', function(e) {
            // Only handle if it's a quick tap (not after a drag)
            if (Math.abs(touchStartY - touchCurrentY) < 10) {
                if (sheetState === 'collapsed') {
                    setSheetState('expanded');
                } else if (sheetState === 'expanded') {
                    setSheetState('full');
                } else {
                    setSheetState('collapsed');
                }
            }
        });
    }
    
    // ============================================
    // OVERLAY CLICK - CLOSE SHEET
    // ============================================
    if (overlay) {
        overlay.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            setSheetState('collapsed');
        });
        
        overlay.addEventListener('touchstart', function(e) {
            e.preventDefault();
            e.stopPropagation();
            setSheetState('collapsed');
        });
    }
    
    // ============================================
    // CLOSE WHEN CLICKING OUTSIDE THE SHEET
    // ============================================
    document.addEventListener('click', function(e) {
        if (sheetState !== 'collapsed') {
            // Check if click is outside the sheet
            if (!sheet.contains(e.target) && e.target !== sheetHandle && !sheetHandle.contains(e.target)) {
                // Don't close if clicking a modal or dropdown
                if (!e.target.closest('.modal-overlay') && !e.target.closest('.ctrl-dropdown-menu')) {
                    setSheetState('collapsed');
                }
            }
        }
    });
    
    document.addEventListener('touchstart', function(e) {
        if (sheetState !== 'collapsed') {
            if (!sheet.contains(e.target) && e.target !== sheetHandle && !sheetHandle.contains(e.target)) {
                if (!e.target.closest('.modal-overlay') && !e.target.closest('.ctrl-dropdown-menu')) {
                    setSheetState('collapsed');
                }
            }
        }
    }, { passive: true });
    
    // ============================================
    // CLOSE WITH ESCAPE KEY
    // ============================================
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && sheetState !== 'collapsed') {
            setSheetState('collapsed');
        }
    });
    
    // ============================================
    // TAB SWITCHING
    // ============================================
    document.querySelectorAll('.sheet-tab').forEach(function(tab) {
        tab.addEventListener('click', function(e) {
            e.stopPropagation();
            
            document.querySelectorAll('.sheet-tab').forEach(function(t) {
                t.classList.remove('active');
            });
            this.classList.add('active');
            
            var tabName = this.getAttribute('data-tab');
            document.querySelectorAll('.sheet-panel').forEach(function(p) {
                p.classList.remove('active');
            });
            
            var targetPanel = document.getElementById('sheet-' + tabName);
            if (targetPanel) {
                targetPanel.classList.add('active');
            }
            
            if (tabName === 'watchlist' && typeof buildMobileWatchlist === 'function') {
                buildMobileWatchlist();
            }
            if (tabName === 'indicators' && typeof buildMobileIndicators === 'function') {
                buildMobileIndicators();
            }
            if (tabName === 'stats' && typeof updateMobileStats === 'function') {
                updateMobileStats();
            }
            
            // Auto-expand if collapsed
            if (sheetState === 'collapsed') {
                setSheetState('expanded');
            }
        });
    });
    
    // ============================================
    // DRAWING TOOLS IN SHEET
    // ============================================
    document.querySelectorAll('.sheet-tool-btn[data-tool]').forEach(function(btn) {
        var newBtn = btn.cloneNode(true);
        btn.parentNode.replaceChild(newBtn, btn);
        
        newBtn.addEventListener('click', function(e) {
            e.stopPropagation();
            e.preventDefault();
            
            var tool = this.getAttribute('data-tool');
            
            if (tool === 'clear' && typeof DrawingEngine !== 'undefined') {
                DrawingEngine.clearAll();
                DrawingEngine.setTool('cursor');
                if (typeof Toast !== 'undefined') Toast.info('All drawings cleared');
            } else if (tool === 'undo' && typeof DrawingEngine !== 'undefined') {
                DrawingEngine.undo();
                DrawingEngine.setTool('cursor');
            } else if (tool === 'eraser' && typeof DrawingEngine !== 'undefined') {
                DrawingEngine.setTool('eraser');
                if (typeof Toast !== 'undefined') Toast.info('Eraser mode - tap a drawing to delete');
            } else if (tool && typeof DrawingEngine !== 'undefined') {
                DrawingEngine.setTool(tool);
            }
            
            setSheetState('collapsed');
        });
    });
    
    // ============================================
    // MORE PANEL ACTIONS
    // ============================================
    document.querySelectorAll('.mob-action-btn[data-action]').forEach(function(btn) {
        var newBtn = btn.cloneNode(true);
        btn.parentNode.replaceChild(newBtn, btn);
        
        newBtn.addEventListener('click', function(e) {
            e.stopPropagation();
            
            var action = this.getAttribute('data-action');
            
            switch(action) {
                case 'profile':
                    if (typeof UserSystem !== 'undefined' && UserSystem.currentUser) {
                        var dropdown = document.getElementById('user-profile-dropdown');
                        if (dropdown) {
                            UserSystem.updateDropdownContent();
                            dropdown.style.position = 'fixed';
                            dropdown.style.top = '80px';
                            dropdown.style.right = '10px';
                            dropdown.style.left = '10px';
                            dropdown.style.width = 'auto';
                            dropdown.style.display = 'block';
                            dropdown.style.zIndex = '99999';
                        }
                    } else {
                        var authModal = document.getElementById('auth-modal');
                        if (authModal) authModal.classList.add('visible');
                    }
                    break;
                case 'search':
                    var searchDropdown = document.getElementById('mobile-search-overlay');
                    if (searchDropdown) {
                        searchDropdown.classList.add('visible');
                        var searchInput = document.getElementById('mobile-search-input');
                        if (searchInput) {
                            searchInput.value = '';
                            setTimeout(function() { searchInput.focus(); }, 100);
                        }
                    }
                    break;
                case 'depth':
                case 'orderbook':
                    document.getElementById('market-depth-modal')?.classList.add('visible');
                    break;
                case 'trades':
                    document.getElementById('market-depth-modal')?.classList.add('visible');
                    setTimeout(function() {
                        var tradeTab = document.querySelector('.depth-tab[data-tab="trades"]');
                        if (tradeTab) tradeTab.click();
                    }, 300);
                    break;
                case 'news':
                    document.getElementById('news-modal')?.classList.add('visible');
                    break;
                case 'screener':
                    var panel = document.getElementById('mobile-right-panel');
                    var mOverlay = document.getElementById('mobile-panel-overlay');
                    if (panel) panel.classList.add('open');
                    if (mOverlay) {
                        mOverlay.classList.add('visible');
                        mOverlay.style.display = 'block';
                    }
                    break;
                case 'alerts':
                    document.getElementById('alerts-modal')?.classList.add('visible');
                    break;
                case 'indicators':
                    document.getElementById('indicators-modal')?.classList.add('visible');
                    break;
                case 'drawings':
                    document.getElementById('drawing-tools-modal')?.classList.add('visible');
                    break;
                case 'journal':
                    document.getElementById('trade-journal-modal')?.classList.add('visible');
                    break;
                case 'backtest':
                    document.getElementById('backtest-modal')?.classList.add('visible');
                    break;
                case 'pine':
                    document.getElementById('indicators-modal')?.classList.add('visible');
                    setTimeout(function() {
                        var customTab = document.querySelector('.cat-tab[data-category="custom"]');
                        if (customTab) customTab.click();
                    }, 300);
                    break;
                case 'testnet':
                    if (typeof TradeManager !== 'undefined') {
                        TradeManager.toggleTestnet();
                    }
                    break;
                case 'settings':
                    document.getElementById('settings-modal')?.classList.add('visible');
                    break;
                case 'theme':
                    var current = document.body.getAttribute('data-theme') || 'dark';
                    var next = current === 'dark' ? 'light' : 'dark';
                    document.body.setAttribute('data-theme', next);
                    if (typeof U !== 'undefined') U.storage.set('tvp_theme', next);
                    if (typeof Toast !== 'undefined') Toast.info('Theme: ' + next);
                    break;
                case 'screenshot':
                    if (ChartEngine && typeof ChartEngine.captureScreenshot === 'function') {
                        ChartEngine.captureScreenshot();
                    }
                    break;
				case 'education':
				document.getElementById('education-modal')?.classList.add('visible');
				TradingEducation.loadChapter(0);
				break;
                case 'fullscreen':
                    if (!document.fullscreenElement) {
                        document.documentElement.requestFullscreen().catch(function(){});
                    } else {
                        document.exitFullscreen();
                    }
                    break;
            }
            
            setSheetState('collapsed');
        });
    });
    
    // ============================================
    // INITIAL STATE
    // ============================================
    setSheetState('collapsed');
    
    console.log('✅ Mobile bottom sheet ready - all close methods active');
}

// ============================================
// BUILD MOBILE WATCHLIST IN SHEET
// ============================================
function buildMobileWatchlist() {
    var container = document.getElementById('mobile-watchlist-list');
    if (!container) return;
    
    var watchlist = (typeof STATE !== 'undefined' && STATE.watchlist) 
        ? STATE.watchlist 
        : [{ symbol: 'BTCUSDT' }, { symbol: 'ETHUSDT' }, { symbol: 'BNBUSDT' }, { symbol: 'SOLUSDT' }];
    
       var html = '';
    for (var i = 0; i < watchlist.length; i++) {
        var item = watchlist[i];
        var sym = U.sanitizeAttr(item.symbol);
        var display = U.sanitize(item.symbol.replace('USDT', '/USDT'));
        
        html += '<div class="mobile-wl-item" data-symbol="' + sym + '">' +
            '<div style="flex:1;min-width:0;">' +
                '<div style="font-weight:700;font-size:13px;">' + display + '</div>' +
                '<div style="font-size:9px;color:var(--text-muted);">Binance</div>' +
            '</div>' +
            '<div style="text-align:right;margin-right:4px;">' +
                '<div style="font-weight:600;font-size:13px;" id="mwl-price-' + sym + '">--</div>' +
                '<div style="font-size:10px;padding:2px 6px;border-radius:3px;" id="mwl-change-' + sym + '">--</div>' +
            '</div>' +
            '<button class="mwl-remove-btn" data-symbol="' + sym + '" style="background:none;border:none;color:var(--text-muted);cursor:pointer;padding:4px 6px;font-size:12px;flex-shrink:0;opacity:0.5;" title="Remove from watchlist">✕</button>' +
        '</div>';
    }
    
    container.innerHTML = html;
    
        // Add click handlers to switch symbol
    container.querySelectorAll('.mobile-wl-item').forEach(function(item) {
        item.addEventListener('click', function(e) {
            // Ignore clicks on the remove button
            if (e.target.closest('.mwl-remove-btn')) return;
            
            var sym = this.getAttribute('data-symbol');
            if (sym && typeof window.TV !== 'undefined' && window.TV.switchSymbol) {
                window.TV.switchSymbol(sym);
                if (typeof Toast !== 'undefined') {
                    Toast.info('Switched to ' + sym.replace('USDT', '/USDT'));
                }
            }
        });
    });
    
    // Add click handlers for remove buttons
    container.querySelectorAll('.mwl-remove-btn').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.stopPropagation();
            e.preventDefault();
            
            var sym = this.getAttribute('data-symbol');
            if (sym) {
                if (typeof window.TV !== 'undefined' && window.TV.removeFromWatchlist) {
                    window.TV.removeFromWatchlist(sym);
                } else if (typeof STATE !== 'undefined' && STATE.watchlist) {
                    STATE.watchlist = STATE.watchlist.filter(function(item) {
                        return item.symbol !== sym;
                    });
                    localStorage.setItem('tvp_watchlist', JSON.stringify(STATE.watchlist));
                    if (typeof WatchlistManager !== 'undefined' && WatchlistManager.render) {
                        WatchlistManager.render();
                    }
                }
                
                // Refresh mobile watchlist
                if (typeof buildMobileWatchlist === 'function') {
                    buildMobileWatchlist();
                }
                
                if (typeof Toast !== 'undefined') {
                    Toast.info(sym.replace('USDT', '/USDT') + ' removed from watchlist');
                }
            }
        });
    });
}

// ============================================
// MOBILE WATCHLIST ADD BUTTON HANDLER
// ============================================
// ============================================
// MOBILE WATCHLIST SEARCH & ADD SYSTEM
// ============================================
(function setupMobileWatchlistSearch() {
    setTimeout(function() {
        var searchInput = document.getElementById('mobile-watchlist-search');
        var addBtn = document.getElementById('mobile-watchlist-add-btn');
        var suggestionsDiv = document.getElementById('mobile-watchlist-suggestions');
        
        if (!searchInput || !suggestionsDiv) {
            console.warn('Mobile watchlist search elements not found');
            return;
        }
        
        var selectedSymbol = null;
        var selectedType = 'crypto';
        var allSuggestions = [];
        
        // ============================================
        // BUILD SUGGESTIONS LIST
        // ============================================
        function getDefaultSuggestions() {
            var suggestions = [];
            
            // Add crypto symbols from available symbols
            if (typeof STATE !== 'undefined' && STATE.availableSymbols && STATE.availableSymbols.length) {
                var cryptos = STATE.availableSymbols.slice(0, 10).map(function(s) {
                    return { symbol: s.symbol, name: s.baseAsset || s.symbol.replace('USDT', ''), type: 'crypto', exchange: 'Binance' };
                });
                suggestions = suggestions.concat(cryptos);
            } else {
                // Fallback cryptos
                suggestions.push(
                    { symbol: 'BTCUSDT', name: 'Bitcoin', type: 'crypto', exchange: 'Binance' },
                    { symbol: 'ETHUSDT', name: 'Ethereum', type: 'crypto', exchange: 'Binance' },
                    { symbol: 'BNBUSDT', name: 'BNB', type: 'crypto', exchange: 'Binance' },
                    { symbol: 'SOLUSDT', name: 'Solana', type: 'crypto', exchange: 'Binance' },
                    { symbol: 'XRPUSDT', name: 'Ripple', type: 'crypto', exchange: 'Binance' },
                    { symbol: 'ADAUSDT', name: 'Cardano', type: 'crypto', exchange: 'Binance' }
                );
            }
            
            // Add stock symbols
            if (typeof STATE !== 'undefined' && STATE.stockSymbols && STATE.stockSymbols.length) {
                var stocks = STATE.stockSymbols.slice(0, 6).map(function(s) {
                    return { symbol: s.symbol, name: s.description || s.symbol, type: 'stocks', exchange: 'NASDAQ/NYSE' };
                });
                suggestions = suggestions.concat(stocks);
            } else {
                suggestions.push(
                    { symbol: 'AAPL', name: 'Apple Inc.', type: 'stocks', exchange: 'NASDAQ' },
                    { symbol: 'TSLA', name: 'Tesla Inc.', type: 'stocks', exchange: 'NASDAQ' },
                    { symbol: 'MSFT', name: 'Microsoft', type: 'stocks', exchange: 'NASDAQ' }
                );
            }
            
            // Add forex symbols
            suggestions.push(
                { symbol: 'EURUSD', name: 'Euro / USD', type: 'forex', exchange: 'FX' },
                { symbol: 'GBPUSD', name: 'Pound / USD', type: 'forex', exchange: 'FX' },
                { symbol: 'USDJPY', name: 'Dollar / Yen', type: 'forex', exchange: 'FX' }
            );
            
            return suggestions;
        }
        
        // ============================================
        // RENDER SUGGESTIONS
        // ============================================
        function renderSuggestions(suggestions) {
            if (!suggestions || suggestions.length === 0) {
                suggestionsDiv.innerHTML = '<div style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">No results found</div>';
                suggestionsDiv.style.display = 'block';
                return;
            }
            
            var html = '';
            for (var i = 0; i < suggestions.length; i++) {
                var s = suggestions[i];
                var displaySymbol = s.symbol.includes('USDT') ? s.symbol.replace('USDT', '/USDT') : s.symbol;
                var typeIcon = s.type === 'crypto' ? '₿' : s.type === 'stocks' ? '📈' : '💱';
                var typeColor = s.type === 'crypto' ? '#58a6ff' : s.type === 'stocks' ? '#26a69a' : '#ff9800';
                var typeBg = s.type === 'crypto' ? 'rgba(88,166,255,0.1)' : s.type === 'stocks' ? 'rgba(38,166,154,0.1)' : 'rgba(255,152,0,0.1)';
                
                html += '<div class="mwl-suggestion-item" data-symbol="' + s.symbol + '" data-type="' + s.type + '" data-name="' + (s.name || '') + '" style="' +
                    'display: flex; justify-content: space-between; align-items: center; ' +
                    'padding: 10px 12px; cursor: pointer; border-bottom: 1px solid rgba(48,54,61,0.2); ' +
                    'transition: background 0.15s;' +
                    '" onmouseenter="this.style.background=\'var(--bg-hover)\'" onmouseleave="this.style.background=\'transparent\'">' +
                    '<div style="display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0;">' +
                        '<span style="font-size: 16px; flex-shrink: 0;">' + typeIcon + '</span>' +
                        '<div style="min-width: 0;">' +
                            '<div style="font-weight: 600; font-size: 12px; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">' + displaySymbol + '</div>' +
                            '<div style="font-size: 10px; color: var(--text-muted);">' + (s.name || s.symbol) + ' · ' + (s.exchange || '') + '</div>' +
                        '</div>' +
                    '</div>' +
                    '<span style="font-size: 9px; padding: 2px 8px; border-radius: 10px; font-weight: 600; background: ' + typeBg + '; color: ' + typeColor + '; flex-shrink: 0; margin-left: 8px;">' + s.type.toUpperCase() + '</span>' +
                '</div>';
            }
            
            suggestionsDiv.innerHTML = html;
            suggestionsDiv.style.display = 'block';
            
            // Add click handlers
            var items = suggestionsDiv.querySelectorAll('.mwl-suggestion-item');
            for (var j = 0; j < items.length; j++) {
                (function(item) {
                    item.addEventListener('click', function() {
                        selectedSymbol = this.getAttribute('data-symbol');
                        selectedType = this.getAttribute('data-type');
                        searchInput.value = this.getAttribute('data-symbol').replace('USDT', '/USDT');
                        suggestionsDiv.style.display = 'none';
                        console.log('Selected:', selectedSymbol, selectedType);
                    });
                })(items[j]);
            }
        }
        
        // ============================================
        // SEARCH INPUT HANDLER
        // ============================================
        searchInput.addEventListener('input', function() {
            var query = this.value.trim().toUpperCase();
            
            if (query.length === 0) {
                allSuggestions = getDefaultSuggestions();
                renderSuggestions(allSuggestions.slice(0, 12));
                return;
            }
            
            // Filter suggestions
            var filtered = allSuggestions.filter(function(s) {
                return s.symbol.toUpperCase().includes(query) || 
                       (s.name && s.name.toUpperCase().includes(query));
            });
            
            if (filtered.length === 0 && query.length >= 2) {
                // Try searching available symbols
                if (typeof STATE !== 'undefined' && STATE.availableSymbols) {
                    var cryptoMatches = STATE.availableSymbols.filter(function(s) {
                        return s.symbol.includes(query) || (s.baseAsset && s.baseAsset.includes(query));
                    }).slice(0, 8).map(function(s) {
                        return { symbol: s.symbol, name: s.baseAsset, type: 'crypto', exchange: 'Binance' };
                    });
                    filtered = filtered.concat(cryptoMatches);
                }
                
                if (typeof STATE !== 'undefined' && STATE.stockSymbols) {
                    var stockMatches = STATE.stockSymbols.filter(function(s) {
                        return s.symbol.toUpperCase().includes(query) || 
                               (s.description && s.description.toUpperCase().includes(query));
                    }).slice(0, 5).map(function(s) {
                        return { symbol: s.symbol, name: s.description || s.symbol, type: 'stocks', exchange: 'NASDAQ' };
                    });
                    filtered = filtered.concat(stockMatches);
                }
            }
            
            renderSuggestions(filtered.slice(0, 12));
        });
        
        // Show suggestions on focus
        searchInput.addEventListener('focus', function() {
            if (allSuggestions.length === 0) {
                allSuggestions = getDefaultSuggestions();
            }
            if (suggestionsDiv.innerHTML === '') {
                renderSuggestions(allSuggestions.slice(0, 12));
            } else {
                suggestionsDiv.style.display = 'block';
            }
        });
        
        // Hide suggestions when clicking outside
        document.addEventListener('click', function(e) {
            if (!searchInput.contains(e.target) && !suggestionsDiv.contains(e.target) && !addBtn.contains(e.target)) {
                suggestionsDiv.style.display = 'none';
            }
        });
        
        // Keyboard navigation
        searchInput.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') {
                suggestionsDiv.style.display = 'none';
                this.blur();
            }
            if (e.key === 'Enter') {
                e.preventDefault();
                addBtn.click();
            }
        });
        
        // ============================================
        // ADD BUTTON HANDLER
        // ============================================
        if (addBtn) {
            var newAddBtn = addBtn.cloneNode(true);
            addBtn.parentNode.replaceChild(newAddBtn, addBtn);
            
            newAddBtn.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                
                var symbol = selectedSymbol;
                
                // If no suggestion selected, try the input text
                if (!symbol) {
                    var inputVal = searchInput.value.trim().toUpperCase();
                    if (!inputVal) {
                        if (typeof Toast !== 'undefined') {
                            Toast.warning('Please search and select a symbol');
                        }
                        return;
                    }
                    symbol = inputVal.replace('/', '');
                    
                    // Auto-add USDT suffix for crypto
                    if (!symbol.includes('USDT') && symbol.length <= 6 && !symbol.match(/^[A-Z]{6}$/)) {
                        symbol = symbol + 'USDT';
                    }
                }
                
                if (!symbol) return;
                
                // Check if already in watchlist
                if (typeof STATE !== 'undefined' && STATE.watchlist) {
                    var exists = STATE.watchlist.find(function(item) {
                        return item.symbol === symbol;
                    });
                    if (exists) {
                        if (typeof Toast !== 'undefined') {
                            Toast.warning(symbol.replace('USDT', '/USDT') + ' is already in your watchlist');
                        }
                        searchInput.value = '';
                        selectedSymbol = null;
                        suggestionsDiv.style.display = 'none';
                        return;
                    }
                }
                
                // Add to watchlist
                if (typeof window.TV !== 'undefined' && window.TV.addToWatchlist) {
                    window.TV.addToWatchlist(symbol);
                } else if (typeof STATE !== 'undefined' && STATE.watchlist) {
                    STATE.watchlist.push({ symbol: symbol });
                    localStorage.setItem('tvp_watchlist', JSON.stringify(STATE.watchlist));
                    if (typeof WatchlistManager !== 'undefined' && WatchlistManager.render) {
                        WatchlistManager.render();
                    }
                }
                
                // Switch to the new symbol
                if (typeof window.TV !== 'undefined' && window.TV.switchSymbol) {
                    window.TV.switchSymbol(symbol);
                }
                
                // Refresh mobile watchlist
                if (typeof buildMobileWatchlist === 'function') {
                    buildMobileWatchlist();
                }
                
                // Clear input
                searchInput.value = '';
                selectedSymbol = null;
                suggestionsDiv.style.display = 'none';
                
                if (typeof Toast !== 'undefined') {
                    Toast.success(symbol.replace('USDT', '/USDT') + ' added to watchlist');
                }
            });
        }
        
        // Initialize suggestions
        allSuggestions = getDefaultSuggestions();
        
        console.log('✅ Mobile watchlist search & add system ready');
    }, 600);
})();

// ============================================
// BUILD MOBILE INDICATORS GRID IN SHEET
// ============================================
// REPLACE the existing buildMobileIndicators function with this:
function buildMobileIndicators() {
    var container = document.getElementById('mobile-indicators-grid');
    if (!container) return;
    
    
    var indicators = [
  'RSI', 'MACD', 'SMA', 'EMA', 'Bollinger', 'VWAP',
  'Stochastic', 'ATR', 'Ichimoku', 'SuperTrend', 'PSAR',
  'CCI', 'CLV', 'WilliamsR', 'Keltner', 'OBV', 'MFI',
  'HullMA', 'Donchian', 'Envelope', 'StochasticRSI',
  'Momentum', 'ROC', 'AD', 'CMF', 'VolumeProfile', 'ZigZag'
];
    
    var html = '';
    for (var i = 0; i < indicators.length; i++) {
        var ind = indicators[i];
        var isActive = (typeof STATE !== 'undefined' && STATE.activeIndicators && STATE.activeIndicators.has(ind));
        
        html += '<button class="sheet-indicator-btn' + (isActive ? ' active' : '') + '" ' +
            'data-indicator="' + ind + '" ' +
            'style="background:' + (isActive ? 'var(--accent-muted)' : 'var(--bg-tertiary)') + ';' +
            'border-color:' + (isActive ? 'var(--accent-primary)' : 'var(--border-primary)') + ';' +
            'color:' + (isActive ? 'var(--accent-primary)' : 'var(--text-secondary)') + ';">' +
            ind +
        '</button>';
    }
    
    container.innerHTML = html;
    
    // Add click handlers
    container.querySelectorAll('.sheet-indicator-btn').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
  e.stopPropagation();
  
  var ind = this.getAttribute('data-indicator');
  if (ind && typeof IndicatorEngine !== 'undefined') {
    // Immediately update button visual (optimistic)
    var wasActive = STATE.activeIndicators.has(ind);
    this.style.background = wasActive ? 'var(--bg-tertiary)' : 'var(--accent-muted)';
    this.style.borderColor = wasActive ? 'var(--border-primary)' : 'var(--accent-primary)';
    this.style.color = wasActive ? 'var(--text-secondary)' : 'var(--accent-primary)';
    
    // Toggle the indicator
    IndicatorEngine.toggleIndicator(ind);
    
    // Recalculate (this triggers pane creation/removal)
    if (typeof IndicatorEngine.calculateAll === 'function') {
      IndicatorEngine.calculateAll();
    }
    
    // Refresh grid after calculation completes
    // Use requestAnimationFrame for smoother timing
    var refreshAttempts = 0;
    var maxAttempts = 10;
    
    function tryRefresh() {
      refreshAttempts++;
      
      // Check if indicator state matches what we expect
      var currentState = STATE.activeIndicators.has(ind);
      var expectedState = !wasActive;
      
      if (currentState === expectedState || refreshAttempts >= maxAttempts) {
        buildMobileIndicators();
      } else {
        // Wait and retry
        setTimeout(tryRefresh, 50);
      }
    }
    
    setTimeout(tryRefresh, 150);
  }
});
    });
}

// ============================================
// UPDATE MOBILE STATS PANEL
// ============================================
function updateMobileStats() {
    var lastCandle = (typeof STATE !== 'undefined' && STATE.candles && STATE.candles.length > 0)
        ? STATE.candles[STATE.candles.length - 1]
        : null;
    
    function setIfExists(id, value) {
        var el = document.getElementById(id);
        if (el) el.textContent = value;
    }
    
    if (lastCandle) {
        setIfExists('ms-open', typeof U !== 'undefined' ? U.formatPrice(lastCandle.open) : lastCandle.open.toFixed(2));
        setIfExists('ms-high', typeof U !== 'undefined' ? U.formatPrice(lastCandle.high) : lastCandle.high.toFixed(2));
        setIfExists('ms-low', typeof U !== 'undefined' ? U.formatPrice(lastCandle.low) : lastCandle.low.toFixed(2));
        setIfExists('ms-volume', typeof U !== 'undefined' ? U.formatVolume(lastCandle.volume) : lastCandle.volume.toFixed(2));
        
        var changeEl = document.getElementById('ms-change');
        if (changeEl && typeof STATE !== 'undefined' && STATE.change24h !== null) {
            var change = STATE.change24h;
            changeEl.textContent = (change >= 0 ? '+' : '') + change.toFixed(2) + '%';
            changeEl.style.color = change >= 0 ? 'var(--up-color)' : 'var(--down-color)';
        }
    } else {
        ['ms-open', 'ms-high', 'ms-low', 'ms-volume'].forEach(function(id) {
            setIfExists(id, '--');
        });
    }
}

// ============================================
// LIVE MOBILE PRICE UPDATES
// ============================================
function updateMobilePrices() {
    IntervalManager.register(function() {
        if (typeof STATE === 'undefined' || !STATE.currentPrice) return;
		
		 var mobileProfileText = document.getElementById('mobile-profile-text');
        if (mobileProfileText) {
            if (typeof UserSystem !== 'undefined' && UserSystem.currentUser) {
                mobileProfileText.textContent = UserSystem.currentUser.displayName || 'My Profile';
            } else {
                mobileProfileText.textContent = 'Sign In / Register';
            }
        }
        
        // Update header price display
        var priceEl = document.getElementById('mobile-price');
        var symbolEl = document.getElementById('mobile-symbol-name');
        var changeBadge = document.getElementById('mobile-change-badge');
        
        if (priceEl) {
            priceEl.textContent = typeof U !== 'undefined'
                ? U.formatPrice(STATE.currentPrice)
                : STATE.currentPrice.toFixed(2);
            priceEl.style.color = (STATE.change24h || 0) >= 0 ? 'var(--up-color)' : 'var(--down-color)';
        }
        
        if (symbolEl) {
            symbolEl.textContent = STATE.symbol.replace('USDT', '/USDT');
        }
        
        if (changeBadge && STATE.change24h !== null) {
            var change = STATE.change24h;
            changeBadge.textContent = (change >= 0 ? '+' : '') + change.toFixed(2) + '%';
            changeBadge.className = 'mobile-change-badge ' + (change >= 0 ? 'up' : 'down');
        }
        
        // Update watchlist prices in sheet
        document.querySelectorAll('#mobile-watchlist-list .mobile-wl-item').forEach(function(item) {
            var sym = item.getAttribute('data-symbol');
            var data = STATE.marketData && STATE.marketData.get ? STATE.marketData.get(sym) : null;
            
            var priceDisplay = document.getElementById('mwl-price-' + sym);
            var changeDisplay = document.getElementById('mwl-change-' + sym);
            
            if (priceDisplay && data && data.price) {
                priceDisplay.textContent = '$' + (typeof U !== 'undefined'
                    ? U.formatPrice(data.price)
                    : data.price.toFixed(2));
            }
            
            if (changeDisplay && data && data.change !== undefined) {
                var itemChange = data.change;
                changeDisplay.textContent = (itemChange >= 0 ? '+' : '') + itemChange.toFixed(2) + '%';
                changeDisplay.style.color = itemChange >= 0 ? 'var(--up-color)' : 'var(--down-color)';
                changeDisplay.style.background = itemChange >= 0 ? 'var(--up-muted)' : 'var(--down-muted)';
            }
        });
      }, 2000, 'Mobile-priceUpdates');
}


