function showTrialUpgradeModal(featureName) {
    var modal = document.getElementById('trial-upgrade-modal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'trial-upgrade-modal';
        modal.className = 'modal-overlay';
        modal.innerHTML = '<div class="modal-container modal-md" style="max-width:450px; text-align:center;">' +
            '<div class="modal-header" style="border-bottom:none;">' +
                '<div class="modal-title">' +
                    '<i class="fas fa-gift" style="color:#ff9800; font-size:24px;"></i>' +
                    '<div>' +
                        '<h3>Start Your 14-Day Free Trial</h3>' +
                        '<p class="modal-subtitle">Unlock ' + (featureName || 'PRO features') + '</p>' +
                    '</div>' +
                '</div>' +
                '<button class="modal-close" onclick="this.closest(\'.modal-overlay\').classList.remove(\'visible\')">✕</button>' +
            '</div>' +
            '<div class="modal-body" style="padding:20px;">' +
                '<div style="background:linear-gradient(135deg,rgba(255,152,0,0.1),rgba(255,152,0,0.05)); border-radius:12px; padding:16px; margin-bottom:16px;">' +
                    '<div style="font-size:28px; font-weight:800; color:#ff9800;">14 DAYS FREE</div>' +
                    '<div style="font-size:12px; color:var(--text-muted); margin-top:4px;">Then auto-renews at $5/month (PRO) or $10/month (ULTIMATE)</div>' +
                '</div>' +
                '<div style="display:flex; gap:12px; margin-bottom:20px;">' +
                    '<div id="trial-pro-option" data-tier="pro" style="flex:1; padding:14px; border:2px solid var(--border-primary); border-radius:12px; cursor:pointer;">' +
                        '<div style="font-size:20px;">⭐</div>' +
                        '<div style="font-weight:700;">PRO</div>' +
                        '<div style="font-size:10px; color:var(--text-muted);">$5/month after trial</div>' +
                        '<div style="font-size:9px; margin-top:6px; color:#ffd700;">30 indicators · 20 alerts · 2 charts</div>' +
                    '</div>' +
                    '<div id="trial-ultimate-option" data-tier="ultimate" style="flex:1; padding:14px; border:2px solid var(--border-primary); border-radius:12px; cursor:pointer;">' +
                        '<div style="font-size:20px;">👑</div>' +
                        '<div style="font-weight:700;">ULTIMATE</div>' +
                        '<div style="font-size:10px; color:var(--text-muted);">$10/month after trial</div>' +
                        '<div style="font-size:9px; margin-top:6px; color:#9b6cff;">Unlimited · API · Premium indicators</div>' +
                    '</div>' +
                '</div>' +
                '<button id="start-trial-modal-btn" class="btn btn-primary btn-full" style="background:linear-gradient(135deg,#ff9800,#f57c00); padding:12px;">' +
                    '<i class="fas fa-gift"></i> Start 14-Day Free Trial' +
                '</button>' +
                '<button id="cancel-trial-modal" style="width:100%; padding:8px; background:transparent; border:none; color:var(--text-muted); cursor:pointer; font-size:11px; margin-top:8px;">' +
                    'No thanks, continue with FREE' +
                '</button>' +
            '</div>' +
        '</div>';
        document.body.appendChild(modal);
    }
    
    var selectedTier = 'pro';
    var proOption = document.getElementById('trial-pro-option');
    var ultimateOption = document.getElementById('trial-ultimate-option');
    
    function updateSelection(tier) {
        selectedTier = tier;
        if (proOption) {
            proOption.style.borderColor = tier === 'pro' ? '#ffd700' : 'var(--border-primary)';
            proOption.style.background = tier === 'pro' ? 'rgba(255,215,0,0.1)' : 'transparent';
        }
        if (ultimateOption) {
            ultimateOption.style.borderColor = tier === 'ultimate' ? '#9b6cff' : 'var(--border-primary)';
            ultimateOption.style.background = tier === 'ultimate' ? 'rgba(155,108,255,0.1)' : 'transparent';
        }
    }
    
    if (proOption) proOption.onclick = function() { updateSelection('pro'); };
    if (ultimateOption) ultimateOption.onclick = function() { updateSelection('ultimate'); };
    updateSelection('pro');
    
    var startBtn = document.getElementById('start-trial-modal-btn');
    if (startBtn) {
        var newBtn = startBtn.cloneNode(true);
        startBtn.parentNode.replaceChild(newBtn, startBtn);
        newBtn.onclick = async function() {
            newBtn.disabled = true;
            newBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Starting trial...';
            var result = await UserSystem.startTrial(selectedTier);
            if (result.success) {
                modal.classList.remove('visible');
                setTimeout(function() { location.reload(); }, 1000);
            } else {
                newBtn.disabled = false;
                newBtn.innerHTML = '<i class="fas fa-gift"></i> Start 14-Day Free Trial';
                if (typeof Toast !== 'undefined') Toast.error(result.error);
            }
        };
    }
    
    document.getElementById('cancel-trial-modal')?.addEventListener('click', function() {
        modal.classList.remove('visible');
    });
    
    modal.classList.add('visible');
}
// ============================================
// API KEY MANAGER (RTDB VERSION - NO FIRESTORE)
// Uses Realtime Database exclusively
// ============================================
const ApiKeyManager = {
  currentKey: null,
  dailyCount: 0,
  resetDate: '',

  async init() {
    if (!UserSystem.currentUser) {
      console.log('🔑 ApiKeyManager: No user logged in, skipping');
      return;
    }
    await this.loadKey();
    this.updateUI();
  },

  async loadKey() {
    try {
      if (!window.FB || !window.FB.rtdb) {
        console.log('🔑 Firebase RTDB not available for API key loading');
        return;
      }
      
      const { ref, get } = await import("https://www.gstatic.com/firebasejs/10.12.0/firebase-database.js");
      const userRef = ref(window.FB.rtdb, 'users/' + UserSystem.currentUser.uid);
      const snap = await get(userRef);
      
      if (!snap.exists()) {
        console.log('🔑 No user data in RTDB yet - will be created on first save');
        return;
      }
      
      const data = snap.val();
      this.currentKey = data.apiKey || null;
      this.dailyCount = data.apiDailyCount || 0;
      this.resetDate = data.apiResetDate || '';
      
      // Reset daily count if it's a new day
      const today = new Date().toISOString().slice(0, 10);
      if (this.resetDate !== today) {
        console.log('🔄 New day - resetting API count from', this.dailyCount, 'to 0');
        this.dailyCount = 0;
        this.resetDate = today;
        await this.save();
      }
      
      console.log('🔑 API key loaded from RTDB:', this.currentKey ? 'Key exists' : 'No key');
    } catch(e) { 
      console.warn('API key load error (non-critical):', e.message); 
    }
  },

  async save() {
    if (!UserSystem.currentUser) {
      console.warn('Cannot save API key - no user logged in');
      return;
    }
    
    try {
      const { ref, update } = await import("https://www.gstatic.com/firebasejs/10.12.0/firebase-database.js");
      const updates = {};
      
      // Only set fields that are defined
      if (this.currentKey !== undefined) updates['users/' + UserSystem.currentUser.uid + '/apiKey'] = this.currentKey;
      if (this.dailyCount !== undefined) updates['users/' + UserSystem.currentUser.uid + '/apiDailyCount'] = this.dailyCount;
      if (this.resetDate !== undefined) updates['users/' + UserSystem.currentUser.uid + '/apiResetDate'] = this.resetDate;
      updates['users/' + UserSystem.currentUser.uid + '/updatedAt'] = new Date().toISOString();
      
      await update(ref(window.FB.rtdb), updates);
      console.log('🔑 API key saved to RTDB');
    } catch(e) {
      console.error('Failed to save API key to RTDB:', e.message);
      if (typeof Toast !== 'undefined') {
        Toast.error('Failed to save API key. Check connection.');
      }
    }
  },

  async generateKey() {
    // Ultimate tier check
    const tier = UserSystem.subscription || 'free';
    if (tier !== 'ultimate') {
      if (typeof Toast !== 'undefined') {
        Toast.warning('API access requires Ultimate subscription');
      }
      UserSystem.checkPro('API Access');
      return;
    }
    
    // Generate a unique key
    const randomPart = U.genId() + U.genId();
    this.currentKey = 'tvp_' + randomPart.substring(0, 32);
    this.dailyCount = 0;
    this.resetDate = new Date().toISOString().slice(0, 10);
    
    await this.save();
    this.updateUI();
    
    if (typeof Toast !== 'undefined') {
      Toast.success('API key generated! Use it in the x-api-key header.');
    }
    
    console.log('🔑 New API key generated:', this.currentKey.substring(0, 8) + '...');
  },

  async revokeKey() {
    if (!this.currentKey) {
      if (typeof Toast !== 'undefined') {
        Toast.info('No API key to revoke');
      }
      return;
    }
    
    if (confirm('Revoke your API key? It will stop working immediately. Any applications using this key will lose access.')) {
      this.currentKey = null;
      this.dailyCount = 0;
      this.resetDate = '';
      await this.save();
      this.updateUI();
      
      if (typeof Toast !== 'undefined') {
        Toast.info('API key revoked');
      }
      console.log('🔑 API key revoked');
    }
  },

  async copyKey() {
    if (!this.currentKey) return;
    try {
      await navigator.clipboard.writeText(this.currentKey);
      if (typeof Toast !== 'undefined') {
        Toast.success('API key copied to clipboard!');
      }
    } catch(e) {
      // Fallback for older browsers
      const display = document.getElementById('api-key-display');
      if (display) {
        display.select();
        document.execCommand('copy');
        if (typeof Toast !== 'undefined') {
          Toast.success('API key copied!');
        }
      }
    }
  },

  updateUI() {
    const display = document.getElementById('api-key-display');
    const usageEl = document.getElementById('api-usage-display');
    const limitEl = document.getElementById('api-limit-display');
    const generateBtn = document.getElementById('generate-api-key-btn');
    const revokeBtn = document.getElementById('revoke-api-key-btn');
    const copyBtn = document.getElementById('copy-api-key-btn');

    if (display) {
      display.value = this.currentKey || 'No key generated';
    }
    
    if (usageEl) {
      const tier = UserSystem.subscription || 'free';
      const limits = { free: 1000, pro: 10000, ultimate: 100000 };
      const limit = limits[tier] || 1000;
      usageEl.textContent = `${this.dailyCount} / ${limit}`;
      
      // Warn if approaching limit
      if (this.dailyCount > limit * 0.8) {
        usageEl.style.color = 'var(--warning)';
      } else {
        usageEl.style.color = '';
      }
    }
    
    if (limitEl) {
      const tier = UserSystem.subscription || 'free';
      if (tier === 'ultimate') {
        limitEl.textContent = '100,000 req/day';
        limitEl.style.color = 'var(--up-color)';
      } else if (tier === 'pro') {
        limitEl.textContent = '10,000 req/day';
        limitEl.style.color = 'var(--accent-primary)';
      } else {
        limitEl.textContent = '1,000 req/day';
        limitEl.style.color = 'var(--text-muted)';
      }
    }
    
    // Show/hide buttons based on key existence
    if (generateBtn) {
      generateBtn.textContent = this.currentKey ? 'Regenerate Key' : 'Generate Key';
    }
    if (revokeBtn) {
      revokeBtn.style.display = this.currentKey ? 'inline-block' : 'none';
    }
    if (copyBtn) {
      copyBtn.style.display = this.currentKey ? 'inline-block' : 'none';
    }
  }
};
// ============================================
// SUBSCRIPTION TIER LIMITS & ENFORCEMENT
// ============================================
const TierLimits = {
  free: {
    indicators: 5,
    alerts: 3,
    charts: 1,
    chatMessages: 10,
    apiAccess: false,
    premiumIndicators: false,
    dataExport: false,
    showAds: true
  },
  pro: {
    indicators: 30,
    alerts: 20,
    charts: 2,
    chatMessages: Infinity,
    apiAccess: false,
    premiumIndicators: false,
    dataExport: false,
    showAds: false
  },
  ultimate: {
    indicators: Infinity,
    alerts: Infinity,
    charts: 4,
    chatMessages: Infinity,
    apiAccess: true,
    premiumIndicators: true,
    dataExport: true,
    showAds: false
  }
};

function getCurrentTier() {
  return UserSystem.subscription || 'free';
}

function checkTier(feature, fallbackMsg) {
  const current = getCurrentTier();
  const limits = TierLimits[current] || TierLimits.free;
  if (!limits[feature]) {
    Toast.warning(fallbackMsg || `This feature requires a Pro or Ultimate subscription.`);
    UserSystem.checkPro(feature);
    return false;
  }
  return true;
}

function checkTierCount(feature, currentCount, limitFeature) {
  const currentTier = getCurrentTier();
  const limits = TierLimits[currentTier] || TierLimits.free;
  const max = limits[limitFeature || feature];
  if (typeof max === 'number' && currentCount >= max) {
    Toast.warning(`Free tier allows only ${max} ${feature}. Upgrade for more.`);
    UserSystem.checkPro(feature);
    return false;
  }
  return true;
}

  // ============================================
  // CHAT SYSTEM
  // ============================================
    var ChatSystem = {
    currentChannel: 'general',
    msgSub: null,

    subscribe: async function(channel) {
      this.currentChannel = channel;
      if (this.msgSub) {
        try { this.msgSub(); } catch(e) {}
        this.msgSub = null;
      }
      
      if (!window.FB || !window.FB.rtdb) { 
        this.renderLocal(); 
        return; 
      }
      
      try {
        var dbMod = await import("https://www.gstatic.com/firebasejs/10.12.0/firebase-database.js");
        var msgsRef = dbMod.ref(window.FB.rtdb, 'chat/' + channel);
        var self = this;
        
        this.msgSub = dbMod.onValue(msgsRef, function(snap) {
          var msgs = [];
          snap.forEach(function(c) { 
            var val = c.val();
            if (val) msgs.push(val);
          });
          msgs.sort(function(a, b) { return (a.timestamp || 0) - (b.timestamp || 0); });
          self.renderMessages(msgs.slice(-100));
          self.updatePresence();
        });
      } catch(e) {
        console.warn('Chat subscription failed, using local:', e.message);
        this.renderLocal();
      }
    },

    renderLocal: function() {
      var key = 'tvp_chat_' + this.currentChannel;
      var msgs = [];
      try { msgs = JSON.parse(localStorage.getItem(key)) || []; } catch(e) {}
      this.renderMessages(msgs);
    },

    renderMessages: function(msgs) {
      var container = document.getElementById('chat-messages');
      if (!container) return;
      var uid = UserSystem.currentUser ? UserSystem.currentUser.uid : null;
      
      var html = '';
      for (var i = 0; i < msgs.length; i++) {
        var m = msgs[i];
        var isOwn = m.uid === uid;
        var dir = isOwn ? 'flex-direction:row-reverse;' : '';
        var align = isOwn ? 'right' : 'left';
        var bgGrad = isOwn ? '#58a6ff,#9b6cff' : '#ff6b6b,#ee5a24';
        var msgBg = isOwn ? 'var(--accent-muted)' : 'var(--bg-tertiary)';
        
        var safeName = U.sanitize(m.name || 'User');
        var safeText = U.sanitize(m.text || '');
        var initial = safeName.charAt(0).toUpperCase();
        
        html += '<div style="display:flex;gap:8px;padding:6px;' + dir + '">' +
          '<div style="width:28px;height:28px;border-radius:50%;background:linear-gradient(135deg,' + bgGrad + ');display:flex;align-items:center;justify-content:center;color:#fff;font-size:10px;font-weight:700;flex-shrink:0;">' + initial + '</div>' +
          '<div style="max-width:70%;">' +
            '<div style="font-size:9px;color:#58a6ff;font-weight:600;">' + safeName + '</div>' +
            '<div style="background:' + msgBg + ';padding:6px 10px;border-radius:10px;font-size:12px;color:var(--text-primary);">' + safeText + '</div>' +
            '<div style="font-size:8px;color:var(--text-muted);margin-top:2px;text-align:' + align + ';">' + U.timeAgo(m.timestamp) + '</div>' +
          '</div>' +
        '</div>';
      }
      
      container.innerHTML = html || '<div style="text-align:center;padding:20px;color:var(--text-muted);">No messages yet. Start the conversation!</div>';
      container.scrollTop = container.scrollHeight;
    },

    updatePresence: async function() {
      if (!window.FB || !window.FB.rtdb) { 
        var countEl = document.getElementById('chat-online-count');
        if (countEl) countEl.textContent = '0'; 
        return; 
      }
      
      try {
        var dbMod = await import("https://www.gstatic.com/firebasejs/10.12.0/firebase-database.js");
        dbMod.onValue(dbMod.ref(window.FB.rtdb, 'presence'), function(snap) {
          var users = [];
          snap.forEach(function(c) { 
            var d = c.val(); 
            if (d && d.online) users.push(d); 
          });
          
          var countEl = document.getElementById('chat-online-count');
          if (countEl) countEl.textContent = users.length;
          
          var usersEl = document.getElementById('chat-users');
          if (usersEl) {
            var html = '';
            for (var i = 0; i < users.length; i++) {
              var u = users[i];
              html += '<div style="display:flex;align-items:center;gap:6px;padding:3px 0;font-size:10px;">' +
                '<div style="position:relative;"><div style="width:22px;height:22px;border-radius:50%;background:linear-gradient(135deg,#58a6ff,#9b6cff);display:flex;align-items:center;justify-content:center;color:#fff;font-size:9px;font-weight:700;">' + (u.name || 'U')[0] + '</div><div style="position:absolute;bottom:0;right:0;width:6px;height:6px;background:#26a69a;border-radius:50%;border:2px solid var(--bg-secondary);"></div></div>' +
                '<span style="color:var(--text-secondary);">' + u.name + '</span>' +
              '</div>';
            }
            usersEl.innerHTML = html;
          }
        }, { onlyOnce: false });
      } catch(e) {}
    },

    sendMessage: async function() {
      var input = document.getElementById('chat-input');
      var text = input ? input.value.trim() : '';
      if (!text) return;
      if (!UserSystem.currentUser) { Toast.warning('Sign in to chat'); return; }
		      // ======== TIER CHECK ========
      if (!checkTierCount('chatMessages', UserSystem.chatCount, 'chatMessages')) return;
      // ===========================
      if (!UserSystem.canChat()) { UserSystem.checkPro('chat'); return; }
      
      if (window.FB && window.FB.rtdb) {
        try {
          var dbMod = await import("https://www.gstatic.com/firebasejs/10.12.0/firebase-database.js");
          await dbMod.push(dbMod.ref(window.FB.rtdb, 'chat/' + this.currentChannel), { 
            text: text, 
            uid: UserSystem.currentUser.uid, 
            name: UserSystem.currentUser.displayName, 
            timestamp: Date.now() 
          });
        } catch(e) {
          this.saveLocal(text);
        }
      } else {
        this.saveLocal(text);
      }
      
      UserSystem.incrementChat();
      if (input) { input.value = ''; input.focus(); }
    },
    
    saveLocal: function(text) {
      var key = 'tvp_chat_' + this.currentChannel;
      var msgs = [];
      try { msgs = JSON.parse(localStorage.getItem(key)) || []; } catch(e) {}
      msgs.push({ text: text, uid: UserSystem.currentUser.uid, name: UserSystem.currentUser.displayName, timestamp: Date.now() });
      if (msgs.length > 100) msgs = msgs.slice(-100);
      localStorage.setItem(key, JSON.stringify(msgs));
      this.renderMessages(msgs);
    }
  };

  // Setup channel clicks
  var channelBtns = document.querySelectorAll('.tvp-channel');
  for (var ci = 0; ci < channelBtns.length; ci++) {
    channelBtns[ci].addEventListener('click', function() {
      for (var cj = 0; cj < channelBtns.length; cj++) { 
        channelBtns[cj].style.color = 'var(--text-muted)'; 
        channelBtns[cj].style.borderBottomColor = 'transparent'; 
      }
      this.style.color = 'var(--accent-primary)'; 
      this.style.borderBottomColor = 'var(--accent-primary)';
      ChatSystem.subscribe(this.dataset.channel);
    });
  }

  // Setup chat input
  var chatInput = document.getElementById('chat-input');
  if (chatInput) {
    chatInput.addEventListener('keypress', function(e) { 
      if (e.key === 'Enter') ChatSystem.sendMessage(); 
    });
  }
  var chatSend = document.getElementById('chat-send');
  if (chatSend) {
    chatSend.addEventListener('click', function() { ChatSystem.sendMessage(); });
  }

