const ChartSharing = {
  init() {
    this.addShareButton();
    this.checkForSharedLink();
    console.log('✅ Chart sharing ready');
  },
  
  addShareButton() {
    setTimeout(() => {
      var headerActions = document.querySelector('.header-actions');
      if (!headerActions) return;
      
      // Desktop share button
      var shareBtn = document.createElement('button');
      shareBtn.id = 'share-chart-btn';
      shareBtn.className = 'action-btn';
      shareBtn.setAttribute('data-tooltip', 'Share Chart');
      shareBtn.innerHTML = '<i class="fas fa-share-alt"></i>';
      shareBtn.addEventListener('click', () => this.generateShareLink());
      
      var fullscreenBtn = document.getElementById('fullscreen-btn');
      if (fullscreenBtn) {
        headerActions.insertBefore(shareBtn, fullscreenBtn);
      } else {
        headerActions.appendChild(shareBtn);
      }
      
      // Mobile share in More sheet
      var sheetMore = document.querySelector('#sheet-more > div');
      if (sheetMore) {
        var mobBtn = document.createElement('button');
        mobBtn.className = 'mob-action-btn';
        mobBtn.innerHTML = '<i class="fas fa-share-alt"></i> Share Chart';
        mobBtn.addEventListener('click', () => this.generateShareLink());
        sheetMore.appendChild(mobBtn);
      }
    }, 1000);
  },
  
  generateShareLink() {
    var state = null;
    try {
      state = window.TV ? window.TV.getState() : null;
    } catch(e) {}
    
    if (!state || !state.symbol) {
      if (typeof Toast !== 'undefined') {
        Toast.error('Chart not ready. Please wait.');
      }
      return;
    }
    
    // Build share data
    var shareData = {
      v: '1',
      s: state.symbol,
      i: state.interval,
      t: state.chartType,
      inds: Array.from(state.activeIndicators || []),
      d: state.drawings ? state.drawings.length : 0
    };
    
    
    // Encode to base64
    var encoded = btoa(JSON.stringify(shareData));
    var url = window.location.origin + window.location.pathname + '?share=' + encoded;
    
    // Copy to clipboard
    if (navigator.clipboard) {
      navigator.clipboard.writeText(url).then(() => {
        if (typeof Toast !== 'undefined') {
          Toast.success('📋 Chart link copied! Share it with anyone.');
        }
      }).catch(() => {
        this.showShareDialog(url);
      });
    } else {
      this.showShareDialog(url);
    }
  },
  
  showShareDialog(url) {
    var dialog = document.createElement('div');
    dialog.className = 'modal-overlay';
    dialog.style.cssText = 'display:flex;align-items:center;justify-content:center;z-index:3000;';
    dialog.innerHTML = 
      '<div class="modal-container modal-md" style="max-width:500px;">' +
        '<div class="modal-header">' +
          '<h3>🔗 Share Chart</h3>' +
          '<button class="modal-close" onclick="this.closest(\'.modal-overlay\').remove()">✕</button>' +
        '</div>' +
        '<div class="modal-body" style="padding:16px;text-align:center;">' +
          '<p style="font-size:11px;color:var(--text-muted);margin-bottom:12px;">Copy this link to share your current chart setup:</p>' +
          '<div style="background:var(--bg-tertiary);padding:10px;border-radius:6px;font-family:monospace;font-size:10px;word-break:break-all;color:var(--text-primary);margin-bottom:12px;text-align:left;">' + url + '</div>' +
          '<button class="btn btn-primary btn-full" onclick="navigator.clipboard.writeText(\'' + url + '\');this.textContent=\'✅ Copied!\';setTimeout(()=>this.closest(\'.modal-overlay\').remove(),1000);">📋 Copy Link</button>' +
          '<p style="font-size:9px;color:var(--text-muted);margin-top:8px;">Anyone with this link will see the same symbol, timeframe, and indicators.</p>' +
        '</div>' +
      '</div>';
    
    document.body.appendChild(dialog);
    dialog.addEventListener('click', function(e) {
      if (e.target === dialog) dialog.remove();
    });
  },
  
  checkForSharedLink() {
    var params = new URLSearchParams(window.location.search);
    var shareData = params.get('share');
    
    if (!shareData) return;
    
    try {
      var data = JSON.parse(atob(shareData));
      
      if (data.s && window.TV) {
        window.TV.switchSymbol(data.s);
        
        setTimeout(function() {
          if (data.i && window.TV.switchInterval) {
            window.TV.switchInterval(data.i);
          }
        }, 500);
        
        setTimeout(function() {
          if (data.inds && data.inds.length > 0) {
            var state = window.TV.getState();
            if (state && state.activeIndicators) {
              data.inds.forEach(function(ind) {
                state.activeIndicators.add(ind);
              });
              if (typeof IndicatorEngine !== 'undefined') {
                IndicatorEngine.calculateAll();
              }
            }
          }
        }, 1500);
        
        if (typeof Toast !== 'undefined') {
          Toast.info('📊 Loaded shared chart: ' + data.s.replace('USDT', '/USDT'));
        }
      }
    } catch(e) {
      console.warn('Invalid share link:', e);
    }
}
};

